window.KTET_500_QUESTIONS = [{"id": 1, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "What is meant by growth?", "options": [{"value": "A", "text": "Change in social behaviour"}, {"value": "B", "text": "Increase in physical size and measurable dimensions"}, {"value": "C", "text": "Improvement in moral values"}, {"value": "D", "text": "Development of emotional intelligence"}], "answer": "B", "explanation": "Growth generally refers to quantitative physical changes, such as increases in height, weight and body size."}, {"id": 2, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which statement best describes development?", "options": [{"value": "A", "text": "Development refers only to physical changes."}, {"value": "B", "text": "Development stops after childhood."}, {"value": "C", "text": "Development includes changes in physical, cognitive, social and emotional functioning."}, {"value": "D", "text": "Development occurs at exactly the same rate in everyone."}], "answer": "C", "explanation": "Development is a broad process involving several interconnected areas of human functioning."}, {"id": 3, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which of the following is an example of cognitive development?", "options": [{"value": "A", "text": "Increase in height"}, {"value": "B", "text": "Improvement in problem-solving ability"}, {"value": "C", "text": "Increase in body weight"}, {"value": "D", "text": "Growth of fingernails"}], "answer": "B", "explanation": "Cognitive development involves thinking, reasoning, memory, attention and problem-solving."}, {"id": 4, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which two major factors influence human development?", "options": [{"value": "A", "text": "Examinations and textbooks"}, {"value": "B", "text": "Heredity and environment"}, {"value": "C", "text": "Rewards and punishments only"}, {"value": "D", "text": "Schools and examinations only"}], "answer": "B", "explanation": "Human development results from interactions between inherited characteristics and environmental experiences."}, {"id": 5, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "What is maturation?", "options": [{"value": "A", "text": "Learning through punishment"}, {"value": "B", "text": "Biological changes that contribute to readiness for particular abilities"}, {"value": "C", "text": "Memorising information"}, {"value": "D", "text": "Copying other people’s behaviour"}], "answer": "B", "explanation": "Maturation involves biological development that supports the emergence of particular abilities."}, {"id": 6, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which principle describes development from the head towards the feet?", "options": [{"value": "A", "text": "Proximodistal principle"}, {"value": "B", "text": "Cephalocaudal principle"}, {"value": "C", "text": "Reinforcement principle"}, {"value": "D", "text": "Trial-and-error principle"}], "answer": "B", "explanation": "Cephalocaudal development generally progresses from the head towards the lower parts of the body."}, {"id": 7, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which principle describes development from the centre of the body towards the extremities?", "options": [{"value": "A", "text": "Cephalocaudal principle"}, {"value": "B", "text": "Proximodistal principle"}, {"value": "C", "text": "Conditioning principle"}, {"value": "D", "text": "Conservation principle"}], "answer": "B", "explanation": "Proximodistal development generally progresses from the body’s central regions towards the hands and fingers."}, {"id": 8, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which of the following is an example of fine motor development?", "options": [{"value": "A", "text": "Running"}, {"value": "B", "text": "Jumping"}, {"value": "C", "text": "Writing with a pencil"}, {"value": "D", "text": "Climbing stairs"}], "answer": "C", "explanation": "Fine motor skills involve small muscle movements and coordination, particularly of the hands and fingers."}, {"id": 9, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which of the following is an example of gross motor development?", "options": [{"value": "A", "text": "Threading a needle"}, {"value": "B", "text": "Buttoning a shirt"}, {"value": "C", "text": "Writing a letter"}, {"value": "D", "text": "Jumping and running"}], "answer": "D", "explanation": "Gross motor skills involve larger muscle groups and whole-body movements."}, {"id": 10, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which statement about individual differences is correct?", "options": [{"value": "A", "text": "All children learn at the same speed."}, {"value": "B", "text": "Children differ in abilities, interests and learning needs."}, {"value": "C", "text": "Individual differences occur only in intelligence."}, {"value": "D", "text": "Teachers should ignore differences between learners."}], "answer": "B", "explanation": "Individual differences require teachers to recognise varied abilities, experiences, interests and learning requirements."}, {"id": 11, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which of the following best represents social development?", "options": [{"value": "A", "text": "Increasing body height"}, {"value": "B", "text": "Learning to cooperate with classmates"}, {"value": "C", "text": "Improving eyesight"}, {"value": "D", "text": "Increasing body weight"}], "answer": "B", "explanation": "Social development includes cooperation, communication, relationship-building and learning social expectations."}, {"id": 12, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Emotional development involves:", "options": [{"value": "A", "text": "Increasing physical strength only"}, {"value": "B", "text": "Memorising facts"}, {"value": "C", "text": "Recognising and regulating emotions"}, {"value": "D", "text": "Learning mathematical formulas only"}], "answer": "C", "explanation": "Emotional development includes recognising feelings, expressing them appropriately and gradually developing emotional regulation."}, {"id": 13, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Why should teachers understand child development?", "options": [{"value": "A", "text": "To compare students publicly"}, {"value": "B", "text": "To label children permanently"}, {"value": "C", "text": "To plan suitable learning experiences"}, {"value": "D", "text": "To avoid changing teaching methods"}], "answer": "C", "explanation": "Understanding development helps teachers select age-appropriate activities and provide suitable support."}, {"id": 14, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "What is meant by readiness to learn?", "options": [{"value": "A", "text": "The learner’s preparedness to acquire a particular skill or concept"}, {"value": "B", "text": "The ability to memorise an entire textbook"}, {"value": "C", "text": "The absence of individual differences"}, {"value": "D", "text": "The ability to avoid examinations"}], "answer": "A", "explanation": "Readiness involves developmental, experiential and contextual factors that influence learning."}, {"id": 15, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Child Development", "question": "Which environment best supports healthy child development?", "options": [{"value": "A", "text": "An environment based on fear"}, {"value": "B", "text": "An environment that discourages questions"}, {"value": "C", "text": "A safe, supportive and stimulating environment"}, {"value": "D", "text": "An environment that constantly compares children"}], "answer": "C", "explanation": "Supportive environments encourage exploration, participation, confidence and learning."}, {"id": 16, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "Who proposed the theory of cognitive development commonly associated with four developmental stages?", "options": [{"value": "A", "text": "B. F. Skinner"}, {"value": "B", "text": "Jean Piaget"}, {"value": "C", "text": "Ivan Pavlov"}, {"value": "D", "text": "Albert Bandura"}], "answer": "B", "explanation": "Jean Piaget proposed a theory explaining how children’s thinking develops through different stages."}, {"id": 17, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "Which is the first stage in Piaget’s theory of cognitive development?", "options": [{"value": "A", "text": "Preoperational stage"}, {"value": "B", "text": "Concrete operational stage"}, {"value": "C", "text": "Sensorimotor stage"}, {"value": "D", "text": "Formal operational stage"}], "answer": "C", "explanation": "The sensorimotor stage generally extends from birth to approximately two years."}, {"id": 18, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "Which stage is generally associated with symbolic thinking and egocentrism?", "options": [{"value": "A", "text": "Sensorimotor stage"}, {"value": "B", "text": "Preoperational stage"}, {"value": "C", "text": "Concrete operational stage"}, {"value": "D", "text": "Formal operational stage"}], "answer": "B", "explanation": "During the preoperational stage, children increasingly use symbols and language but may find it difficult to consider another person’s perspective."}, {"id": 19, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "Logical reasoning about concrete objects is characteristic of which stage?", "options": [{"value": "A", "text": "Sensorimotor stage"}, {"value": "B", "text": "Preoperational stage"}, {"value": "C", "text": "Concrete operational stage"}, {"value": "D", "text": "Prenatal stage"}], "answer": "C", "explanation": "Children generally develop logical reasoning about concrete situations during the concrete operational stage."}, {"id": 20, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "Abstract and hypothetical reasoning becomes more developed during which stage?", "options": [{"value": "A", "text": "Sensorimotor stage"}, {"value": "B", "text": "Preoperational stage"}, {"value": "C", "text": "Concrete operational stage"}, {"value": "D", "text": "Formal operational stage"}], "answer": "D", "explanation": "Piaget associated the formal operational stage with increasingly abstract and hypothetical reasoning."}, {"id": 21, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "What is assimilation in Piaget’s theory?", "options": [{"value": "A", "text": "Changing an existing schema to accommodate new information"}, {"value": "B", "text": "Interpreting new experiences using existing schemas"}, {"value": "C", "text": "Forgetting previously learned information"}, {"value": "D", "text": "Learning only through punishment"}], "answer": "B", "explanation": "Assimilation occurs when new experiences are understood through existing mental frameworks."}, {"id": 22, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "What is accommodation?", "options": [{"value": "A", "text": "Modifying existing schemas or creating new ones in response to experience"}, {"value": "B", "text": "Ignoring new information"}, {"value": "C", "text": "Repeating information without understanding"}, {"value": "D", "text": "Learning through rewards alone"}], "answer": "A", "explanation": "Accommodation occurs when existing mental frameworks need to change to account for new information."}, {"id": 23, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "A child calls every four-legged animal a dog. After learning about cats, the child changes their understanding. Which process is illustrated by this change?", "options": [{"value": "A", "text": "Reinforcement"}, {"value": "B", "text": "Accommodation"}, {"value": "C", "text": "Classical conditioning"}, {"value": "D", "text": "Rote memorisation"}], "answer": "B", "explanation": "The child modifies an existing mental category to distinguish dogs from cats."}, {"id": 24, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "According to Piaget, children are best understood as:", "options": [{"value": "A", "text": "Passive receivers of information"}, {"value": "B", "text": "Active constructors of knowledge"}, {"value": "C", "text": "Learners who cannot learn through experience"}, {"value": "D", "text": "Individuals who learn only through rewards"}], "answer": "B", "explanation": "Piaget emphasised children’s active exploration and construction of understanding."}, {"id": 25, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Piaget’S Cognitive Development Theory", "question": "Which classroom practice is most consistent with Piaget’s theory?", "options": [{"value": "A", "text": "Asking children to memorise every answer"}, {"value": "B", "text": "Preventing students from handling materials"}, {"value": "C", "text": "Providing activities that encourage exploration and discovery"}, {"value": "D", "text": "Giving identical tasks regardless of developmental readiness"}], "answer": "C", "explanation": "Active learning experiences allow children to explore, test ideas and develop understanding."}, {"id": 26, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Vygotsky And Social Learning", "question": "Who is associated with the sociocultural theory of cognitive development?", "options": [{"value": "A", "text": "Jean Piaget"}, {"value": "B", "text": "Lev Vygotsky"}, {"value": "C", "text": "Ivan Pavlov"}, {"value": "D", "text": "Edward Thorndike"}], "answer": "B", "explanation": "Vygotsky emphasised the role of social interaction, language and culture in cognitive development."}, {"id": 27, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Vygotsky And Social Learning", "question": "What does the Zone of Proximal Development (ZPD) describe?", "options": [{"value": "A", "text": "Tasks that a learner can never perform"}, {"value": "B", "text": "The difference between independent performance and performance possible with suitable assistance"}, {"value": "C", "text": "The physical growth rate of a learner"}, {"value": "D", "text": "A fixed measure of intelligence"}], "answer": "B", "explanation": "The ZPD identifies learning that becomes possible when a learner receives appropriate guidance."}, {"id": 28, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Vygotsky And Social Learning", "question": "What is scaffolding in education?", "options": [{"value": "A", "text": "Giving every answer directly to the learner"}, {"value": "B", "text": "Preventing students from working independently"}, {"value": "C", "text": "Providing temporary support that is gradually withdrawn"}, {"value": "D", "text": "Using punishment as the main teaching strategy"}], "answer": "C", "explanation": "Scaffolding supports learners while they develop the competence needed to complete tasks independently."}, {"id": 29, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Vygotsky And Social Learning", "question": "Which classroom activity best reflects Vygotsky’s approach?", "options": [{"value": "A", "text": "Students are forbidden from discussing their ideas."}, {"value": "B", "text": "Students collaborate and receive guidance from a teacher."}, {"value": "C", "text": "Students memorise information without interaction."}, {"value": "D", "text": "Students are discouraged from asking questions."}], "answer": "B", "explanation": "Vygotsky emphasised social interaction and support from more knowledgeable individuals."}, {"id": 30, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Vygotsky And Social Learning", "question": "According to Vygotsky, which factor plays an important role in cognitive development?", "options": [{"value": "A", "text": "Social interaction and cultural experiences"}, {"value": "B", "text": "Physical height alone"}, {"value": "C", "text": "Eye colour"}, {"value": "D", "text": "Memorisation without interaction"}], "answer": "A", "explanation": "Vygotsky viewed learning as a socially and culturally mediated process."}, {"id": 31, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "Classical conditioning is associated with:", "options": [{"value": "A", "text": "Jean Piaget"}, {"value": "B", "text": "Ivan Pavlov"}, {"value": "C", "text": "Albert Bandura"}, {"value": "D", "text": "Abraham Maslow"}], "answer": "B", "explanation": "Pavlov’s research demonstrated how organisms can learn associations between stimuli."}, {"id": 32, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "Operant conditioning is most closely associated with:", "options": [{"value": "A", "text": "B. F. Skinner"}, {"value": "B", "text": "Lev Vygotsky"}, {"value": "C", "text": "Lawrence Kohlberg"}, {"value": "D", "text": "Jean Piaget"}], "answer": "A", "explanation": "Skinner studied how consequences influence the likelihood of behaviour occurring again."}, {"id": 33, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "Who is associated with social learning theory?", "options": [{"value": "A", "text": "Ivan Pavlov"}, {"value": "B", "text": "Albert Bandura"}, {"value": "C", "text": "Edward Thorndike"}, {"value": "D", "text": "Sigmund Freud"}], "answer": "B", "explanation": "Bandura emphasised observational learning and the influence of models."}, {"id": 34, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "Who is associated with the law of effect?", "options": [{"value": "A", "text": "Edward Thorndike"}, {"value": "B", "text": "Howard Gardner"}, {"value": "C", "text": "Jean Piaget"}, {"value": "D", "text": "Lev Vygotsky"}], "answer": "A", "explanation": "Thorndike’s law of effect explains how satisfying consequences can strengthen responses."}, {"id": 35, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "In classical conditioning, learning primarily involves:", "options": [{"value": "A", "text": "Association between stimuli"}, {"value": "B", "text": "Abstract reasoning alone"}, {"value": "C", "text": "Moral judgement"}, {"value": "D", "text": "Physical growth"}], "answer": "A", "explanation": "Classical conditioning occurs when a previously neutral stimulus becomes associated with a stimulus that naturally elicits a response."}, {"id": 36, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "In operant conditioning, behaviour is influenced by:", "options": [{"value": "A", "text": "Consequences that follow behaviour"}, {"value": "B", "text": "Body height alone"}, {"value": "C", "text": "Eye colour"}, {"value": "D", "text": "Heredity alone"}], "answer": "A", "explanation": "Reinforcement and punishment can influence the future likelihood of a behaviour."}, {"id": 37, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "What is positive reinforcement?", "options": [{"value": "A", "text": "Adding a consequence that increases a behaviour"}, {"value": "B", "text": "Removing a desirable consequence to reduce a behaviour"}, {"value": "C", "text": "Ignoring all classroom behaviour"}, {"value": "D", "text": "Punishing every mistake"}], "answer": "A", "explanation": "Positive reinforcement involves presenting a consequence that increases the likelihood of a behaviour recurring."}, {"id": 38, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "A teacher praises a student for helping a classmate. The student begins helping classmates more often. This illustrates:", "options": [{"value": "A", "text": "Accommodation"}, {"value": "B", "text": "Positive reinforcement"}, {"value": "C", "text": "Classical extinction only"}, {"value": "D", "text": "Maturation"}], "answer": "B", "explanation": "Praise can act as a reinforcer when it increases the likelihood of the desired behaviour."}, {"id": 39, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "Which is an example of observational learning?", "options": [{"value": "A", "text": "A student learns a laboratory procedure by watching a demonstration."}, {"value": "B", "text": "A student grows taller."}, {"value": "C", "text": "A student changes eye colour."}, {"value": "D", "text": "A student develops stronger muscles without practice."}], "answer": "A", "explanation": "Observational learning occurs when a person acquires knowledge or behaviour by observing others."}, {"id": 40, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Learning Theories", "question": "Which approach emphasises learners actively constructing knowledge?", "options": [{"value": "A", "text": "Constructivism"}, {"value": "B", "text": "Passive reception alone"}, {"value": "C", "text": "Punishment-based teaching"}, {"value": "D", "text": "Memorisation without understanding"}], "answer": "A", "explanation": "Constructivism emphasises learners’ active role in making sense of experiences and connecting ideas."}, {"id": 41, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "What is intrinsic motivation?", "options": [{"value": "A", "text": "Studying only to receive money"}, {"value": "B", "text": "Learning because an activity is interesting or satisfying"}, {"value": "C", "text": "Studying only to avoid punishment"}, {"value": "D", "text": "Completing work only because of a threat"}], "answer": "B", "explanation": "Intrinsic motivation comes from interest, curiosity or personal satisfaction."}, {"id": 42, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Which is an example of extrinsic motivation?", "options": [{"value": "A", "text": "Reading because one enjoys a story"}, {"value": "B", "text": "Exploring a topic out of curiosity"}, {"value": "C", "text": "Completing an assignment to earn a reward"}, {"value": "D", "text": "Solving puzzles for enjoyment"}], "answer": "C", "explanation": "Extrinsic motivation involves external outcomes such as rewards, recognition or avoiding penalties."}, {"id": 43, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Who proposed the hierarchy of needs?", "options": [{"value": "A", "text": "Abraham Maslow"}, {"value": "B", "text": "Ivan Pavlov"}, {"value": "C", "text": "B. F. Skinner"}, {"value": "D", "text": "Edward Thorndike"}], "answer": "A", "explanation": "Maslow proposed a model of human needs, commonly represented as a hierarchy ranging from physiological needs to self-actualisation."}, {"id": 44, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Which of the following is a physiological need?", "options": [{"value": "A", "text": "Social recognition"}, {"value": "B", "text": "Hunger"}, {"value": "C", "text": "Self-actualisation"}, {"value": "D", "text": "Achievement status"}], "answer": "B", "explanation": "Physiological needs include basic requirements such as food, water and sleep."}, {"id": 45, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Which classroom practice is most likely to encourage intrinsic motivation?", "options": [{"value": "A", "text": "Threatening students with punishment"}, {"value": "B", "text": "Giving rewards for every action"}, {"value": "C", "text": "Providing meaningful choices and opportunities to explore interests"}, {"value": "D", "text": "Comparing every student publicly"}], "answer": "C", "explanation": "Autonomy, meaningful tasks and opportunities to explore can support students’ internal motivation."}, {"id": 46, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Which statement about intelligence is most appropriate?", "options": [{"value": "A", "text": "Intelligence can be fully understood through one classroom test."}, {"value": "B", "text": "Intelligence is identical to academic marks."}, {"value": "C", "text": "Intelligence involves abilities that may be expressed in different ways."}, {"value": "D", "text": "Intelligence cannot develop through learning experiences."}], "answer": "C", "explanation": "Human abilities are complex, and a single test or academic score cannot capture every aspect of a person’s capabilities."}, {"id": 47, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Who proposed the theory of multiple intelligences?", "options": [{"value": "A", "text": "Howard Gardner"}, {"value": "B", "text": "Ivan Pavlov"}, {"value": "C", "text": "B. F. Skinner"}, {"value": "D", "text": "Lawrence Kohlberg"}], "answer": "A", "explanation": "Gardner proposed that intelligence can be understood through multiple forms of ability. His theory remains influential, although its empirical support and application are debated."}, {"id": 48, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "What is metacognition?", "options": [{"value": "A", "text": "Thinking about and regulating one’s own thinking"}, {"value": "B", "text": "Physical growth during adolescence"}, {"value": "C", "text": "Memorising without reflection"}, {"value": "D", "text": "Learning only through imitation"}], "answer": "A", "explanation": "Metacognition involves planning, monitoring and evaluating one’s own learning processes."}, {"id": 49, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "Which classroom practice best promotes self-regulated learning?", "options": [{"value": "A", "text": "Asking students to memorise without reflection"}, {"value": "B", "text": "Encouraging students to set goals and monitor their progress"}, {"value": "C", "text": "Preventing students from checking their work"}, {"value": "D", "text": "Giving no feedback"}], "answer": "B", "explanation": "Self-regulated learners plan their learning, monitor understanding and adjust strategies when necessary."}, {"id": 50, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Motivation And Intelligence", "question": "What is transfer of learning?", "options": [{"value": "A", "text": "Forgetting an old concept"}, {"value": "B", "text": "Applying previously learned knowledge or skills in a new situation"}, {"value": "C", "text": "Repeating the same answer without understanding"}, {"value": "D", "text": "Copying another student’s work"}], "answer": "B", "explanation": "Transfer occurs when learning from one situation influences performance in another."}, {"id": 51, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Inclusive Education", "question": "What is the main principle of inclusive education?", "options": [{"value": "A", "text": "Teaching only high-achieving students"}, {"value": "B", "text": "Separating all students with disabilities"}, {"value": "C", "text": "Enabling diverse learners to participate meaningfully in education"}, {"value": "D", "text": "Using identical teaching methods regardless of need"}], "answer": "C", "explanation": "Inclusive education aims to reduce barriers and provide meaningful participation and learning opportunities for all students."}, {"id": 52, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Inclusive Education", "question": "What does Universal Design for Learning (UDL) encourage?", "options": [{"value": "A", "text": "One method of teaching for every student"}, {"value": "B", "text": "Multiple ways to engage, represent information and demonstrate learning"}, {"value": "C", "text": "Excluding learners who need additional support"}, {"value": "D", "text": "Using examinations as the only learning activity"}], "answer": "B", "explanation": "UDL encourages flexible learning environments that anticipate learner variability."}, {"id": 53, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Inclusive Education", "question": "What is an Individualised Education Programme (IEP)?", "options": [{"value": "A", "text": "A school timetable for all teachers"}, {"value": "B", "text": "An individualised educational plan for a learner who requires it"}, {"value": "C", "text": "A national examination paper"}, {"value": "D", "text": "A common textbook for every student"}], "answer": "B", "explanation": "An IEP identifies individual educational goals, appropriate support and methods for monitoring progress where such a plan is applicable."}, {"id": 54, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Inclusive Education", "question": "Which is an example of a reasonable educational accommodation?", "options": [{"value": "A", "text": "Denying a learner access to examinations"}, {"value": "B", "text": "Providing an appropriate accessible format for learning materials"}, {"value": "C", "text": "Excluding a learner from classroom activities"}, {"value": "D", "text": "Refusing to adapt an inaccessible resource"}], "answer": "B", "explanation": "Appropriate accommodations can reduce barriers and help learners access educational activities."}, {"id": 55, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Inclusive Education", "question": "What should a teacher do when a learner experiences difficulty with a classroom task?", "options": [{"value": "A", "text": "Assume the learner cannot learn"}, {"value": "B", "text": "Publicly criticise the learner"}, {"value": "C", "text": "Identify barriers and provide appropriate support"}, {"value": "D", "text": "Permanently remove the learner from classroom activities"}], "answer": "C", "explanation": "Teachers should identify learning needs, adapt teaching where appropriate and provide suitable support."}, {"id": 56, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Teaching Methods", "question": "Which approach places learners actively at the centre of the learning process?", "options": [{"value": "A", "text": "Learner-centred teaching"}, {"value": "B", "text": "Teacher monologue in every lesson"}, {"value": "C", "text": "Punishment-based instruction"}, {"value": "D", "text": "Rote memorisation alone"}], "answer": "A", "explanation": "Learner-centred teaching considers students’ needs, prior knowledge, participation and learning goals."}, {"id": 57, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Teaching Methods", "question": "What is experiential learning?", "options": [{"value": "A", "text": "Learning only by memorising definitions"}, {"value": "B", "text": "Learning through experience and reflection"}, {"value": "C", "text": "Learning without participation"}, {"value": "D", "text": "Learning only through examinations"}], "answer": "B", "explanation": "Experiential learning uses experiences and reflection to develop understanding."}, {"id": 58, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Teaching Methods", "question": "Which teaching method is particularly suitable for developing collaborative skills?", "options": [{"value": "A", "text": "Cooperative learning"}, {"value": "B", "text": "Silent copying only"}, {"value": "C", "text": "Individual memorisation in every activity"}, {"value": "D", "text": "Public ranking without discussion"}], "answer": "A", "explanation": "Cooperative learning structures interaction so that students work together towards learning goals."}, {"id": 59, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Teaching Methods", "question": "What is the main purpose of classroom discussion?", "options": [{"value": "A", "text": "To prevent students from expressing ideas"}, {"value": "B", "text": "To encourage the exchange and examination of ideas"}, {"value": "C", "text": "To eliminate questioning"}, {"value": "D", "text": "To ensure that only the teacher speaks"}], "answer": "B", "explanation": "Discussion can develop communication, reasoning and deeper understanding when appropriately facilitated."}, {"id": 60, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Teaching Methods", "question": "Which activity best supports problem-solving skills?", "options": [{"value": "A", "text": "Copying a solution without examining it"}, {"value": "B", "text": "Memorising an answer without context"}, {"value": "C", "text": "Analysing a real-life problem and evaluating possible solutions"}, {"value": "D", "text": "Avoiding unfamiliar tasks"}], "answer": "C", "explanation": "Problem-solving requires learners to identify issues, consider alternatives and evaluate possible outcomes."}, {"id": 61, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Assessment And Evaluation", "question": "What is formative assessment primarily used for?", "options": [{"value": "A", "text": "Monitoring learning and improving instruction during the learning process"}, {"value": "B", "text": "Ranking students only at the end of the year"}, {"value": "C", "text": "Replacing all classroom activities"}, {"value": "D", "text": "Determining school buildings’ quality"}], "answer": "A", "explanation": "Formative assessment provides information that teachers and students can use to improve ongoing learning."}, {"id": 62, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Assessment And Evaluation", "question": "What is summative assessment generally used for?", "options": [{"value": "A", "text": "Identifying every learning difficulty before instruction"}, {"value": "B", "text": "Evaluating achievement at the end of a unit, course or instructional period"}, {"value": "C", "text": "Replacing teaching with discussion"}, {"value": "D", "text": "Observing playground behaviour only"}], "answer": "B", "explanation": "Summative assessment evaluates learning outcomes after a defined period of instruction."}, {"id": 63, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Assessment And Evaluation", "question": "What is diagnostic assessment designed to identify?", "options": [{"value": "A", "text": "Only final grades"}, {"value": "B", "text": "Learning strengths, difficulties and specific misconceptions"}, {"value": "C", "text": "Students’ physical height"}, {"value": "D", "text": "Teachers’ salaries"}], "answer": "B", "explanation": "Diagnostic assessment helps identify learning needs so that suitable instructional support can be planned."}, {"id": 64, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Assessment And Evaluation", "question": "What is the purpose of feedback in learning?", "options": [{"value": "A", "text": "To discourage students from trying"}, {"value": "B", "text": "To identify mistakes only"}, {"value": "C", "text": "To help learners understand progress and improve performance"}, {"value": "D", "text": "To replace instruction completely"}], "answer": "C", "explanation": "Useful feedback identifies what has been done well and what can be improved."}, {"id": 65, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Assessment And Evaluation", "question": "Which assessment method can provide evidence of a student’s practical skills?", "options": [{"value": "A", "text": "Practical performance task"}, {"value": "B", "text": "Attendance record alone"}, {"value": "C", "text": "School timetable"}, {"value": "D", "text": "Textbook page count"}], "answer": "A", "explanation": "Performance-based assessment allows learners to demonstrate skills through relevant tasks."}, {"id": 66, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Classroom Management And Learner Support", "question": "Which is an example of positive classroom management?", "options": [{"value": "A", "text": "Establishing clear expectations and supportive routines"}, {"value": "B", "text": "Using humiliation to control behaviour"}, {"value": "C", "text": "Ignoring all student needs"}, {"value": "D", "text": "Punishing every mistake"}], "answer": "A", "explanation": "Clear expectations, predictable routines and positive relationships help create an environment conducive to learning."}, {"id": 67, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Classroom Management And Learner Support", "question": "A student repeatedly struggles to understand a mathematics concept. What should the teacher do first?", "options": [{"value": "A", "text": "Label the student as weak"}, {"value": "B", "text": "Immediately stop teaching the student"}, {"value": "C", "text": "Identify the specific difficulty and assess the student’s understanding"}, {"value": "D", "text": "Compare the student publicly with classmates"}], "answer": "C", "explanation": "Identifying the source of difficulty helps the teacher plan appropriate support or remedial instruction."}, {"id": 68, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Classroom Management And Learner Support", "question": "What is remedial teaching?", "options": [{"value": "A", "text": "Teaching designed to address identified learning difficulties"}, {"value": "B", "text": "Teaching intended only for the highest achievers"}, {"value": "C", "text": "Replacing all classroom assessment"}, {"value": "D", "text": "Giving identical additional homework to every learner"}], "answer": "A", "explanation": "Remedial teaching provides targeted support based on identified learning needs."}, {"id": 69, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Classroom Management And Learner Support", "question": "Which classroom practice best supports learner confidence?", "options": [{"value": "A", "text": "Publicly ridiculing mistakes"}, {"value": "B", "text": "Providing constructive feedback and opportunities to improve"}, {"value": "C", "text": "Comparing every student with the highest achiever"}, {"value": "D", "text": "Discouraging questions"}], "answer": "B", "explanation": "Constructive feedback and opportunities to succeed can support confidence and persistence."}, {"id": 70, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Classroom Management And Learner Support", "question": "What should a teacher do when students have different learning needs?", "options": [{"value": "A", "text": "Ignore the differences"}, {"value": "B", "text": "Teach only students who learn quickly"}, {"value": "C", "text": "Provide appropriate flexibility, support and varied learning opportunities"}, {"value": "D", "text": "Use public ranking as the only teaching strategy"}], "answer": "C", "explanation": "Responsive teaching adapts instruction to learner needs while maintaining meaningful learning goals."}, {"id": 71, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A teacher asks students to investigate why some objects float while others sink. Which approach is being encouraged?", "options": [{"value": "A", "text": "Inquiry-based learning"}, {"value": "B", "text": "Rote memorisation only"}, {"value": "C", "text": "Punishment-based learning"}, {"value": "D", "text": "Passive copying"}], "answer": "A", "explanation": "Inquiry-based learning encourages learners to ask questions, investigate evidence and develop explanations."}, {"id": 72, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A teacher connects a new lesson to students’ previous experiences. Which principle is being applied?", "options": [{"value": "A", "text": "Learning without context"}, {"value": "B", "text": "Building on prior knowledge"}, {"value": "C", "text": "Avoiding meaningful connections"}, {"value": "D", "text": "Memorisation without understanding"}], "answer": "B", "explanation": "Prior knowledge provides a foundation for understanding new concepts."}, {"id": 73, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "Students work in groups to design a solution to a local environmental problem. Which approach is most evident?", "options": [{"value": "A", "text": "Collaborative problem-solving"}, {"value": "B", "text": "Isolated memorisation"}, {"value": "C", "text": "Passive listening"}, {"value": "D", "text": "Punishment-based instruction"}], "answer": "A", "explanation": "The activity combines group cooperation with the analysis of a real-world problem."}, {"id": 74, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A teacher offers students different ways to demonstrate understanding, such as a written explanation, an oral presentation or a suitable visual model. Which approach does this reflect?", "options": [{"value": "A", "text": "Flexible assessment"}, {"value": "B", "text": "Uniform assessment without adaptation"}, {"value": "C", "text": "Exclusion"}, {"value": "D", "text": "Rote learning alone"}], "answer": "A", "explanation": "Multiple ways of demonstrating learning can help make assessment more accessible while preserving the intended learning outcomes."}, {"id": 75, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A student makes an incorrect prediction during a science experiment. What is the most appropriate teacher response?", "options": [{"value": "A", "text": "Ridicule the student"}, {"value": "B", "text": "Ask the student to examine the evidence and reconsider the prediction"}, {"value": "C", "text": "Prohibit further questions"}, {"value": "D", "text": "Give the student a failing mark without feedback"}], "answer": "B", "explanation": "Examining evidence and revising explanations are important parts of scientific inquiry."}, {"id": 76, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A learner understands a concept after receiving hints from a teacher but cannot yet complete the task independently. Which concept is most relevant?", "options": [{"value": "A", "text": "Zone of Proximal Development"}, {"value": "B", "text": "Physical maturation only"}, {"value": "C", "text": "Classical conditioning only"}, {"value": "D", "text": "Summative assessment"}], "answer": "A", "explanation": "The ZPD concerns tasks a learner can accomplish with appropriate guidance but cannot yet perform independently."}, {"id": 77, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A teacher gradually reduces hints as a student becomes more capable of solving problems independently. What is this called?", "options": [{"value": "A", "text": "Scaffolding"}, {"value": "B", "text": "Punishment"}, {"value": "C", "text": "Rote memorisation"}, {"value": "D", "text": "Labelling"}], "answer": "A", "explanation": "Scaffolding provides temporary support and gradually transfers responsibility to the learner."}, {"id": 78, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "Students maintain a learning journal in which they record what they understand and which topics need more practice. This primarily supports:", "options": [{"value": "A", "text": "Metacognition and self-monitoring"}, {"value": "B", "text": "Physical development"}, {"value": "C", "text": "Classical conditioning only"}, {"value": "D", "text": "Public ranking"}], "answer": "A", "explanation": "Reflecting on understanding and identifying learning needs helps students monitor their own learning."}, {"id": 79, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A teacher uses a short quiz during a lesson and adjusts the next activity based on the results. This is an example of:", "options": [{"value": "A", "text": "Formative assessment"}, {"value": "B", "text": "Summative assessment only"}, {"value": "C", "text": "School inspection"}, {"value": "D", "text": "Standardised final grading only"}], "answer": "A", "explanation": "The quiz provides information used to adapt instruction while learning is taking place."}, {"id": 80, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Application-Based Questions", "question": "A teacher notices that several students have misunderstood the same concept. What is the most appropriate response?", "options": [{"value": "A", "text": "Ignore the misunderstanding"}, {"value": "B", "text": "Repeat the same explanation indefinitely without checking understanding"}, {"value": "C", "text": "Revisit the concept using a different explanation or activity"}, {"value": "D", "text": "Blame the students for not listening"}], "answer": "C", "explanation": "When misconceptions are widespread, teachers should reconsider their instructional approach and check whether the new explanation helps."}, {"id": 81, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "What is constructivism?", "options": [{"value": "A", "text": "The view that learners actively construct understanding"}, {"value": "B", "text": "The view that learners must never ask questions"}, {"value": "C", "text": "The belief that learning occurs only through punishment"}, {"value": "D", "text": "The belief that previous knowledge is irrelevant"}], "answer": "A", "explanation": "Constructivist approaches emphasise the learner’s active role in making meaning from experience and information."}, {"id": 82, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "What is the main purpose of cooperative learning?", "options": [{"value": "A", "text": "To encourage competition at all times"}, {"value": "B", "text": "To enable students to work together towards learning goals"}, {"value": "C", "text": "To eliminate interaction between students"}, {"value": "D", "text": "To replace all teacher guidance"}], "answer": "B", "explanation": "Cooperative learning uses structured collaboration to support learning and social interaction."}, {"id": 83, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "Which of the following is an example of critical thinking?", "options": [{"value": "A", "text": "Accepting every statement without examination"}, {"value": "B", "text": "Memorising an answer without understanding"}, {"value": "C", "text": "Examining evidence before reaching a conclusion"}, {"value": "D", "text": "Copying another person’s opinion"}], "answer": "C", "explanation": "Critical thinking involves evaluating evidence, analysing arguments and reaching reasoned conclusions."}, {"id": 84, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "Which is the best example of creativity in learning?", "options": [{"value": "A", "text": "Reproducing a textbook paragraph word for word"}, {"value": "B", "text": "Developing an original solution to a problem"}, {"value": "C", "text": "Avoiding all unfamiliar tasks"}, {"value": "D", "text": "Copying another student’s project"}], "answer": "B", "explanation": "Creativity involves generating ideas or approaches that are novel and appropriate to the task."}, {"id": 85, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "What is meant by learner autonomy?", "options": [{"value": "A", "text": "The learner’s ability to take an active role in managing learning"}, {"value": "B", "text": "The teacher’s responsibility to make every decision"}, {"value": "C", "text": "The complete absence of learning goals"}, {"value": "D", "text": "The prohibition of student questions"}], "answer": "A", "explanation": "Learner autonomy includes taking responsibility for goals, strategies and progress, with suitable support."}, {"id": 86, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "What is peer learning?", "options": [{"value": "A", "text": "Learning through interaction with fellow learners"}, {"value": "B", "text": "Learning only from textbooks"}, {"value": "C", "text": "Learning without communication"}, {"value": "D", "text": "Learning exclusively through examinations"}], "answer": "A", "explanation": "Peer learning allows students to explain ideas, exchange feedback and learn collaboratively."}, {"id": 87, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "Which practice best supports reflective teaching?", "options": [{"value": "A", "text": "Using the same lesson plan regardless of results"}, {"value": "B", "text": "Reviewing teaching outcomes and adjusting future lessons"}, {"value": "C", "text": "Avoiding feedback from students"}, {"value": "D", "text": "Ignoring learning difficulties"}], "answer": "B", "explanation": "Reflective teaching involves examining instructional decisions and their effects on learning."}, {"id": 88, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "Which statement best describes differentiated instruction?", "options": [{"value": "A", "text": "Every student must always complete identical tasks in identical ways."}, {"value": "B", "text": "Teaching can be adapted to learners’ readiness, interests and needs."}, {"value": "C", "text": "Only struggling learners should participate in lessons."}, {"value": "D", "text": "Students should never work collaboratively."}], "answer": "B", "explanation": "Differentiation involves making appropriate adjustments to instruction while maintaining meaningful educational goals."}, {"id": 89, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "Which of the following best describes a learning objective?", "options": [{"value": "A", "text": "A clear statement of what learners should know or be able to do"}, {"value": "B", "text": "A list of classroom decorations"}, {"value": "C", "text": "A teacher’s personal biography"}, {"value": "D", "text": "A list of students’ home addresses"}], "answer": "A", "explanation": "Learning objectives guide instruction and help determine suitable learning activities and assessments."}, {"id": 90, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Important Educational Concepts", "question": "What is the purpose of a lesson plan?", "options": [{"value": "A", "text": "To eliminate the need to assess learning"}, {"value": "B", "text": "To organise learning objectives, activities, resources and assessment"}, {"value": "C", "text": "To prevent teachers from responding to students"}, {"value": "D", "text": "To guarantee identical results for every learner"}], "answer": "B", "explanation": "A lesson plan helps teachers organise instruction while allowing adjustments according to learner needs."}, {"id": 91, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "Which type of assessment is generally conducted before instruction to identify learners’ existing knowledge and needs?", "options": [{"value": "A", "text": "Diagnostic assessment"}, {"value": "B", "text": "Summative assessment"}, {"value": "C", "text": "Final certification only"}, {"value": "D", "text": "Annual grading only"}], "answer": "A", "explanation": "Diagnostic assessment helps identify prior knowledge, learning gaps and misconceptions before planning instruction."}, {"id": 92, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "What is the main purpose of a rubric?", "options": [{"value": "A", "text": "To provide criteria for evaluating performance"}, {"value": "B", "text": "To replace learning objectives"}, {"value": "C", "text": "To prevent feedback"}, {"value": "D", "text": "To determine students’ physical growth"}], "answer": "A", "explanation": "A rubric describes performance criteria and, often, levels of achievement."}, {"id": 93, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "Which is the best example of self-assessment?", "options": [{"value": "A", "text": "A student reflects on their work using stated criteria."}, {"value": "B", "text": "A teacher announces ranks without explanation."}, {"value": "C", "text": "Students copy answers from one another."}, {"value": "D", "text": "A school publishes attendance figures."}], "answer": "A", "explanation": "Self-assessment encourages learners to evaluate their own progress against learning goals or criteria."}, {"id": 94, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "What does reliability in assessment generally refer to?", "options": [{"value": "A", "text": "The consistency of assessment results"}, {"value": "B", "text": "The colour of the examination paper"}, {"value": "C", "text": "The length of the school day"}, {"value": "D", "text": "The number of classrooms in a school"}], "answer": "A", "explanation": "Reliability concerns the consistency of measurement. Validity, by contrast, concerns whether the assessment measures what it is intended to measure."}, {"id": 95, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "What does validity in assessment refer to?", "options": [{"value": "A", "text": "Whether an assessment measures what it is intended to measure"}, {"value": "B", "text": "Whether the paper contains colourful images"}, {"value": "C", "text": "Whether all students receive identical marks"}, {"value": "D", "text": "Whether the test is completed quickly"}], "answer": "A", "explanation": "Validity concerns the appropriateness of interpretations and uses of assessment results for the intended purpose."}, {"id": 96, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "Which practice best promotes an inclusive classroom?", "options": [{"value": "A", "text": "Using inaccessible resources without alternatives"}, {"value": "B", "text": "Encouraging participation and addressing barriers to learning"}, {"value": "C", "text": "Excluding students who need support"}, {"value": "D", "text": "Assuming every student has identical needs"}], "answer": "B", "explanation": "Inclusion requires attention to access, participation, belonging and appropriate educational support."}, {"id": 97, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "A student is afraid of answering questions because classmates laugh at mistakes. What should the teacher do?", "options": [{"value": "A", "text": "Ignore the situation"}, {"value": "B", "text": "Encourage the class to laugh less loudly"}, {"value": "C", "text": "Establish respectful classroom expectations and support safe participation"}, {"value": "D", "text": "Stop asking all questions permanently"}], "answer": "C", "explanation": "A respectful learning environment helps students participate without fear of humiliation."}, {"id": 98, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "Which teaching approach is most suitable for developing scientific reasoning?", "options": [{"value": "A", "text": "Asking students to memorise conclusions only"}, {"value": "B", "text": "Encouraging observation, investigation and evidence-based explanations"}, {"value": "C", "text": "Preventing experiments"}, {"value": "D", "text": "Discouraging predictions"}], "answer": "B", "explanation": "Scientific reasoning develops through questioning, investigating, analysing evidence and evaluating explanations."}, {"id": 99, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "What is the main purpose of remedial instruction after identifying a learning gap?", "options": [{"value": "A", "text": "To punish the learner"}, {"value": "B", "text": "To provide targeted opportunities to address the gap"}, {"value": "C", "text": "To remove the learner from the subject"}, {"value": "D", "text": "To compare the learner publicly with classmates"}], "answer": "B", "explanation": "Remedial instruction focuses on identified learning difficulties and provides appropriate opportunities for improvement."}, {"id": 100, "part": 1, "partName": "Part 1", "partSubject": "Child Development & Pedagogy", "section": "Final Practice Questions", "question": "Which statement best represents effective teaching?", "options": [{"value": "A", "text": "Every learner must learn in exactly the same way."}, {"value": "B", "text": "Memorisation should replace understanding."}, {"value": "C", "text": "Teaching should be responsive to learning objectives, evidence and learner needs."}, {"value": "D", "text": "Assessment should never influence teaching."}], "answer": "C", "explanation": "Effective teaching combines clear objectives, appropriate methods, ongoing assessment and adjustments that support learning."}, {"id": 101, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Which of the following best describes child development?", "options": [{"value": "A", "text": "It occurs only during childhood"}, {"value": "B", "text": "It is a continuous process throughout life"}, {"value": "C", "text": "It depends only on heredity"}, {"value": "D", "text": "It is the same for every child"}], "answer": "B", "explanation": "Development begins before birth and continues throughout the lifespan. Its rate and pattern may vary among individuals."}, {"id": 102, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "The principle of individual differences means that:", "options": [{"value": "A", "text": "All children learn at the same speed"}, {"value": "B", "text": "Children differ in abilities, interests and learning needs"}, {"value": "C", "text": "Only intelligent children can learn"}, {"value": "D", "text": "Teaching should focus only on average learners"}], "answer": "B", "explanation": "Learners differ in their physical, emotional, social and cognitive characteristics. Teachers should adapt instruction to accommodate these differences."}, {"id": 103, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Which factor is most closely associated with physical growth?", "options": [{"value": "A", "text": "Increase in height and weight"}, {"value": "B", "text": "Development of moral values"}, {"value": "C", "text": "Improvement in reasoning"}, {"value": "D", "text": "Development of social attitudes"}], "answer": "A", "explanation": "Growth mainly refers to measurable physical changes, such as increases in height, weight and body size."}, {"id": 104, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Development is best understood as a process that is:", "options": [{"value": "A", "text": "Entirely random"}, {"value": "B", "text": "Limited to physical changes"}, {"value": "C", "text": "Multidimensional"}, {"value": "D", "text": "Identical in every individual"}], "answer": "C", "explanation": "Development involves physical, cognitive, emotional, language and social dimensions."}, {"id": 105, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Which statement about heredity and environment is correct?", "options": [{"value": "A", "text": "Heredity alone determines development"}, {"value": "B", "text": "Environment alone determines development"}, {"value": "C", "text": "Both heredity and environment influence development"}, {"value": "D", "text": "Neither heredity nor environment affects development"}], "answer": "C", "explanation": "Development results from the interaction of genetic characteristics and environmental experiences."}, {"id": 106, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "A teacher observes that a learner understands concepts better through practical activities. What should the teacher do?", "options": [{"value": "A", "text": "Provide more opportunities for hands-on learning"}, {"value": "B", "text": "Ask the learner to memorise every answer"}, {"value": "C", "text": "Ignore the learner’s preference"}, {"value": "D", "text": "Give only written examinations"}], "answer": "A", "explanation": "Teaching should provide varied learning experiences and respond to learners’ needs."}, {"id": 107, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "The term maturation refers mainly to:", "options": [{"value": "A", "text": "Changes resulting from punishment"}, {"value": "B", "text": "Biologically guided development"}, {"value": "C", "text": "Learning through memorisation"}, {"value": "D", "text": "Changes caused exclusively by schooling"}], "answer": "B", "explanation": "Maturation refers to developmental changes associated with biological growth. Learning and experience also influence how abilities develop."}, {"id": 108, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Which of the following is an example of social development?", "options": [{"value": "A", "text": "Increase in body weight"}, {"value": "B", "text": "Improvement in eyesight"}, {"value": "C", "text": "Learning to cooperate with classmates"}, {"value": "D", "text": "Growth in height"}], "answer": "C", "explanation": "Social development involves learning to interact, communicate and cooperate with others."}, {"id": 109, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Emotional development includes the ability to:", "options": [{"value": "A", "text": "Recognise and regulate feelings"}, {"value": "B", "text": "Increase physical strength only"}, {"value": "C", "text": "Memorise textbook paragraphs"}, {"value": "D", "text": "Solve mathematical equations exclusively"}], "answer": "A", "explanation": "Emotional development includes recognising emotions, expressing them appropriately and gradually learning self-regulation."}, {"id": 110, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Child Development And Pedagogy", "question": "Which classroom practice best supports the holistic development of children?", "options": [{"value": "A", "text": "Focusing only on examination marks"}, {"value": "B", "text": "Encouraging academic, social, emotional and physical development"}, {"value": "C", "text": "Using only lectures"}, {"value": "D", "text": "Avoiding group activities"}], "answer": "B", "explanation": "Holistic education addresses multiple dimensions of a learner’s development rather than focusing only on academic achievement."}, {"id": 111, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "According to Jean Piaget, children construct knowledge mainly through:", "options": [{"value": "A", "text": "Passive listening"}, {"value": "B", "text": "Active interaction with their environment"}, {"value": "C", "text": "Punishment"}, {"value": "D", "text": "Repeated copying alone"}], "answer": "B", "explanation": "Piaget viewed children as active learners who construct and modify mental structures through experience."}, {"id": 112, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "The process of fitting new information into an existing mental schema is called:", "options": [{"value": "A", "text": "Accommodation"}, {"value": "B", "text": "Assimilation"}, {"value": "C", "text": "Reinforcement"}, {"value": "D", "text": "Conditioning"}], "answer": "B", "explanation": "Assimilation occurs when new experiences are interpreted using existing schemas."}, {"id": 113, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "When a child modifies an existing schema to understand a new experience, it is called:", "options": [{"value": "A", "text": "Accommodation"}, {"value": "B", "text": "Assimilation"}, {"value": "C", "text": "Imitation"}, {"value": "D", "text": "Extinction"}], "answer": "A", "explanation": "Accommodation involves changing an existing schema or developing a new one to fit new information."}, {"id": 114, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "Which stage of Piaget’s theory is associated with symbolic play and egocentric thinking?", "options": [{"value": "A", "text": "Sensorimotor stage"}, {"value": "B", "text": "Preoperational stage"}, {"value": "C", "text": "Concrete operational stage"}, {"value": "D", "text": "Formal operational stage"}], "answer": "B", "explanation": "The preoperational stage generally occurs from about 2 to 7 years and includes symbolic thought, although logical operations remain limited."}, {"id": 115, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "Object permanence develops primarily during which stage?", "options": [{"value": "A", "text": "Sensorimotor"}, {"value": "B", "text": "Preoperational"}, {"value": "C", "text": "Concrete operational"}, {"value": "D", "text": "Formal operational"}], "answer": "A", "explanation": "Object permanence—the understanding that objects continue to exist when out of sight—develops during the sensorimotor stage."}, {"id": 116, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "A child understands that the quantity of water remains the same when poured into a differently shaped glass. This demonstrates:", "options": [{"value": "A", "text": "Egocentrism"}, {"value": "B", "text": "Conservation"}, {"value": "C", "text": "Animism"}, {"value": "D", "text": "Centration"}], "answer": "B", "explanation": "Conservation is the understanding that quantity remains constant despite changes in appearance. It is associated with the concrete operational stage."}, {"id": 117, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "The ability to think abstractly and consider hypothetical situations is associated with:", "options": [{"value": "A", "text": "Sensorimotor stage"}, {"value": "B", "text": "Preoperational stage"}, {"value": "C", "text": "Concrete operational stage"}, {"value": "D", "text": "Formal operational stage"}], "answer": "D", "explanation": "Piaget associated formal operational thought with abstract reasoning and systematic consideration of hypothetical possibilities."}, {"id": 118, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "In Piaget’s theory, egocentrism means that a child:", "options": [{"value": "A", "text": "Is always selfish"}, {"value": "B", "text": "Has difficulty understanding another person’s perspective"}, {"value": "C", "text": "Cannot recognise objects"}, {"value": "D", "text": "Has no emotions"}], "answer": "B", "explanation": "Cognitive egocentrism involves difficulty taking another person’s viewpoint. It does not simply mean selfishness."}, {"id": 119, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "A teacher gives learners concrete objects to help them understand mathematical operations. This practice is especially suitable for learners who are:", "options": [{"value": "A", "text": "Developing concrete operational thinking"}, {"value": "B", "text": "Unable to learn through experience"}, {"value": "C", "text": "Already experts in abstract reasoning"}, {"value": "D", "text": "Not interested in mathematics"}], "answer": "A", "explanation": "Concrete materials help learners connect mathematical ideas with observable experiences."}, {"id": 120, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Piaget And Cognitive Development", "question": "Which statement best reflects Piaget’s view of learning?", "options": [{"value": "A", "text": "Children learn only through rewards"}, {"value": "B", "text": "Children actively construct knowledge"}, {"value": "C", "text": "Learning is entirely controlled by teachers"}, {"value": "D", "text": "Intelligence never changes"}], "answer": "B", "explanation": "Piaget emphasised active exploration and the gradual development of cognitive structures."}, {"id": 121, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "Lev Vygotsky emphasised the importance of which factor in cognitive development?", "options": [{"value": "A", "text": "Social interaction"}, {"value": "B", "text": "Isolation"}, {"value": "C", "text": "Punishment alone"}, {"value": "D", "text": "Heredity alone"}], "answer": "A", "explanation": "Vygotsky argued that social interaction and culturally developed tools play important roles in learning and cognitive development."}, {"id": 122, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "The Zone of Proximal Development (ZPD) refers to the difference between:", "options": [{"value": "A", "text": "A child’s age and height"}, {"value": "B", "text": "What a learner can do independently and what the learner can do with guidance"}, {"value": "C", "text": "Intelligence and personality"}, {"value": "D", "text": "Memory and attention"}], "answer": "B", "explanation": "The ZPD identifies tasks a learner cannot yet complete independently but can accomplish with appropriate support."}, {"id": 123, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "A teacher provides hints while a learner solves a difficult problem and gradually reduces help. This is an example of:", "options": [{"value": "A", "text": "Scaffolding"}, {"value": "B", "text": "Punishment"}, {"value": "C", "text": "Extinction"}, {"value": "D", "text": "Rote learning"}], "answer": "A", "explanation": "Scaffolding is temporary support that helps learners complete tasks and develop independence. It is closely associated with sociocultural approaches to learning."}, {"id": 124, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "According to Vygotsky, language is important because it:", "options": [{"value": "A", "text": "Has no relationship with thought"}, {"value": "B", "text": "Supports communication and the development of thinking"}, {"value": "C", "text": "Prevents social interaction"}, {"value": "D", "text": "Replaces every other learning process"}], "answer": "B", "explanation": "Vygotsky emphasised the role of language in social communication, self-regulation and the development of higher mental functions."}, {"id": 125, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "Which classroom activity best reflects social constructivism?", "options": [{"value": "A", "text": "Learners silently copy notes throughout the lesson"}, {"value": "B", "text": "Learners collaborate to solve a meaningful problem"}, {"value": "C", "text": "Learners memorise without understanding"}, {"value": "D", "text": "The teacher prevents discussion"}], "answer": "B", "explanation": "Social constructivism emphasises learning through interaction, dialogue and the shared construction of understanding."}, {"id": 126, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "Peer learning is useful because it can:", "options": [{"value": "A", "text": "Eliminate the teacher’s role entirely"}, {"value": "B", "text": "Encourage learners to explain and discuss ideas"}, {"value": "C", "text": "Guarantee identical achievement for everyone"}, {"value": "D", "text": "Replace all forms of assessment"}], "answer": "B", "explanation": "Explaining concepts to peers and hearing different perspectives can deepen understanding."}, {"id": 127, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "A more knowledgeable other, in Vygotsky’s theory, may be:", "options": [{"value": "A", "text": "Only a school principal"}, {"value": "B", "text": "Only a parent"}, {"value": "C", "text": "A person with greater relevant knowledge or skill"}, {"value": "D", "text": "Only a learner’s age-mate"}], "answer": "C", "explanation": "The more knowledgeable other may be a teacher, parent, peer or another person who can support learning."}, {"id": 128, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "Which statement best describes guided learning?", "options": [{"value": "A", "text": "Learners receive suitable support while developing independence"}, {"value": "B", "text": "Learners are never allowed to ask questions"}, {"value": "C", "text": "Teachers complete all tasks for learners"}, {"value": "D", "text": "Learners must discover everything without any help"}], "answer": "A", "explanation": "Guided learning provides assistance matched to the learner’s current level and gradually encourages independent performance."}, {"id": 129, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "In a constructivist classroom, the teacher primarily acts as a:", "options": [{"value": "A", "text": "Sole source of all knowledge"}, {"value": "B", "text": "Facilitator of learning"}, {"value": "C", "text": "Strict examiner only"}, {"value": "D", "text": "Passive observer in every situation"}], "answer": "B", "explanation": "The teacher designs experiences, asks questions and supports learners in constructing meaning."}, {"id": 130, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Vygotsky And Social Constructivism", "question": "Which approach is most consistent with collaborative learning?", "options": [{"value": "A", "text": "Assigning every learner an unrelated task with no interaction"}, {"value": "B", "text": "Encouraging a group to discuss evidence and develop a shared solution"}, {"value": "C", "text": "Prohibiting learners from communicating"}, {"value": "D", "text": "Giving marks only for copying textbook definitions"}], "answer": "B", "explanation": "Collaborative learning involves learners working together towards a shared learning goal."}, {"id": 131, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Classical conditioning is most closely associated with:", "options": [{"value": "A", "text": "Ivan Pavlov"}, {"value": "B", "text": "Jean Piaget"}, {"value": "C", "text": "Abraham Maslow"}, {"value": "D", "text": "Howard Gardner"}], "answer": "A", "explanation": "Pavlov demonstrated classical conditioning through experiments involving dogs, food and conditioned responses."}, {"id": 132, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Operant conditioning is associated with:", "options": [{"value": "A", "text": "B. F. Skinner"}, {"value": "B", "text": "Lev Vygotsky"}, {"value": "C", "text": "Lawrence Kohlberg"}, {"value": "D", "text": "Jean Piaget"}], "answer": "A", "explanation": "Skinner studied how consequences influence the likelihood of behaviour occurring again."}, {"id": 133, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "A teacher praises a learner for completing homework on time. If this increases the likelihood of the behaviour recurring, the praise functions as:", "options": [{"value": "A", "text": "Positive reinforcement"}, {"value": "B", "text": "Negative punishment"}, {"value": "C", "text": "Extinction"}, {"value": "D", "text": "Classical conditioning only"}], "answer": "A", "explanation": "Positive reinforcement involves presenting a consequence that increases the likelihood of a behaviour."}, {"id": 134, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Negative reinforcement occurs when:", "options": [{"value": "A", "text": "An unpleasant condition is removed to increase a behaviour"}, {"value": "B", "text": "A reward is removed to decrease a behaviour"}, {"value": "C", "text": "A learner is insulted"}, {"value": "D", "text": "A response is ignored in every case"}], "answer": "A", "explanation": "Negative reinforcement strengthens behaviour by removing or preventing an aversive condition. It is different from punishment."}, {"id": 135, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Thorndike’s Law of Effect states that responses followed by satisfying consequences tend to:", "options": [{"value": "A", "text": "Become less likely"}, {"value": "B", "text": "Become more likely"}, {"value": "C", "text": "Disappear immediately"}, {"value": "D", "text": "Remain completely unchanged"}], "answer": "B", "explanation": "Thorndike proposed that satisfying consequences strengthen the connection between a situation and a response."}, {"id": 136, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Learning by observing and imitating others is central to the theory of:", "options": [{"value": "A", "text": "Albert Bandura"}, {"value": "B", "text": "Ivan Pavlov"}, {"value": "C", "text": "B. F. Skinner alone"}, {"value": "D", "text": "Alfred Binet"}], "answer": "A", "explanation": "Bandura’s social learning theory emphasises observation, modelling and the role of social experiences in learning."}, {"id": 137, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "A student learns how to conduct a science experiment by watching the teacher demonstrate it. This is an example of:", "options": [{"value": "A", "text": "Observational learning"}, {"value": "B", "text": "Trial-and-error learning only"}, {"value": "C", "text": "Maturation"}, {"value": "D", "text": "Extinction"}], "answer": "A", "explanation": "The learner acquires information or skills by observing another person’s actions."}, {"id": 138, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Insight learning is most closely associated with:", "options": [{"value": "A", "text": "Wolfgang Köhler"}, {"value": "B", "text": "Edward Thorndike"}, {"value": "C", "text": "Ivan Pavlov"}, {"value": "D", "text": "B. F. Skinner"}], "answer": "A", "explanation": "Köhler’s work with chimpanzees contributed to the understanding of insight learning, in which a solution emerges through reorganising one’s understanding of a problem."}, {"id": 139, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Trial-and-error learning is associated with:", "options": [{"value": "A", "text": "Edward Thorndike"}, {"value": "B", "text": "Abraham Maslow"}, {"value": "C", "text": "Noam Chomsky"}, {"value": "D", "text": "Jean Piaget alone"}], "answer": "A", "explanation": "Thorndike studied how learning can occur through repeated attempts, with successful responses becoming more likely."}, {"id": 140, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Learning Theories", "question": "Which practice is most likely to promote meaningful learning?", "options": [{"value": "A", "text": "Memorising isolated facts without understanding"}, {"value": "B", "text": "Connecting new concepts to prior knowledge"}, {"value": "C", "text": "Copying paragraphs repeatedly without discussion"}, {"value": "D", "text": "Avoiding questions"}], "answer": "B", "explanation": "Meaningful learning occurs when learners relate new information to what they already know and understand."}, {"id": 141, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Intrinsic motivation occurs when a learner studies because:", "options": [{"value": "A", "text": "The learner enjoys or values the activity itself"}, {"value": "B", "text": "The learner is threatened with punishment"}, {"value": "C", "text": "A prize is always promised"}, {"value": "D", "text": "Attendance is compulsory"}], "answer": "A", "explanation": "Intrinsic motivation comes from interest, enjoyment or personal satisfaction."}, {"id": 142, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "A learner completes a project to receive a certificate. This is primarily an example of:", "options": [{"value": "A", "text": "Intrinsic motivation"}, {"value": "B", "text": "Extrinsic motivation"}, {"value": "C", "text": "Maturation"}, {"value": "D", "text": "Insight learning"}], "answer": "B", "explanation": "Extrinsic motivation involves performing an activity to obtain an external reward or avoid an undesirable consequence."}, {"id": 143, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Abraham Maslow is associated with the:", "options": [{"value": "A", "text": "Hierarchy of Needs"}, {"value": "B", "text": "Theory of Classical Conditioning"}, {"value": "C", "text": "Theory of Cognitive Development"}, {"value": "D", "text": "Law of Effect"}], "answer": "A", "explanation": "Maslow proposed a hierarchy of human needs, commonly represented from physiological needs through safety, belonging, esteem and self-actualisation."}, {"id": 144, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Which classroom condition is most likely to support learning?", "options": [{"value": "A", "text": "Fear of humiliation"}, {"value": "B", "text": "A safe and supportive environment"}, {"value": "C", "text": "Constant comparison with classmates"}, {"value": "D", "text": "Frequent public criticism"}], "answer": "B", "explanation": "Learners are more likely to participate and take intellectual risks when they feel safe and respected."}, {"id": 145, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Howard Gardner is known for the theory of:", "options": [{"value": "A", "text": "Multiple Intelligences"}, {"value": "B", "text": "Classical Conditioning"}, {"value": "C", "text": "Moral Development"}, {"value": "D", "text": "Psychosexual Development"}], "answer": "A", "explanation": "Gardner proposed that intelligence can be understood through several distinct capacities, such as linguistic, logical-mathematical, spatial and interpersonal abilities."}, {"id": 146, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Which statement about intelligence is most appropriate for a teacher?", "options": [{"value": "A", "text": "A single test reveals every aspect of a learner’s ability"}, {"value": "B", "text": "Learners may demonstrate strengths in different areas"}, {"value": "C", "text": "Intelligence cannot be developed in any way"}, {"value": "D", "text": "Academic marks measure every form of intelligence"}], "answer": "B", "explanation": "Learners have varied strengths. Teachers should use multiple methods to understand and support their abilities."}, {"id": 147, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Emotional intelligence includes the ability to:", "options": [{"value": "A", "text": "Recognise and manage emotions"}, {"value": "B", "text": "Memorise facts only"}, {"value": "C", "text": "Calculate rapidly in every situation"}, {"value": "D", "text": "Avoid all social interaction"}], "answer": "A", "explanation": "Emotional intelligence involves understanding emotions and using that understanding to guide thinking and behaviour."}, {"id": 148, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Which strategy can help improve a learner’s confidence?", "options": [{"value": "A", "text": "Giving constructive feedback and achievable challenges"}, {"value": "B", "text": "Comparing the learner negatively with others"}, {"value": "C", "text": "Highlighting every mistake publicly"}, {"value": "D", "text": "Preventing independent attempts"}], "answer": "A", "explanation": "Supportive feedback and appropriately challenging tasks can help learners recognise progress and build confidence."}, {"id": 149, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "A learner continues practising a difficult skill because improvement is personally satisfying. This illustrates:", "options": [{"value": "A", "text": "Intrinsic motivation"}, {"value": "B", "text": "Negative punishment"}, {"value": "C", "text": "Classical conditioning"}, {"value": "D", "text": "External pressure only"}], "answer": "A", "explanation": "The learner is motivated by personal satisfaction and the desire to improve."}, {"id": 150, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Motivation, Intelligence And Individual Differences", "question": "Which is the best way to respond to differences in learners’ abilities?", "options": [{"value": "A", "text": "Use exactly the same support for every learner in every situation"}, {"value": "B", "text": "Provide appropriate, varied learning opportunities"}, {"value": "C", "text": "Label learners permanently by ability"}, {"value": "D", "text": "Give up on learners who struggle"}], "answer": "B", "explanation": "Differentiated teaching offers suitable support, challenges and resources according to learners’ needs."}, {"id": 151, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Inclusive education aims to:", "options": [{"value": "A", "text": "Educate only high-achieving learners together"}, {"value": "B", "text": "Enable all learners to participate meaningfully in education"}, {"value": "C", "text": "Separate every learner with a disability"}, {"value": "D", "text": "Eliminate individual support"}], "answer": "B", "explanation": "Inclusive education seeks to reduce barriers and ensure participation, access and learning for diverse students."}, {"id": 152, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "A teacher provides enlarged print to a learner with low vision. This is an example of:", "options": [{"value": "A", "text": "An educational accommodation"}, {"value": "B", "text": "Punishment"}, {"value": "C", "text": "Ability grouping"}, {"value": "D", "text": "Summative assessment"}], "answer": "A", "explanation": "An accommodation changes how a learner accesses information or demonstrates learning without necessarily changing the learning goal."}, {"id": 153, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Which practice is most suitable for a learner with a hearing impairment?", "options": [{"value": "A", "text": "Always speaking while facing the blackboard"}, {"value": "B", "text": "Providing visual information and ensuring the learner can see the speaker"}, {"value": "C", "text": "Avoiding written instructions"}, {"value": "D", "text": "Excluding the learner from group activities"}], "answer": "B", "explanation": "Visual cues, accessible communication and appropriate seating can support participation. Individual needs should guide the support provided."}, {"id": 154, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Dyslexia is primarily associated with difficulties in:", "options": [{"value": "A", "text": "Reading and word recognition"}, {"value": "B", "text": "Physical growth"}, {"value": "C", "text": "Hearing every sound"}, {"value": "D", "text": "Social interaction in every situation"}], "answer": "A", "explanation": "Dyslexia is a learning disorder that primarily affects word reading, decoding and spelling. It does not indicate low intelligence."}, {"id": 155, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Dyscalculia is associated mainly with difficulties in:", "options": [{"value": "A", "text": "Mathematical understanding and number processing"}, {"value": "B", "text": "Hearing speech"}, {"value": "C", "text": "Recognising facial expressions only"}, {"value": "D", "text": "Physical coordination exclusively"}], "answer": "A", "explanation": "Dyscalculia can affect number sense, arithmetic learning and the understanding of mathematical relationships."}, {"id": 156, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Which approach is appropriate when supporting a learner with ADHD?", "options": [{"value": "A", "text": "Provide clear routines and manageable instructions"}, {"value": "B", "text": "Assume the learner is deliberately misbehaving"}, {"value": "C", "text": "Use public humiliation"}, {"value": "D", "text": "Remove every opportunity for movement"}], "answer": "A", "explanation": "Predictable routines, clear directions, task chunking and appropriate movement opportunities may help learners with attention and self-regulation difficulties."}, {"id": 157, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Universal Design for Learning (UDL) encourages teachers to provide:", "options": [{"value": "A", "text": "Only one way to present information"}, {"value": "B", "text": "Multiple means of engagement, representation and action or expression"}, {"value": "C", "text": "The same assessment format in every situation"}, {"value": "D", "text": "Separate curricula for every individual by default"}], "answer": "B", "explanation": "UDL encourages flexible learning environments that anticipate learner variability and reduce barriers."}, {"id": 158, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "A child who needs additional time to complete a test may benefit from:", "options": [{"value": "A", "text": "An appropriate assessment accommodation"}, {"value": "B", "text": "Automatic failure"}, {"value": "C", "text": "Exclusion from assessment"}, {"value": "D", "text": "Public criticism"}], "answer": "A", "explanation": "Additional time may be an appropriate accommodation when justified by the learner’s needs and permitted by the applicable assessment rules."}, {"id": 159, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "Which statement about disability is most appropriate?", "options": [{"value": "A", "text": "Disability always prevents learning"}, {"value": "B", "text": "Appropriate support and accessible environments can reduce barriers"}, {"value": "C", "text": "All learners with the same disability have identical needs"}, {"value": "D", "text": "Inclusion means ignoring individual needs"}], "answer": "B", "explanation": "Learners’ needs vary. Accessible teaching and individualised support can improve participation and learning."}, {"id": 160, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Inclusive Education And Special Educational Needs", "question": "In an inclusive classroom, a teacher should:", "options": [{"value": "A", "text": "Encourage participation and respect differences"}, {"value": "B", "text": "Expect every learner to learn in exactly the same way"}, {"value": "C", "text": "Discourage peer support"}, {"value": "D", "text": "Focus exclusively on learners who finish first"}], "answer": "A", "explanation": "Inclusion involves valuing diversity, removing barriers and providing meaningful opportunities for every learner."}, {"id": 161, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "The project method is commonly associated with:", "options": [{"value": "A", "text": "William H. Kilpatrick"}, {"value": "B", "text": "Ivan Pavlov"}, {"value": "C", "text": "Alfred Binet"}, {"value": "D", "text": "Lawrence Kohlberg"}], "answer": "A", "explanation": "Kilpatrick helped popularise the project method, which organises learning around purposeful activities."}, {"id": 162, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Problem-based learning begins with:", "options": [{"value": "A", "text": "A meaningful problem that learners investigate"}, {"value": "B", "text": "Memorising a complete textbook"}, {"value": "C", "text": "Copying answers without discussion"}, {"value": "D", "text": "A final examination only"}], "answer": "A", "explanation": "In problem-based learning, learners explore a problem, identify what they need to know and work towards possible solutions."}, {"id": 163, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Activity-based learning emphasises:", "options": [{"value": "A", "text": "Learning through purposeful activities"}, {"value": "B", "text": "Listening without participation"}, {"value": "C", "text": "Memorisation as the only method"}, {"value": "D", "text": "Avoiding practical experiences"}], "answer": "A", "explanation": "Activity-based learning engages learners in tasks that help them explore and understand concepts."}, {"id": 164, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Which method is particularly useful for encouraging learners to express and exchange ideas?", "options": [{"value": "A", "text": "Discussion"}, {"value": "B", "text": "Silent copying only"}, {"value": "C", "text": "Dictation alone"}, {"value": "D", "text": "Repeated punishment"}], "answer": "A", "explanation": "Discussion encourages communication, reasoning, listening and the consideration of different perspectives."}, {"id": 165, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Demonstration is especially useful when teaching:", "options": [{"value": "A", "text": "A process or skill that learners need to observe"}, {"value": "B", "text": "Only abstract definitions with no examples"}, {"value": "C", "text": "Topics that must never be illustrated"}, {"value": "D", "text": "Facts that cannot be explained"}], "answer": "A", "explanation": "Demonstration allows learners to observe procedures, techniques or processes before practising them."}, {"id": 166, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Which practice best supports critical thinking?", "options": [{"value": "A", "text": "Asking learners to justify their answers with evidence"}, {"value": "B", "text": "Requiring them to accept every statement without question"}, {"value": "C", "text": "Discouraging discussion"}, {"value": "D", "text": "Rewarding copying without understanding"}], "answer": "A", "explanation": "Critical thinking involves analysing information, evaluating evidence and giving reasoned explanations."}, {"id": 167, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Brainstorming is mainly used to:", "options": [{"value": "A", "text": "Generate a variety of ideas"}, {"value": "B", "text": "Identify one learner for punishment"}, {"value": "C", "text": "Prevent creative thinking"}, {"value": "D", "text": "Replace every form of teaching"}], "answer": "A", "explanation": "Brainstorming encourages participants to suggest ideas before evaluating or selecting them."}, {"id": 168, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Experiential learning emphasises:", "options": [{"value": "A", "text": "Learning through experience and reflection"}, {"value": "B", "text": "Reading definitions without application"}, {"value": "C", "text": "Avoiding practical activities"}, {"value": "D", "text": "Memorisation alone"}], "answer": "A", "explanation": "Experiential learning connects direct experiences with reflection and the development of understanding."}, {"id": 169, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Which teacher question best encourages higher-order thinking?", "options": [{"value": "A", "text": "“What is the definition?”"}, {"value": "B", "text": "“Copy the second paragraph.”"}, {"value": "C", "text": "“Why do you think this solution works, and what evidence supports it?”"}, {"value": "D", "text": "“Repeat the sentence exactly.”"}], "answer": "C", "explanation": "Asking learners to justify solutions requires analysis and evaluation rather than simple recall."}, {"id": 170, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Teaching Methods And Classroom Practices", "question": "Reflective teaching involves:", "options": [{"value": "A", "text": "Examining teaching practices to improve future instruction"}, {"value": "B", "text": "Repeating the same lesson regardless of results"}, {"value": "C", "text": "Avoiding feedback"}, {"value": "D", "text": "Blaming learners for every difficulty"}], "answer": "A", "explanation": "Reflective teachers analyse evidence from lessons, consider what worked and make adjustments."}, {"id": 171, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Assessment conducted during the teaching-learning process to improve learning is called:", "options": [{"value": "A", "text": "Formative assessment"}, {"value": "B", "text": "Summative assessment"}, {"value": "C", "text": "Final certification only"}, {"value": "D", "text": "Selection testing only"}], "answer": "A", "explanation": "Formative assessment provides information that teachers and learners can use to improve ongoing learning."}, {"id": 172, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Assessment conducted mainly at the end of a unit or course to judge achievement is generally called:", "options": [{"value": "A", "text": "Diagnostic assessment"}, {"value": "B", "text": "Summative assessment"}, {"value": "C", "text": "Informal observation only"}, {"value": "D", "text": "Peer tutoring"}], "answer": "B", "explanation": "Summative assessment evaluates learning at the end of a defined instructional period."}, {"id": 173, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Diagnostic assessment helps a teacher to:", "options": [{"value": "A", "text": "Identify learners’ strengths, difficulties and learning gaps"}, {"value": "B", "text": "Assign final grades only"}, {"value": "C", "text": "Avoid planning lessons"}, {"value": "D", "text": "Eliminate feedback"}], "answer": "A", "explanation": "Diagnostic assessment helps teachers identify specific areas requiring further instruction or support."}, {"id": 174, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "A teacher checks learners’ understanding through short questions during a lesson. This is an example of:", "options": [{"value": "A", "text": "Formative assessment"}, {"value": "B", "text": "Summative assessment only"}, {"value": "C", "text": "External certification"}, {"value": "D", "text": "Entrance selection only"}], "answer": "A", "explanation": "Questions during a lesson provide immediate evidence of understanding and can guide the next teaching steps."}, {"id": 175, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "A rubric is:", "options": [{"value": "A", "text": "A set of criteria used to assess performance"}, {"value": "B", "text": "A method of physical punishment"}, {"value": "C", "text": "A school attendance register"}, {"value": "D", "text": "A textbook index"}], "answer": "A", "explanation": "Rubrics describe assessment criteria and often include levels of performance to make expectations clearer."}, {"id": 176, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Reliability in assessment refers to:", "options": [{"value": "A", "text": "Consistency of measurement"}, {"value": "B", "text": "The attractiveness of the question paper"}, {"value": "C", "text": "The length of the examination hall"}, {"value": "D", "text": "The number of illustrations in a textbook"}], "answer": "A", "explanation": "A reliable assessment produces reasonably consistent results under comparable conditions."}, {"id": 177, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Validity in assessment refers to whether an assessment:", "options": [{"value": "A", "text": "Measures what it is intended to measure"}, {"value": "B", "text": "Contains many questions"}, {"value": "C", "text": "Is always difficult"}, {"value": "D", "text": "Uses only multiple-choice questions"}], "answer": "A", "explanation": "Validity concerns whether the evidence and interpretations from an assessment are appropriate for its intended purpose."}, {"id": 178, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Self-assessment encourages learners to:", "options": [{"value": "A", "text": "Reflect on their own learning and progress"}, {"value": "B", "text": "Avoid responsibility"}, {"value": "C", "text": "Assign grades to teachers only"}, {"value": "D", "text": "Stop receiving feedback"}], "answer": "A", "explanation": "Self-assessment helps learners identify strengths, difficulties and next steps."}, {"id": 179, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Which feedback is most useful for learning?", "options": [{"value": "A", "text": "“You are bad at this.”"}, {"value": "B", "text": "“Your answer is wrong.”"}, {"value": "C", "text": "“Your method is correct so far; check the calculation in step three.”"}, {"value": "D", "text": "“You will never understand this.”"}], "answer": "C", "explanation": "Specific, constructive feedback identifies what is working and gives the learner a clear next step."}, {"id": 180, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Assessment And Evaluation", "question": "Portfolio assessment involves:", "options": [{"value": "A", "text": "Collecting selected examples of a learner’s work over time"}, {"value": "B", "text": "Conducting one surprise test only"}, {"value": "C", "text": "Recording attendance alone"}, {"value": "D", "text": "Assessing learners only through oral questioning"}], "answer": "A", "explanation": "A portfolio can show progress, achievement and reflection through a collection of work produced over a period."}, {"id": 181, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Effective classroom management primarily aims to:", "options": [{"value": "A", "text": "Create an environment that supports learning"}, {"value": "B", "text": "Maintain silence regardless of learning needs"}, {"value": "C", "text": "Punish every mistake"}, {"value": "D", "text": "Prevent learner participation"}], "answer": "A", "explanation": "Classroom management includes establishing routines, supporting positive behaviour and creating conditions for learning."}, {"id": 182, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "A learner repeatedly interrupts a lesson. What should the teacher do first?", "options": [{"value": "A", "text": "Publicly humiliate the learner"}, {"value": "B", "text": "Investigate the reason and respond calmly and appropriately"}, {"value": "C", "text": "Immediately remove the learner from all future lessons"}, {"value": "D", "text": "Ignore every classroom disruption permanently"}], "answer": "B", "explanation": "Understanding the behaviour and applying proportionate, respectful strategies can help address its causes."}, {"id": 183, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Positive classroom discipline emphasises:", "options": [{"value": "A", "text": "Clear expectations and respectful guidance"}, {"value": "B", "text": "Fear as the main learning tool"}, {"value": "C", "text": "Public humiliation"}, {"value": "D", "text": "Unpredictable punishment"}], "answer": "A", "explanation": "Positive discipline teaches appropriate behaviour through consistent expectations, support and constructive consequences."}, {"id": 184, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Which approach is most appropriate for resolving a disagreement between learners?", "options": [{"value": "A", "text": "Listen to both learners and guide a fair resolution"}, {"value": "B", "text": "Punish both without hearing their explanations"}, {"value": "C", "text": "Encourage other learners to take sides"}, {"value": "D", "text": "Ignore every conflict"}], "answer": "A", "explanation": "Listening, respectful communication and problem-solving can help learners resolve conflicts constructively."}, {"id": 185, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "A teacher notices that a learner is frequently absent. The most appropriate initial response is to:", "options": [{"value": "A", "text": "Publicly shame the learner"}, {"value": "B", "text": "Explore the reasons and follow appropriate school procedures"}, {"value": "C", "text": "Assume the learner is lazy"}, {"value": "D", "text": "Immediately stop providing learning support"}], "answer": "B", "explanation": "Attendance difficulties may have different causes. Understanding the situation helps the school provide appropriate support."}, {"id": 186, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Classroom rules are most effective when they are:", "options": [{"value": "A", "text": "Clear, fair and consistently applied"}, {"value": "B", "text": "Changed randomly every day"}, {"value": "C", "text": "Known only to the teacher"}, {"value": "D", "text": "Based on personal preferences alone"}], "answer": "A", "explanation": "Predictable expectations help learners understand acceptable behaviour and create a more orderly learning environment."}, {"id": 187, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Which action helps create a democratic classroom?", "options": [{"value": "A", "text": "Allowing learners to express ideas respectfully"}, {"value": "B", "text": "Preventing all questions"}, {"value": "C", "text": "Giving one learner control over every activity"}, {"value": "D", "text": "Ignoring learner perspectives"}], "answer": "A", "explanation": "A democratic classroom supports participation, dialogue, fairness and respect for different viewpoints."}, {"id": 188, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "A teacher should handle confidential information about learners by:", "options": [{"value": "A", "text": "Sharing it publicly"}, {"value": "B", "text": "Protecting privacy and following appropriate professional procedures"}, {"value": "C", "text": "Discussing it casually with unrelated people"}, {"value": "D", "text": "Posting it on social media"}], "answer": "B", "explanation": "Teachers should handle sensitive learner information responsibly and share it only when appropriate and authorised."}, {"id": 189, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Professional development helps teachers to:", "options": [{"value": "A", "text": "Update their knowledge and improve teaching practice"}, {"value": "B", "text": "Avoid learning new methods"}, {"value": "C", "text": "Eliminate the need for reflection"}, {"value": "D", "text": "Use the same strategies forever"}], "answer": "A", "explanation": "Professional development supports teachers in improving subject knowledge, pedagogical skills and responsiveness to learners."}, {"id": 190, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Classroom Management And Professional Practice", "question": "Collaboration between teachers and parents can help to:", "options": [{"value": "A", "text": "Support learners’ educational progress"}, {"value": "B", "text": "Replace all classroom teaching"}, {"value": "C", "text": "Guarantee that every learner has identical needs"}, {"value": "D", "text": "Eliminate assessment"}], "answer": "A", "explanation": "Appropriate communication between school and home can help coordinate support for learners’ educational and developmental needs."}, {"id": 191, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "A teacher asks learners to predict what will happen in an experiment before carrying it out. This activity particularly encourages:", "options": [{"value": "A", "text": "Scientific thinking"}, {"value": "B", "text": "Passive memorisation"}, {"value": "C", "text": "Punishment-based learning"}, {"value": "D", "text": "Rote copying"}], "answer": "A", "explanation": "Making predictions encourages learners to use prior knowledge, formulate expectations and test ideas against evidence."}, {"id": 192, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "During a lesson, a teacher discovers that several learners have misunderstood a key concept. What is the best next step?", "options": [{"value": "A", "text": "Continue without addressing the misunderstanding"}, {"value": "B", "text": "Re-explain the concept using another example and check understanding"}, {"value": "C", "text": "Blame the learners"}, {"value": "D", "text": "Give a final examination immediately"}], "answer": "B", "explanation": "Teaching should respond to evidence of learning. An alternative explanation can help address misconceptions."}, {"id": 193, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "Learners investigate water use in their community and propose ways to reduce waste. This is an example of:", "options": [{"value": "A", "text": "Contextual and problem-based learning"}, {"value": "B", "text": "Memorisation without application"}, {"value": "C", "text": "Punishment"}, {"value": "D", "text": "Passive listening only"}], "answer": "A", "explanation": "The activity connects classroom learning to a real-world issue and asks learners to investigate possible solutions."}, {"id": 194, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "A teacher gives different reading materials to learners according to their current reading levels while maintaining a shared learning goal. This illustrates:", "options": [{"value": "A", "text": "Differentiated instruction"}, {"value": "B", "text": "Fixed ability labelling"}, {"value": "C", "text": "Summative assessment"}, {"value": "D", "text": "Classical conditioning"}], "answer": "A", "explanation": "Differentiated instruction adjusts resources or support to meet different learner needs while working towards suitable objectives."}, {"id": 195, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "A learner gives an incorrect answer but explains a reasonable line of thinking. The teacher should:", "options": [{"value": "A", "text": "Explore the learner’s reasoning and address the misconception"}, {"value": "B", "text": "Immediately stop the learner from participating"}, {"value": "C", "text": "Laugh at the answer"}, {"value": "D", "text": "Ignore the explanation"}], "answer": "A", "explanation": "Analysing a learner’s reasoning helps identify misunderstandings and supports conceptual development."}, {"id": 196, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "Which activity best develops cooperative skills?", "options": [{"value": "A", "text": "A group task with shared goals and defined responsibilities"}, {"value": "B", "text": "A competition in which only one learner can participate"}, {"value": "C", "text": "Individual copying throughout the lesson"}, {"value": "D", "text": "Preventing learners from communicating"}], "answer": "A", "explanation": "Structured group work gives learners opportunities to communicate, share responsibility and work towards a common outcome."}, {"id": 197, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "A teacher wants to know whether learners can apply a mathematical concept to everyday life. Which task is most suitable?", "options": [{"value": "A", "text": "Ask learners to copy the definition"}, {"value": "B", "text": "Ask learners to solve a realistic everyday problem using the concept"}, {"value": "C", "text": "Ask learners to repeat the concept aloud"}, {"value": "D", "text": "Ask learners to memorise the page number"}], "answer": "B", "explanation": "Applying knowledge to a new situation provides evidence of transfer and practical understanding."}, {"id": 198, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "Learners are encouraged to maintain journals about what they learned and what they still find difficult. This mainly supports:", "options": [{"value": "A", "text": "Reflection and metacognition"}, {"value": "B", "text": "Punishment"}, {"value": "C", "text": "Rote memorisation only"}, {"value": "D", "text": "Physical growth"}], "answer": "A", "explanation": "Metacognition involves thinking about one’s own thinking and learning. Journals can help learners monitor their understanding."}, {"id": 199, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "A teacher uses a short quiz, reviews the responses and changes the next lesson accordingly. This demonstrates:", "options": [{"value": "A", "text": "Assessment-informed teaching"}, {"value": "B", "text": "Teaching without evidence"}, {"value": "C", "text": "Summative grading only"}, {"value": "D", "text": "Unplanned punishment"}], "answer": "A", "explanation": "The teacher uses evidence of learners’ understanding to make instructional decisions."}, {"id": 200, "part": 2, "partName": "Part 2", "partSubject": "Child Development, Learning Theories, Inclusive Education, Teaching Methods & Assessment", "section": "Application-Based Pedagogy Questions", "question": "Which statement best represents learner-centred teaching?", "options": [{"value": "A", "text": "Every lesson must be delivered through a lecture"}, {"value": "B", "text": "Learners actively engage with ideas, while the teacher guides and supports learning"}, {"value": "C", "text": "Learners should never ask questions"}, {"value": "D", "text": "Assessment should be avoided"}], "answer": "B", "explanation": "Learner-centred teaching encourages active participation, meaningful tasks, feedback and appropriate teacher guidance."}, {"id": 201, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Educational psychology primarily studies:", "options": [{"value": "A", "text": "The financial administration of schools"}, {"value": "B", "text": "Human behaviour and learning in educational settings"}, {"value": "C", "text": "The history of buildings"}, {"value": "D", "text": "The preparation of school timetables only"}], "answer": "B", "explanation": "Educational psychology applies psychological principles to understand learning, motivation, development and classroom behaviour."}, {"id": 202, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Which method involves observing learners systematically in their natural environment?", "options": [{"value": "A", "text": "Observation method"}, {"value": "B", "text": "Guessing method"}, {"value": "C", "text": "Punishment method"}, {"value": "D", "text": "Memorisation method"}], "answer": "A", "explanation": "Systematic observation helps teachers understand learners’ behaviour and interactions in real situations."}, {"id": 203, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "A teacher wants to understand why a learner repeatedly struggles with reading. Which approach is most appropriate initially?", "options": [{"value": "A", "text": "Label the learner as incapable"}, {"value": "B", "text": "Gather information about the learner’s reading skills and difficulties"}, {"value": "C", "text": "Ignore the problem"}, {"value": "D", "text": "Punish the learner for slow reading"}], "answer": "B", "explanation": "Careful assessment helps identify specific learning needs before selecting appropriate interventions."}, {"id": 204, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Which of the following is an example of metacognition?", "options": [{"value": "A", "text": "Repeating a sentence without thinking"}, {"value": "B", "text": "Thinking about which strategy helps you solve a problem"}, {"value": "C", "text": "Copying a classmate’s answer"}, {"value": "D", "text": "Memorising without checking understanding"}], "answer": "B", "explanation": "Metacognition involves monitoring and regulating one’s own thinking and learning."}, {"id": 205, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Transfer of learning occurs when:", "options": [{"value": "A", "text": "Learning in one situation influences performance in another"}, {"value": "B", "text": "A learner changes schools"}, {"value": "C", "text": "A teacher changes the classroom"}, {"value": "D", "text": "A learner forgets all previous knowledge"}], "answer": "A", "explanation": "Transfer occurs when knowledge or skills learned in one context affect learning or performance in a different context."}, {"id": 206, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Positive transfer of learning occurs when previous learning:", "options": [{"value": "A", "text": "Interferes with new learning"}, {"value": "B", "text": "Helps the learner acquire or perform something new"}, {"value": "C", "text": "Has no influence on performance"}, {"value": "D", "text": "Prevents understanding"}], "answer": "B", "explanation": "Positive transfer occurs when existing knowledge or skills support new learning."}, {"id": 207, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Forgetting information because newly learned information interferes with older information is called:", "options": [{"value": "A", "text": "Proactive interference"}, {"value": "B", "text": "Retroactive interference"}, {"value": "C", "text": "Positive transfer"}, {"value": "D", "text": "Insight learning"}], "answer": "B", "explanation": "Retroactive interference occurs when newer learning disrupts the recall of previously learned information."}, {"id": 208, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "When older learning interferes with the recall of newer information, it is called:", "options": [{"value": "A", "text": "Proactive interference"}, {"value": "B", "text": "Retroactive interference"}, {"value": "C", "text": "Positive reinforcement"}, {"value": "D", "text": "Accommodation"}], "answer": "A", "explanation": "Proactive interference occurs when previously learned information makes it harder to remember newer information."}, {"id": 209, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "Which practice is generally most useful for long-term retention?", "options": [{"value": "A", "text": "Studying everything once immediately before an examination"}, {"value": "B", "text": "Spaced practice with opportunities for retrieval"}, {"value": "C", "text": "Reading without checking understanding"}, {"value": "D", "text": "Avoiding revision"}], "answer": "B", "explanation": "Revisiting information over time and actively retrieving it can improve long-term retention."}, {"id": 210, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Psychology", "question": "A teacher asks learners to explain a concept in their own words. This can help the teacher assess:", "options": [{"value": "A", "text": "Understanding"}, {"value": "B", "text": "Height"}, {"value": "C", "text": "Physical strength"}, {"value": "D", "text": "Attendance alone"}], "answer": "A", "explanation": "Explaining a concept in one’s own words provides evidence of comprehension and can reveal misconceptions."}, {"id": 211, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Erik Erikson’s theory focuses on:", "options": [{"value": "A", "text": "Psychosocial development"}, {"value": "B", "text": "Classical conditioning"}, {"value": "C", "text": "Multiple intelligences"}, {"value": "D", "text": "Trial-and-error learning"}], "answer": "A", "explanation": "Erikson described psychosocial stages involving developmental challenges throughout life."}, {"id": 212, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "According to Erikson, the major psychosocial conflict during adolescence is:", "options": [{"value": "A", "text": "Trust versus mistrust"}, {"value": "B", "text": "Autonomy versus shame and doubt"}, {"value": "C", "text": "Identity versus role confusion"}, {"value": "D", "text": "Integrity versus despair"}], "answer": "C", "explanation": "Erikson associated adolescence with exploring identity, values, roles and a sense of self."}, {"id": 213, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Lawrence Kohlberg is known for his theory of:", "options": [{"value": "A", "text": "Moral development"}, {"value": "B", "text": "Language acquisition only"}, {"value": "C", "text": "Operant conditioning"}, {"value": "D", "text": "Cognitive mapping"}], "answer": "A", "explanation": "Kohlberg proposed levels and stages describing how moral reasoning may develop."}, {"id": 214, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "A child follows a classroom rule mainly to avoid punishment. In Kohlberg’s framework, this is most consistent with:", "options": [{"value": "A", "text": "Pre-conventional moral reasoning"}, {"value": "B", "text": "Post-conventional moral reasoning"}, {"value": "C", "text": "Formal operational thought"}, {"value": "D", "text": "Self-actualisation"}], "answer": "A", "explanation": "Pre-conventional reasoning focuses strongly on consequences for the individual, including punishment and reward."}, {"id": 215, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Which statement about developmental stages is most appropriate?", "options": [{"value": "A", "text": "Every child reaches every milestone at exactly the same age"}, {"value": "B", "text": "Developmental age ranges are approximate and individual variation exists"}, {"value": "C", "text": "Development stops after primary school"}, {"value": "D", "text": "Every developmental difference indicates a disorder"}], "answer": "B", "explanation": "Development follows broad patterns, but the timing and expression of skills vary among children."}, {"id": 216, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Which factor can influence language development?", "options": [{"value": "A", "text": "Interaction and exposure to language"}, {"value": "B", "text": "Physical height alone"}, {"value": "C", "text": "School uniform colour"}, {"value": "D", "text": "Seating arrangement alone in every case"}], "answer": "A", "explanation": "Language development is supported by meaningful communication, exposure, opportunities to listen and speak, and individual developmental factors."}, {"id": 217, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Play is important in early childhood because it can support:", "options": [{"value": "A", "text": "Cognitive, physical, social and emotional development"}, {"value": "B", "text": "Physical development only"}, {"value": "C", "text": "Memorisation only"}, {"value": "D", "text": "Examination performance exclusively"}], "answer": "A", "explanation": "Different forms of play provide opportunities for exploration, movement, imagination, cooperation and emotional expression."}, {"id": 218, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Which classroom activity best encourages symbolic thinking in young children?", "options": [{"value": "A", "text": "Pretending a cardboard box is a bus"}, {"value": "B", "text": "Copying a paragraph repeatedly"}, {"value": "C", "text": "Memorising a list without context"}, {"value": "D", "text": "Completing only timed tests"}], "answer": "A", "explanation": "Pretend play involves using one object or action to represent another, demonstrating symbolic thought."}, {"id": 219, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "Moral development in children can be supported by:", "options": [{"value": "A", "text": "Discussing fairness and the consequences of actions"}, {"value": "B", "text": "Preventing all questions about rules"}, {"value": "C", "text": "Using humiliation as a teaching method"}, {"value": "D", "text": "Asking learners to obey without understanding in every situation"}], "answer": "A", "explanation": "Guided discussion of fairness, responsibility and the effects of actions can encourage moral reasoning."}, {"id": 220, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Developmental Theories", "question": "A teacher notices that a learner becomes upset after making a mistake. Which response is most supportive?", "options": [{"value": "A", "text": "Tell the learner that mistakes prove an inability to learn"}, {"value": "B", "text": "Help the learner understand the mistake and try again"}, {"value": "C", "text": "Compare the learner negatively with others"}, {"value": "D", "text": "Stop the learner from attempting difficult tasks"}], "answer": "B", "explanation": "Constructive feedback and opportunities to retry can help learners develop resilience and confidence."}, {"id": 221, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Which classroom practice best supports language development?", "options": [{"value": "A", "text": "Encouraging meaningful conversations and storytelling"}, {"value": "B", "text": "Preventing learners from speaking"}, {"value": "C", "text": "Correcting every minor error through public criticism"}, {"value": "D", "text": "Asking learners only to copy text"}], "answer": "A", "explanation": "Communication-rich activities provide opportunities to develop vocabulary, listening, speaking and narrative skills."}, {"id": 222, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "A learner uses a new word correctly after hearing it in several meaningful contexts. This demonstrates:", "options": [{"value": "A", "text": "Vocabulary development through exposure and use"}, {"value": "B", "text": "Physical maturation alone"}, {"value": "C", "text": "Negative reinforcement"}, {"value": "D", "text": "Summative evaluation"}], "answer": "A", "explanation": "Repeated exposure and meaningful use help learners develop an understanding of new vocabulary."}, {"id": 223, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Which strategy is most appropriate for helping learners understand a difficult abstract concept?", "options": [{"value": "A", "text": "Connect it to familiar examples, models or representations"}, {"value": "B", "text": "Require memorisation without explanation"}, {"value": "C", "text": "Avoid answering questions"}, {"value": "D", "text": "Use only unfamiliar terminology"}], "answer": "A", "explanation": "Familiar examples and representations can help learners connect new ideas with prior knowledge."}, {"id": 224, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Divergent thinking involves:", "options": [{"value": "A", "text": "Producing multiple possible ideas or solutions"}, {"value": "B", "text": "Memorising one answer only"}, {"value": "C", "text": "Repeating the same procedure without variation"}, {"value": "D", "text": "Avoiding imagination"}], "answer": "A", "explanation": "Divergent thinking explores a range of possible answers or approaches to a problem."}, {"id": 225, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Convergent thinking primarily involves:", "options": [{"value": "A", "text": "Generating unlimited possibilities without selecting one"}, {"value": "B", "text": "Working towards a suitable or best-supported answer"}, {"value": "C", "text": "Avoiding evidence"}, {"value": "D", "text": "Refusing to solve problems"}], "answer": "B", "explanation": "Convergent thinking narrows possibilities to reach a solution based on relevant information or criteria."}, {"id": 226, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Critical thinking requires learners to:", "options": [{"value": "A", "text": "Accept all claims without examination"}, {"value": "B", "text": "Evaluate evidence and consider reasons"}, {"value": "C", "text": "Avoid questioning sources"}, {"value": "D", "text": "Memorise opinions as facts"}], "answer": "B", "explanation": "Critical thinking involves analysing claims, evaluating evidence and drawing reasoned conclusions."}, {"id": 227, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Which activity is most likely to encourage creativity?", "options": [{"value": "A", "text": "Asking learners to design several solutions to a local problem"}, {"value": "B", "text": "Requiring identical answers to every open-ended question"}, {"value": "C", "text": "Preventing experimentation"}, {"value": "D", "text": "Punishing unusual ideas automatically"}], "answer": "A", "explanation": "Open-ended tasks encourage imagination, flexible thinking and the exploration of alternatives."}, {"id": 228, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Prior knowledge is important because it:", "options": [{"value": "A", "text": "Helps learners connect new information to existing understanding"}, {"value": "B", "text": "Always prevents new learning"}, {"value": "C", "text": "Makes teaching unnecessary"}, {"value": "D", "text": "Eliminates the need for practice"}], "answer": "A", "explanation": "New concepts are often easier to understand when learners can relate them to what they already know."}, {"id": 229, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Which teacher question best promotes analysis?", "options": [{"value": "A", "text": "“Repeat the definition.”"}, {"value": "B", "text": "“List the first three words on the page.”"}, {"value": "C", "text": "“What are the similarities and differences between these two explanations?”"}, {"value": "D", "text": "“Copy the example exactly.”"}], "answer": "C", "explanation": "Comparing and contrasting requires learners to examine relationships and distinguish important features."}, {"id": 230, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Language, Thinking And Learning", "question": "Which strategy is most appropriate when learners have different levels of prior knowledge?", "options": [{"value": "A", "text": "Check their starting points and provide suitable support"}, {"value": "B", "text": "Assume everyone knows the same information"}, {"value": "C", "text": "Ignore misunderstandings"}, {"value": "D", "text": "Teach only to the most advanced learners"}], "answer": "A", "explanation": "Understanding learners’ starting points helps teachers plan instruction that is appropriately challenging and accessible."}, {"id": 231, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "A learner sets a personal goal to improve reading fluency. This is an example of:", "options": [{"value": "A", "text": "Goal-directed learning"}, {"value": "B", "text": "Classical conditioning only"}, {"value": "C", "text": "Physical maturation"}, {"value": "D", "text": "Negative punishment"}], "answer": "A", "explanation": "Setting a goal gives the learner a target against which progress can be monitored."}, {"id": 232, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "Which teacher response is most likely to encourage a growth-oriented approach to learning?", "options": [{"value": "A", "text": "“You can improve by practising and trying a different strategy.”"}, {"value": "B", "text": "“Your ability can never change.”"}, {"value": "C", "text": "“Only naturally talented learners succeed.”"}, {"value": "D", "text": "“Mistakes should never happen.”"}], "answer": "A", "explanation": "A growth-oriented approach emphasises learning, effective strategies, effort and improvement rather than fixed ability."}, {"id": 233, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "Excessive fear in a classroom can interfere with learning because it may:", "options": [{"value": "A", "text": "Make some learners reluctant to participate or take risks"}, {"value": "B", "text": "Guarantee deeper understanding"}, {"value": "C", "text": "Improve every learner’s memory"}, {"value": "D", "text": "Eliminate all distractions"}], "answer": "A", "explanation": "A threatening environment can reduce participation and interfere with concentration for some learners."}, {"id": 234, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "Which reward is most educationally useful when it gives information about a learner’s progress?", "options": [{"value": "A", "text": "Specific feedback describing what the learner did well"}, {"value": "B", "text": "A reward unrelated to the learning task in every situation"}, {"value": "C", "text": "Public comparison of all learners"}, {"value": "D", "text": "An unexplained mark with no feedback"}], "answer": "A", "explanation": "Informative feedback helps learners understand their strengths and identify what to improve."}, {"id": 235, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "A learner gives up after one unsuccessful attempt. Which strategy is most appropriate?", "options": [{"value": "A", "text": "Break the task into manageable steps and provide guidance"}, {"value": "B", "text": "Remove every future learning opportunity"}, {"value": "C", "text": "Publicly criticise the learner"}, {"value": "D", "text": "Assume the learner can never succeed"}], "answer": "A", "explanation": "Smaller steps, feedback and suitable support can make challenging tasks more manageable."}, {"id": 236, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "Which factor is most likely to support sustained motivation?", "options": [{"value": "A", "text": "Meaningful goals and a sense of progress"}, {"value": "B", "text": "Repeated humiliation"}, {"value": "C", "text": "Unclear expectations"}, {"value": "D", "text": "Tasks that are always impossible"}], "answer": "A", "explanation": "Learners are more likely to persist when goals are meaningful and progress is visible."}, {"id": 237, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "A teacher allows learners to choose between two suitable project topics. This may support motivation by increasing:", "options": [{"value": "A", "text": "Learner autonomy"}, {"value": "B", "text": "Punishment"}, {"value": "C", "text": "Rote memorisation"}, {"value": "D", "text": "External control only"}], "answer": "A", "explanation": "Appropriate choice gives learners a sense of ownership and control over aspects of their learning."}, {"id": 238, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "Which approach best supports self-regulated learning?", "options": [{"value": "A", "text": "Help learners plan, monitor and evaluate their learning"}, {"value": "B", "text": "Make every decision for learners permanently"}, {"value": "C", "text": "Prevent learners from checking their progress"}, {"value": "D", "text": "Avoid setting learning goals"}], "answer": "A", "explanation": "Self-regulated learners use strategies to plan tasks, monitor understanding and evaluate outcomes."}, {"id": 239, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "A learner studies because the topic is personally interesting. This motivation is primarily:", "options": [{"value": "A", "text": "Intrinsic"}, {"value": "B", "text": "Extrinsic"}, {"value": "C", "text": "Punishment-based"}, {"value": "D", "text": "Unrelated to motivation"}], "answer": "A", "explanation": "Intrinsic motivation arises from interest or satisfaction in the activity itself."}, {"id": 240, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Motivation And Classroom Learning", "question": "Which practice best helps learners develop perseverance?", "options": [{"value": "A", "text": "Treat errors as opportunities for feedback and improvement"}, {"value": "B", "text": "Punish every unsuccessful attempt"}, {"value": "C", "text": "Avoid challenging tasks entirely"}, {"value": "D", "text": "Compare learners publicly after every activity"}], "answer": "A", "explanation": "Constructive responses to errors help learners learn from difficulties and continue working towards improvement."}, {"id": 241, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Equity in education means:", "options": [{"value": "A", "text": "Giving every learner exactly the same support regardless of need"}, {"value": "B", "text": "Providing fair opportunities and appropriate support according to need"}, {"value": "C", "text": "Educating only learners who achieve high marks"}, {"value": "D", "text": "Ignoring barriers to participation"}], "answer": "B", "explanation": "Equity recognises that learners may require different supports to access meaningful learning opportunities."}, {"id": 242, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Which practice best supports a learner who has difficulty understanding lengthy verbal instructions?", "options": [{"value": "A", "text": "Give concise, sequenced instructions and check understanding"}, {"value": "B", "text": "Make the instructions longer"}, {"value": "C", "text": "Refuse to repeat important information"}, {"value": "D", "text": "Exclude the learner from activities"}], "answer": "A", "explanation": "Breaking instructions into manageable steps and checking comprehension can improve access to learning."}, {"id": 243, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "A teacher provides audio recordings and written notes for a lesson. This is an example of:", "options": [{"value": "A", "text": "Offering multiple ways to access information"}, {"value": "B", "text": "Reducing every learning objective"}, {"value": "C", "text": "Punishment"}, {"value": "D", "text": "Summative grading"}], "answer": "A", "explanation": "Multiple formats can make content more accessible to learners with different preferences and needs."}, {"id": 244, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Which statement about learners with disabilities is correct?", "options": [{"value": "A", "text": "They all require the same accommodations"}, {"value": "B", "text": "Support should be based on individual needs and applicable guidance"}, {"value": "C", "text": "They should automatically be excluded from group work"}, {"value": "D", "text": "They cannot participate in meaningful assessment"}], "answer": "B", "explanation": "Disability-related support should respond to the learner’s needs, strengths and educational context."}, {"id": 245, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "A teacher wants to reduce barriers for learners who struggle with written expression. Which option may help demonstrate their understanding?", "options": [{"value": "A", "text": "Offer an appropriate oral response option where feasible"}, {"value": "B", "text": "Prevent them from answering"}, {"value": "C", "text": "Grade handwriting instead of the stated learning objective"}, {"value": "D", "text": "Remove all learning goals"}], "answer": "A", "explanation": "Alternative ways of responding may help assess the intended knowledge or skill, provided the response mode fits the learning objective and assessment requirements."}, {"id": 246, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Which action best supports gender equity in the classroom?", "options": [{"value": "A", "text": "Encourage all learners to participate in every subject without gender stereotypes"}, {"value": "B", "text": "Assign leadership only to boys"}, {"value": "C", "text": "Assume girls are less capable in science"}, {"value": "D", "text": "Separate learning opportunities based on stereotypes"}], "answer": "A", "explanation": "Gender-equitable teaching challenges stereotypes and provides fair opportunities for participation and achievement."}, {"id": 247, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "A culturally responsive teacher should:", "options": [{"value": "A", "text": "Respect learners’ backgrounds and connect learning to varied experiences"}, {"value": "B", "text": "Treat one cultural background as superior"}, {"value": "C", "text": "Prohibit learners from sharing relevant experiences"}, {"value": "D", "text": "Assume all learners have identical home experiences"}], "answer": "A", "explanation": "Culturally responsive teaching recognises diversity and uses learners’ experiences as resources for learning."}, {"id": 248, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Which approach is most suitable for a multilingual classroom?", "options": [{"value": "A", "text": "Use clear language, visuals and opportunities for meaningful communication"}, {"value": "B", "text": "Shame learners for using their home language"}, {"value": "C", "text": "Assume multilingualism prevents learning"}, {"value": "D", "text": "Avoid checking comprehension"}], "answer": "A", "explanation": "Accessible explanations and meaningful language activities can support learners who use different languages."}, {"id": 249, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Peer support in an inclusive classroom should aim to:", "options": [{"value": "A", "text": "Promote participation and mutual learning"}, {"value": "B", "text": "Make one learner permanently responsible for another"}, {"value": "C", "text": "Replace the teacher’s professional responsibilities"}, {"value": "D", "text": "Separate learners by perceived ability in every activity"}], "answer": "A", "explanation": "Well-structured peer support encourages cooperation while maintaining appropriate teacher responsibility and learner independence."}, {"id": 250, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Inclusive Education And Equity", "question": "Which is the best indicator of an inclusive classroom?", "options": [{"value": "A", "text": "Only high-achieving learners participate"}, {"value": "B", "text": "Diverse learners have meaningful opportunities to participate and learn"}, {"value": "C", "text": "Every learner must complete tasks in exactly the same way"}, {"value": "D", "text": "Learners who need support are always separated"}], "answer": "B", "explanation": "Inclusion is reflected in access, participation, belonging and appropriate support for learners with varied needs."}, {"id": 251, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "The inductive method proceeds from:", "options": [{"value": "A", "text": "Specific examples to a general rule"}, {"value": "B", "text": "A general rule to specific examples"}, {"value": "C", "text": "Assessment to punishment"}, {"value": "D", "text": "Conclusions to unrelated topics"}], "answer": "A", "explanation": "In inductive teaching, learners examine examples or observations and develop a general principle."}, {"id": 252, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "The deductive method generally proceeds from:", "options": [{"value": "A", "text": "Specific examples to a general principle"}, {"value": "B", "text": "A general rule to particular applications"}, {"value": "C", "text": "Guessing to memorisation"}, {"value": "D", "text": "Observation to no conclusion"}], "answer": "B", "explanation": "Deductive teaching introduces a general principle and then applies it to specific cases."}, {"id": 253, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "Which is an advantage of the demonstration method?", "options": [{"value": "A", "text": "It allows learners to observe how a process is performed"}, {"value": "B", "text": "It guarantees that no practice is needed"}, {"value": "C", "text": "It prevents learners from asking questions"}, {"value": "D", "text": "It replaces all other teaching strategies"}], "answer": "A", "explanation": "Demonstration can make procedures visible and clarify the sequence of actions required."}, {"id": 254, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "Which classroom task best represents inquiry-based learning?", "options": [{"value": "A", "text": "Learners investigate a question, gather evidence and develop a conclusion"}, {"value": "B", "text": "Learners copy a conclusion without investigation"}, {"value": "C", "text": "Learners memorise the teacher’s opinion only"}, {"value": "D", "text": "Learners avoid asking questions"}], "answer": "A", "explanation": "Inquiry-based learning involves questioning, investigation, evidence and reasoned conclusions."}, {"id": 255, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "Cooperative learning is most effective when:", "options": [{"value": "A", "text": "Learners have a shared goal and meaningful responsibilities"}, {"value": "B", "text": "One learner completes every task"}, {"value": "C", "text": "Learners are not allowed to communicate"}, {"value": "D", "text": "Group members have no idea what they must achieve"}], "answer": "A", "explanation": "Clear goals and individual responsibilities help make group work purposeful and equitable."}, {"id": 256, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "Which strategy best supports concept formation?", "options": [{"value": "A", "text": "Group examples according to their common characteristics"}, {"value": "B", "text": "Memorise unrelated words"}, {"value": "C", "text": "Avoid comparing examples"}, {"value": "D", "text": "Prevent learners from identifying patterns"}], "answer": "A", "explanation": "Identifying common and contrasting features helps learners recognise the defining characteristics of a concept."}, {"id": 257, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "A teacher uses local plants to teach classification. This illustrates:", "options": [{"value": "A", "text": "Contextualised learning"}, {"value": "B", "text": "Learning without examples"}, {"value": "C", "text": "Punishment-based teaching"}, {"value": "D", "text": "Summative assessment only"}], "answer": "A", "explanation": "Using familiar objects connects learning objectives to the learners’ environment."}, {"id": 258, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "Which practice is most likely to improve a lesson after it has been taught?", "options": [{"value": "A", "text": "Reflect on learner responses and adapt the next lesson"}, {"value": "B", "text": "Ignore all evidence of misunderstanding"}, {"value": "C", "text": "Repeat the same lesson regardless of results"}, {"value": "D", "text": "Avoid learner feedback"}], "answer": "A", "explanation": "Reflection and evidence-informed adjustments help teachers respond to learners’ needs."}, {"id": 259, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "Which is the best example of interdisciplinary learning?", "options": [{"value": "A", "text": "Studying water conservation through science, mathematics and language activities"}, {"value": "B", "text": "Teaching one isolated fact without context"}, {"value": "C", "text": "Preventing links between subjects"}, {"value": "D", "text": "Using assessment only for attendance"}], "answer": "A", "explanation": "Interdisciplinary learning connects ideas and skills from more than one subject around a shared topic or problem."}, {"id": 260, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Teaching Methods And Pedagogical Skills", "question": "A teacher asks learners to create a model after studying a concept. This activity can help learners:", "options": [{"value": "A", "text": "Apply and represent their understanding"}, {"value": "B", "text": "Avoid all thinking"}, {"value": "C", "text": "Replace every form of assessment"}, {"value": "D", "text": "Memorise without understanding in every case"}], "answer": "A", "explanation": "Creating a model can provide evidence of application and conceptual understanding."}, {"id": 261, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "Which assessment tool is especially useful for recording a learner’s behaviour over time?", "options": [{"value": "A", "text": "Anecdotal record"}, {"value": "B", "text": "School timetable"}, {"value": "C", "text": "Textbook index"}, {"value": "D", "text": "Attendance certificate alone"}], "answer": "A", "explanation": "An anecdotal record is a brief, factual account of a significant observed event or behaviour."}, {"id": 262, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "A checklist is useful when a teacher wants to record whether:", "options": [{"value": "A", "text": "Specific skills or behaviours are present"}, {"value": "B", "text": "Every learner has the same personality"}, {"value": "C", "text": "A lesson is always successful"}, {"value": "D", "text": "A learner’s future is certain"}], "answer": "A", "explanation": "Checklists help teachers record whether particular criteria, skills or behaviours have been demonstrated."}, {"id": 263, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "An assessment blueprint helps a teacher to:", "options": [{"value": "A", "text": "Plan the distribution of questions across content and learning objectives"}, {"value": "B", "text": "Decorate the classroom"}, {"value": "C", "text": "Record only attendance"}, {"value": "D", "text": "Replace the curriculum"}], "answer": "A", "explanation": "A blueprint supports balanced test construction by mapping questions to content areas and intended outcomes."}, {"id": 264, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "Which question primarily assesses recall?", "options": [{"value": "A", "text": "“Define evaporation.”"}, {"value": "B", "text": "“Compare two explanations of evaporation.”"}, {"value": "C", "text": "“Design an experiment to investigate evaporation.”"}, {"value": "D", "text": "“Evaluate the limitations of an experiment.”"}], "answer": "A", "explanation": "Defining a term primarily requires remembering information, while the other tasks require higher-level thinking."}, {"id": 265, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "Which task best assesses application?", "options": [{"value": "A", "text": "Repeat the definition of percentage"}, {"value": "B", "text": "Use percentages to calculate a discount on a real purchase"}, {"value": "C", "text": "Copy the textbook paragraph"}, {"value": "D", "text": "List the page numbers of examples"}], "answer": "B", "explanation": "Application requires using knowledge or a procedure in a particular situation."}, {"id": 266, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "A criterion-referenced assessment compares a learner’s performance with:", "options": [{"value": "A", "text": "Defined criteria or learning standards"}, {"value": "B", "text": "The performance of the tallest learner"}, {"value": "C", "text": "The teacher’s personal preferences"}, {"value": "D", "text": "A random score"}], "answer": "A", "explanation": "Criterion-referenced assessment determines how well a learner meets specified learning expectations."}, {"id": 267, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "A norm-referenced assessment interprets a learner’s performance in relation to:", "options": [{"value": "A", "text": "The performance of a reference group"}, {"value": "B", "text": "A list of learning objectives only"}, {"value": "C", "text": "The learner’s handwriting alone"}, {"value": "D", "text": "A classroom seating plan"}], "answer": "A", "explanation": "Norm-referenced interpretation compares a learner’s results with those of a specified group."}, {"id": 268, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "Which practice best improves the fairness of an assessment?", "options": [{"value": "A", "text": "Align questions with learning objectives and use clear criteria"}, {"value": "B", "text": "Include unrelated questions"}, {"value": "C", "text": "Change the marking rules unpredictably"}, {"value": "D", "text": "Give hidden advantages to selected learners"}], "answer": "A", "explanation": "Clear alignment and consistent criteria help ensure that an assessment measures relevant learning fairly."}, {"id": 269, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "Which statement best describes feedback in formative assessment?", "options": [{"value": "A", "text": "It should help learners understand their current performance and next steps"}, {"value": "B", "text": "It should always be limited to a final mark"}, {"value": "C", "text": "It should never be given during learning"}, {"value": "D", "text": "It should focus only on personal criticism"}], "answer": "A", "explanation": "Useful formative feedback provides information that learners can act on to improve."}, {"id": 270, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Assessment And Learning Outcomes", "question": "A teacher analyses common errors in a test before planning revision lessons. This demonstrates:", "options": [{"value": "A", "text": "Using assessment evidence to guide instruction"}, {"value": "B", "text": "Ignoring assessment results"}, {"value": "C", "text": "Summative grading without teaching"}, {"value": "D", "text": "Punishment-based assessment"}], "answer": "A", "explanation": "Analysing patterns of errors can reveal areas that require further explanation or practice."}, {"id": 271, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "A curriculum broadly includes:", "options": [{"value": "A", "text": "Planned learning experiences and educational goals"}, {"value": "B", "text": "Textbooks alone"}, {"value": "C", "text": "Examinations alone"}, {"value": "D", "text": "School buildings only"}], "answer": "A", "explanation": "A curriculum includes intended learning outcomes, content, learning experiences and approaches to assessment."}, {"id": 272, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "A lesson objective should ideally be:", "options": [{"value": "A", "text": "Clear and related to the intended learning outcome"}, {"value": "B", "text": "Unrelated to the lesson"}, {"value": "C", "text": "Impossible to understand"}, {"value": "D", "text": "Focused only on classroom decoration"}], "answer": "A", "explanation": "Clear objectives help teachers plan instruction and determine whether learning has occurred."}, {"id": 273, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "Bloom’s revised taxonomy places which of the following at the highest cognitive process level?", "options": [{"value": "A", "text": "Remember"}, {"value": "B", "text": "Understand"}, {"value": "C", "text": "Apply"}, {"value": "D", "text": "Create"}], "answer": "D", "explanation": "The commonly used revised taxonomy orders the cognitive processes as Remember, Understand, Apply, Analyse, Evaluate and Create."}, {"id": 274, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "Which activity is most closely associated with the “analyse” level of Bloom’s revised taxonomy?", "options": [{"value": "A", "text": "Recalling a date"}, {"value": "B", "text": "Explaining a word’s meaning"}, {"value": "C", "text": "Identifying relationships between parts of an argument"}, {"value": "D", "text": "Repeating a definition"}], "answer": "C", "explanation": "Analysis involves breaking information into parts and examining relationships, patterns or structure."}, {"id": 275, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "Which task best represents the “evaluate” level?", "options": [{"value": "A", "text": "List five facts"}, {"value": "B", "text": "Judge two solutions using stated criteria"}, {"value": "C", "text": "Copy a diagram"}, {"value": "D", "text": "Repeat a definition"}], "answer": "B", "explanation": "Evaluation involves making a judgement based on criteria, evidence or standards."}, {"id": 276, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "The hidden curriculum refers to:", "options": [{"value": "A", "text": "Unwritten values, norms and expectations learned through school life"}, {"value": "B", "text": "A textbook kept in a locked cupboard"}, {"value": "C", "text": "The official examination timetable"}, {"value": "D", "text": "The printed syllabus only"}], "answer": "A", "explanation": "Learners may acquire social expectations and values through routines, relationships and school culture, even when these are not formally taught."}, {"id": 277, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "A child learns to wait for a turn by participating in group activities. This is an example of learning that can occur through:", "options": [{"value": "A", "text": "Social interaction and classroom experience"}, {"value": "B", "text": "Physical growth alone"}, {"value": "C", "text": "Written examinations only"}, {"value": "D", "text": "Rote memorisation exclusively"}], "answer": "A", "explanation": "Group activities provide opportunities to practise cooperation, turn-taking and other social skills."}, {"id": 278, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "Curriculum flexibility is important because:", "options": [{"value": "A", "text": "Learners and educational contexts can differ"}, {"value": "B", "text": "All learners have identical needs"}, {"value": "C", "text": "Learning objectives are never important"}, {"value": "D", "text": "Teachers should avoid planning"}], "answer": "A", "explanation": "Flexibility allows teaching and learning experiences to respond to relevant learner needs and contextual conditions while maintaining appropriate goals."}, {"id": 279, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "Which statement best describes a competency-based approach?", "options": [{"value": "A", "text": "It focuses on demonstrating specified knowledge and skills"}, {"value": "B", "text": "It focuses only on copying notes"}, {"value": "C", "text": "It avoids learning outcomes"}, {"value": "D", "text": "It measures attendance as the only outcome"}], "answer": "A", "explanation": "Competency-based education emphasises learners’ ability to demonstrate relevant knowledge, skills and application."}, {"id": 280, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Curriculum And Educational Objectives", "question": "A teacher aligns objectives, activities and assessment. This promotes:", "options": [{"value": "A", "text": "Coherence in lesson planning"}, {"value": "B", "text": "Unrelated classroom tasks"}, {"value": "C", "text": "Unpredictable assessment"}, {"value": "D", "text": "The removal of learning goals"}], "answer": "A", "explanation": "Alignment ensures that learning activities and assessments provide evidence of the intended objectives."}, {"id": 281, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Educational technology is most effective when it:", "options": [{"value": "A", "text": "Supports clearly defined learning goals"}, {"value": "B", "text": "Is used only because it is new"}, {"value": "C", "text": "Replaces all teacher-student interaction"}, {"value": "D", "text": "Is unrelated to the subject"}], "answer": "A", "explanation": "Technology should be selected according to its usefulness for learning rather than novelty alone."}, {"id": 282, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Which is an example of blended learning?", "options": [{"value": "A", "text": "Combining face-to-face instruction with online learning activities"}, {"value": "B", "text": "Using only printed textbooks in every lesson"}, {"value": "C", "text": "Avoiding all classroom interaction"}, {"value": "D", "text": "Conducting only a final examination"}], "answer": "A", "explanation": "Blended learning combines in-person instruction with digital or online learning experiences."}, {"id": 283, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "A teacher asks learners to watch a short lesson video before class and solve problems together during class. This is an example of:", "options": [{"value": "A", "text": "Flipped learning"}, {"value": "B", "text": "Classical conditioning"}, {"value": "C", "text": "Summative assessment"}, {"value": "D", "text": "Rote learning only"}], "answer": "A", "explanation": "In a flipped approach, learners engage with introductory content before class and use class time for guided application and discussion."}, {"id": 284, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Which is an important consideration when selecting digital learning resources?", "options": [{"value": "A", "text": "Accessibility, accuracy, relevance and learner safety"}, {"value": "B", "text": "Popularity alone"}, {"value": "C", "text": "The number of animations only"}, {"value": "D", "text": "Whether the resource replaces every teacher activity"}], "answer": "A", "explanation": "Digital resources should be suitable for the learning objective, accurate, accessible and safe to use."}, {"id": 285, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Digital citizenship includes:", "options": [{"value": "A", "text": "Responsible, safe and respectful use of digital technologies"}, {"value": "B", "text": "Sharing passwords with everyone"}, {"value": "C", "text": "Publishing classmates’ private information"}, {"value": "D", "text": "Ignoring copyright and privacy"}], "answer": "A", "explanation": "Digital citizenship involves responsible online behaviour, privacy awareness, respectful communication and appropriate use of digital content."}, {"id": 286, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Which practice helps protect learners’ privacy online?", "options": [{"value": "A", "text": "Sharing personal information publicly"}, {"value": "B", "text": "Using appropriate privacy settings and limiting unnecessary data sharing"}, {"value": "C", "text": "Posting learner records on open websites"}, {"value": "D", "text": "Sharing account passwords with classmates"}], "answer": "B", "explanation": "Privacy-conscious practices reduce unnecessary exposure of personal information."}, {"id": 287, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "A teacher uses an online quiz that provides immediate feedback. The main potential learning benefit is:", "options": [{"value": "A", "text": "Learners can identify errors quickly"}, {"value": "B", "text": "All learning difficulties disappear automatically"}, {"value": "C", "text": "Teachers no longer need to plan"}, {"value": "D", "text": "The quiz guarantees perfect understanding"}], "answer": "A", "explanation": "Immediate feedback can help learners recognise mistakes and correct misunderstandings, although its effectiveness depends on the quality of the questions and feedback."}, {"id": 288, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Which statement about artificial intelligence in education is most appropriate?", "options": [{"value": "A", "text": "AI outputs should always be accepted without checking"}, {"value": "B", "text": "AI can support some learning tasks, but its outputs need critical evaluation"}, {"value": "C", "text": "AI guarantees that all information is correct"}, {"value": "D", "text": "AI removes the need for teachers"}], "answer": "B", "explanation": "AI tools may support planning, feedback and practice, but teachers and learners should check accuracy, bias, privacy and suitability."}, {"id": 289, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "A teacher wants learners to collaborate on a shared document. A suitable digital tool should support:", "options": [{"value": "A", "text": "Shared editing and communication"}, {"value": "B", "text": "Only private offline copying"}, {"value": "C", "text": "Automatic elimination of all disagreements"}, {"value": "D", "text": "Access to private information without permission"}], "answer": "A", "explanation": "Collaborative digital documents can allow learners to contribute, review and revise shared work."}, {"id": 290, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Educational Technology And Modern Learning", "question": "Which is a potential limitation of technology-based learning?", "options": [{"value": "A", "text": "Unequal access to devices or reliable internet"}, {"value": "B", "text": "The possibility of providing visual explanations"}, {"value": "C", "text": "Opportunities for interactive practice"}, {"value": "D", "text": "Access to diverse learning materials"}], "answer": "A", "explanation": "A digital divide can limit participation when learners do not have suitable devices, connectivity or accessible resources."}, {"id": 291, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "During a group discussion, one learner dominates and others remain silent. What should the teacher do?", "options": [{"value": "A", "text": "Structure turn-taking and encourage contributions from all learners"}, {"value": "B", "text": "Allow the same learner to answer every question"}, {"value": "C", "text": "End all group activities permanently"}, {"value": "D", "text": "Ignore the participation imbalance"}], "answer": "A", "explanation": "Clear roles and equitable turn-taking can create more balanced participation."}, {"id": 292, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A learner memorises a formula but cannot use it to solve a problem. What should the teacher do?", "options": [{"value": "A", "text": "Provide worked examples and guided practice applying the formula"}, {"value": "B", "text": "Ask the learner to memorise it more times without application"}, {"value": "C", "text": "Assume the learner has mastered the concept"}, {"value": "D", "text": "Stop teaching the topic"}], "answer": "A", "explanation": "The learner needs opportunities to connect the formula with its meaning and use it in relevant problems."}, {"id": 293, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A teacher discovers that the textbook example is unfamiliar to many learners. What is a good response?", "options": [{"value": "A", "text": "Introduce a familiar local example before returning to the textbook concept"}, {"value": "B", "text": "Blame learners for not understanding"}, {"value": "C", "text": "Remove every explanation"}, {"value": "D", "text": "Ask learners to copy the example repeatedly"}], "answer": "A", "explanation": "Familiar contexts can activate prior knowledge and make abstract concepts more accessible."}, {"id": 294, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A learner completes tasks quickly and accurately. Which response is most appropriate?", "options": [{"value": "A", "text": "Provide meaningful extension activities that deepen learning"}, {"value": "B", "text": "Require the learner to wait without any learning opportunity"}, {"value": "C", "text": "Give the learner unrelated busywork every time"}, {"value": "D", "text": "Prevent the learner from asking questions"}], "answer": "A", "explanation": "Extension activities can maintain engagement and develop deeper understanding without simply increasing repetitive work."}, {"id": 295, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A learner repeatedly makes the same spelling error. What should the teacher do?", "options": [{"value": "A", "text": "Identify the error pattern and provide targeted practice"}, {"value": "B", "text": "Criticise the learner publicly"}, {"value": "C", "text": "Ignore the error permanently"}, {"value": "D", "text": "Assume the learner cannot improve"}], "answer": "A", "explanation": "Identifying the source of a recurring error helps the teacher select appropriate instruction and feedback."}, {"id": 296, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "Learners disagree about the answer to a question. Which response best supports learning?", "options": [{"value": "A", "text": "Ask them to explain their reasoning and examine the evidence"}, {"value": "B", "text": "End the discussion immediately"}, {"value": "C", "text": "Accept the loudest learner’s answer"}, {"value": "D", "text": "Prevent learners from asking follow-up questions"}], "answer": "A", "explanation": "Evidence-based discussion encourages reasoning, respectful disagreement and the correction of misconceptions."}, {"id": 297, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A teacher notices that learners can answer questions in class but struggle independently. What would help?", "options": [{"value": "A", "text": "Gradually reduce support and provide independent practice"}, {"value": "B", "text": "Continue giving the complete answer every time"}, {"value": "C", "text": "Avoid independent tasks permanently"}, {"value": "D", "text": "Increase the complexity without guidance"}], "answer": "A", "explanation": "Gradual release of responsibility helps learners move from supported performance to independent application."}, {"id": 298, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A learner is anxious about speaking in front of the whole class. Which approach may help?", "options": [{"value": "A", "text": "Begin with smaller, supportive speaking opportunities"}, {"value": "B", "text": "Force an immediate long presentation without preparation"}, {"value": "C", "text": "Mock the learner’s anxiety"}, {"value": "D", "text": "Exclude the learner from all communication tasks"}], "answer": "A", "explanation": "Gradual, supportive opportunities can help learners build confidence while still working towards the learning objective."}, {"id": 299, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "A teacher wants to check understanding before moving to the next topic. Which strategy is most useful?", "options": [{"value": "A", "text": "Use a brief exit ticket or targeted questions"}, {"value": "B", "text": "Assume silence means everyone understands"}, {"value": "C", "text": "Move on without checking"}, {"value": "D", "text": "Ask only the highest-achieving learner"}], "answer": "A", "explanation": "A short check for understanding gives the teacher evidence to decide whether to review, extend or move forward."}, {"id": 300, "part": 3, "partName": "Part 3", "partSubject": "Educational Psychology, Child Development, Pedagogy, Inclusive Education & Assessment", "section": "Situational Pedagogy", "question": "Which statement best summarises effective pedagogy?", "options": [{"value": "A", "text": "Teaching is only the delivery of information"}, {"value": "B", "text": "Effective teaching combines planning, learner engagement, assessment and reflection"}, {"value": "C", "text": "All learners must use one method in every situation"}, {"value": "D", "text": "Assessment has no role in teaching"}], "answer": "B", "explanation": "Effective pedagogy involves clear goals, suitable learning experiences, attention to learner needs, useful feedback and ongoing improvement."}, {"id": 301, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Child-centred education gives primary importance to:", "options": [{"value": "A", "text": "The teacher’s convenience"}, {"value": "B", "text": "Learners’ needs, interests and active participation"}, {"value": "C", "text": "Textbook completion alone"}, {"value": "D", "text": "Examinations alone"}], "answer": "B", "explanation": "Child-centred education considers learners’ developmental needs and encourages active involvement in learning."}, {"id": 302, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Which classroom practice best reflects child-centred teaching?", "options": [{"value": "A", "text": "The teacher speaks throughout every lesson"}, {"value": "B", "text": "Learners explore ideas and participate in meaningful activities"}, {"value": "C", "text": "Learners copy notes without discussion"}, {"value": "D", "text": "Questions from learners are discouraged"}], "answer": "B", "explanation": "Child-centred teaching encourages exploration, participation, questioning and the construction of understanding."}, {"id": 303, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "A teacher asks learners what they already know about a topic before introducing new content. This helps the teacher:", "options": [{"value": "A", "text": "Identify prior knowledge"}, {"value": "B", "text": "Avoid lesson planning"}, {"value": "C", "text": "Replace all assessments"}, {"value": "D", "text": "Determine intelligence from one answer"}], "answer": "A", "explanation": "Activating prior knowledge helps teachers connect new learning with learners’ existing understanding."}, {"id": 304, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Which is the most appropriate role of a teacher in a constructivist classroom?", "options": [{"value": "A", "text": "Dictator of every answer"}, {"value": "B", "text": "Facilitator who supports learners’ construction of knowledge"}, {"value": "C", "text": "Examiner only"}, {"value": "D", "text": "Passive observer who never intervenes"}], "answer": "B", "explanation": "Constructivist teaching involves designing learning experiences, asking questions and providing appropriate guidance."}, {"id": 305, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "A learner asks an unexpected question during a lesson. What should the teacher ideally do?", "options": [{"value": "A", "text": "Discourage curiosity"}, {"value": "B", "text": "Explore the question when relevant and encourage inquiry"}, {"value": "C", "text": "Punish the learner"}, {"value": "D", "text": "Ignore every question that is not in the textbook"}], "answer": "B", "explanation": "Thoughtful responses to questions can encourage curiosity, critical thinking and deeper understanding."}, {"id": 306, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Which activity best encourages active learning?", "options": [{"value": "A", "text": "Copying a complete chapter silently"}, {"value": "B", "text": "Conducting an experiment and discussing the results"}, {"value": "C", "text": "Listening without any opportunity to respond"}, {"value": "D", "text": "Memorising page numbers"}], "answer": "B", "explanation": "Active learning involves learners engaging with ideas through investigation, discussion and application."}, {"id": 307, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "A teacher adapts a task so that learners with different levels of readiness can work towards the same broad objective. This is:", "options": [{"value": "A", "text": "Differentiated instruction"}, {"value": "B", "text": "Punishment"}, {"value": "C", "text": "Fixed ability grouping"}, {"value": "D", "text": "Summative evaluation"}], "answer": "A", "explanation": "Differentiated instruction adjusts teaching, resources or support to accommodate differences among learners."}, {"id": 308, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Which statement best describes learner autonomy?", "options": [{"value": "A", "text": "Learners make appropriate choices and take increasing responsibility for learning"}, {"value": "B", "text": "Learners must complete every task without guidance"}, {"value": "C", "text": "Teachers should stop giving feedback"}, {"value": "D", "text": "Learners should never work with others"}], "answer": "A", "explanation": "Learner autonomy involves developing independence and responsibility while receiving suitable support."}, {"id": 309, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Why is questioning important in teaching?", "options": [{"value": "A", "text": "It helps teachers check understanding and encourage thinking"}, {"value": "B", "text": "It guarantees that every learner understands immediately"}, {"value": "C", "text": "It eliminates the need for lesson planning"}, {"value": "D", "text": "It is useful only during examinations"}], "answer": "A", "explanation": "Well-designed questions reveal misconceptions, stimulate reasoning and help guide instruction."}, {"id": 310, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Child-Centred Education", "question": "Which classroom arrangement can support collaborative learning?", "options": [{"value": "A", "text": "Seating and grouping that allow learners to communicate and work together"}, {"value": "B", "text": "Preventing learners from seeing one another"}, {"value": "C", "text": "Prohibiting all peer discussion"}, {"value": "D", "text": "Giving every group the same answer to copy"}], "answer": "A", "explanation": "Appropriate arrangements can make discussion, shared tasks and peer support easier."}, {"id": 311, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Individual differences among learners may arise from:", "options": [{"value": "A", "text": "Heredity and environmental experiences"}, {"value": "B", "text": "School uniform alone"}, {"value": "C", "text": "Classroom walls alone"}, {"value": "D", "text": "Examination dates alone"}], "answer": "A", "explanation": "Learner differences reflect complex interactions among genetic, developmental, cultural, social and educational factors."}, {"id": 312, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Which practice is least appropriate when dealing with individual differences?", "options": [{"value": "A", "text": "Offering varied learning activities"}, {"value": "B", "text": "Providing appropriate support"}, {"value": "C", "text": "Labelling learners permanently as weak or incapable"}, {"value": "D", "text": "Considering learners’ interests and readiness"}], "answer": "C", "explanation": "Fixed labels can limit expectations and opportunities. Teachers should focus on learners’ current needs, strengths and potential for growth."}, {"id": 313, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Creativity is best encouraged by:", "options": [{"value": "A", "text": "Allowing exploration and multiple possible solutions"}, {"value": "B", "text": "Requiring identical responses to every open-ended task"}, {"value": "C", "text": "Discouraging original ideas"}, {"value": "D", "text": "Penalising every unusual approach"}], "answer": "A", "explanation": "Creativity benefits from opportunities to explore, experiment, imagine and develop alternative solutions."}, {"id": 314, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Which activity most directly encourages fluency in creative thinking?", "options": [{"value": "A", "text": "Generating many possible uses for an everyday object"}, {"value": "B", "text": "Memorising a single definition"}, {"value": "C", "text": "Copying one answer repeatedly"}, {"value": "D", "text": "Selecting an answer without considering alternatives"}], "answer": "A", "explanation": "In creativity assessment, fluency refers to the number of relevant ideas generated."}, {"id": 315, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "In creative thinking, flexibility refers to the ability to:", "options": [{"value": "A", "text": "Produce ideas from different categories or perspectives"}, {"value": "B", "text": "Repeat the same idea many times"}, {"value": "C", "text": "Memorise a long passage"}, {"value": "D", "text": "Avoid changing one’s approach"}], "answer": "A", "explanation": "Flexibility involves shifting between different approaches, categories or ways of thinking."}, {"id": 316, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Originality in creative thinking refers mainly to:", "options": [{"value": "A", "text": "Producing relatively uncommon or novel ideas"}, {"value": "B", "text": "Repeating the most common response"}, {"value": "C", "text": "Copying a classmate’s answer"}, {"value": "D", "text": "Following a fixed procedure without variation"}], "answer": "A", "explanation": "Originality concerns the novelty or uncommonness of an idea, while still considering its relevance."}, {"id": 317, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Which approach is most suitable for a learner who finishes routine tasks quickly?", "options": [{"value": "A", "text": "Provide appropriate enrichment or extension tasks"}, {"value": "B", "text": "Stop the learner from learning further"}, {"value": "C", "text": "Assign repetitive work without a purpose"}, {"value": "D", "text": "Ask the learner to disturb classmates"}], "answer": "A", "explanation": "Enrichment gives learners opportunities to explore concepts more deeply or apply them in challenging ways."}, {"id": 318, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Which statement about intelligence tests is most appropriate?", "options": [{"value": "A", "text": "One score captures every aspect of a person"}, {"value": "B", "text": "Results should be interpreted carefully and in context"}, {"value": "C", "text": "A test score determines a learner’s future permanently"}, {"value": "D", "text": "Intelligence tests make classroom observation unnecessary"}], "answer": "B", "explanation": "Assessment results provide limited information and should be considered alongside other evidence and relevant contextual factors."}, {"id": 319, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "Which teacher practice can help reduce the harmful effects of comparison among learners?", "options": [{"value": "A", "text": "Focus on individual progress and meaningful learning goals"}, {"value": "B", "text": "Publicly rank learners for every task"}, {"value": "C", "text": "Compare every learner with the highest scorer"}, {"value": "D", "text": "Treat slower progress as proof of inability"}], "answer": "A", "explanation": "Recognising progress and providing actionable feedback supports learning without relying excessively on competition."}, {"id": 320, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Intelligence, Creativity And Individual Differences", "question": "A learner solves a problem using an unusual but valid strategy. The teacher should:", "options": [{"value": "A", "text": "Explore the learner’s reasoning and acknowledge the valid approach"}, {"value": "B", "text": "Reject the solution because it differs from the textbook"}, {"value": "C", "text": "Prevent the learner from explaining it"}, {"value": "D", "text": "Insist that only one method can ever be used"}], "answer": "A", "explanation": "Exploring alternative strategies can deepen understanding and encourage flexible thinking."}, {"id": 321, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Sensory memory briefly holds information received through:", "options": [{"value": "A", "text": "The senses"}, {"value": "B", "text": "Long-term planning alone"}, {"value": "C", "text": "Moral reasoning only"}, {"value": "D", "text": "Physical exercise only"}], "answer": "A", "explanation": "Sensory memory briefly retains incoming sensory information before it fades or receives further attention."}, {"id": 322, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Working memory is mainly involved in:", "options": [{"value": "A", "text": "Holding and manipulating information during a task"}, {"value": "B", "text": "Storing every experience permanently"}, {"value": "C", "text": "Controlling physical growth"}, {"value": "D", "text": "Determining personality alone"}], "answer": "A", "explanation": "Working memory allows learners to keep information available while using it for tasks such as mental arithmetic or following instructions."}, {"id": 323, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Which strategy can reduce unnecessary demands on working memory?", "options": [{"value": "A", "text": "Break complex instructions into manageable steps"}, {"value": "B", "text": "Give many unrelated instructions at once"}, {"value": "C", "text": "Use unfamiliar terminology without explanation"}, {"value": "D", "text": "Avoid examples"}], "answer": "A", "explanation": "Chunking information and providing clear sequences can make complex tasks easier to manage."}, {"id": 324, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Elaborative rehearsal involves:", "options": [{"value": "A", "text": "Connecting information with meaning and existing knowledge"}, {"value": "B", "text": "Repeating sounds without considering meaning"}, {"value": "C", "text": "Avoiding revision"}, {"value": "D", "text": "Copying words without understanding"}], "answer": "A", "explanation": "Elaborative rehearsal supports memory by linking new information to existing knowledge and meaningful associations."}, {"id": 325, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Which revision strategy relies most directly on active retrieval?", "options": [{"value": "A", "text": "Attempting to recall answers before checking notes"}, {"value": "B", "text": "Rereading a page passively without testing oneself"}, {"value": "C", "text": "Highlighting every sentence"}, {"value": "D", "text": "Copying the same passage repeatedly"}], "answer": "A", "explanation": "Retrieval practice requires learners to bring information to mind, strengthening access to learned material."}, {"id": 326, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Distributed practice means:", "options": [{"value": "A", "text": "Spreading practice sessions over time"}, {"value": "B", "text": "Studying all material in one uninterrupted session"}, {"value": "C", "text": "Avoiding practice"}, {"value": "D", "text": "Revising only after an examination"}], "answer": "A", "explanation": "Distributed or spaced practice spreads learning sessions across time instead of concentrating them into one long session."}, {"id": 327, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Which is the clearest example of procedural knowledge?", "options": [{"value": "A", "text": "Knowing how to perform a laboratory procedure"}, {"value": "B", "text": "Knowing the name of a scientist"}, {"value": "C", "text": "Remembering a date"}, {"value": "D", "text": "Recalling a definition without applying it"}], "answer": "A", "explanation": "Procedural knowledge concerns knowing how to carry out an action or process."}, {"id": 328, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Declarative knowledge refers mainly to:", "options": [{"value": "A", "text": "Knowing facts and information"}, {"value": "B", "text": "Performing a motor skill only"}, {"value": "C", "text": "Developing physical strength"}, {"value": "D", "text": "Following a procedure without knowing its facts"}], "answer": "A", "explanation": "Declarative knowledge includes facts, concepts and information that can often be expressed verbally."}, {"id": 329, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "Which condition is most likely to improve attention during a lesson?", "options": [{"value": "A", "text": "Clear objectives and manageable learning tasks"}, {"value": "B", "text": "Constant interruptions"}, {"value": "C", "text": "Unclear instructions"}, {"value": "D", "text": "Irrelevant information throughout"}], "answer": "A", "explanation": "Focused tasks and clear expectations can help learners direct their attention towards relevant information."}, {"id": 330, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Learning, Memory And Cognition", "question": "A learner understands a concept but cannot recall it during a test. What should the teacher consider?", "options": [{"value": "A", "text": "Possible retrieval difficulties and the conditions under which the learner practised"}, {"value": "B", "text": "That the learner has no ability to learn"}, {"value": "C", "text": "That understanding never matters"}, {"value": "D", "text": "That every test answer is a perfect measure of knowledge"}], "answer": "A", "explanation": "Performance can be affected by retrieval demands, anxiety, practice conditions and the way questions are framed."}, {"id": 331, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Empathy involves:", "options": [{"value": "A", "text": "Understanding or considering another person’s feelings and perspective"}, {"value": "B", "text": "Winning every competition"}, {"value": "C", "text": "Avoiding all relationships"}, {"value": "D", "text": "Memorising facts without context"}], "answer": "A", "explanation": "Empathy involves recognising or attempting to understand another person’s emotional experience or point of view."}, {"id": 332, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Which classroom activity can help learners practise empathy?", "options": [{"value": "A", "text": "Discussing a story from different characters’ perspectives"}, {"value": "B", "text": "Encouraging learners to mock fictional characters"}, {"value": "C", "text": "Preventing discussion of feelings"}, {"value": "D", "text": "Ranking learners by popularity"}], "answer": "A", "explanation": "Perspective-taking activities can help learners consider experiences and emotions different from their own."}, {"id": 333, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Self-regulation refers to the ability to:", "options": [{"value": "A", "text": "Manage one’s attention, emotions and behaviour in appropriate ways"}, {"value": "B", "text": "Control every other person’s decisions"}, {"value": "C", "text": "Avoid all challenges"}, {"value": "D", "text": "Memorise without understanding"}], "answer": "A", "explanation": "Self-regulation involves monitoring and managing responses in pursuit of appropriate goals."}, {"id": 334, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "A learner becomes frustrated when a task is difficult. Which response best supports emotional regulation?", "options": [{"value": "A", "text": "Help the learner pause, identify the difficulty and select a next step"}, {"value": "B", "text": "Tell the learner that frustration is unacceptable in every situation"}, {"value": "C", "text": "Publicly ridicule the learner"}, {"value": "D", "text": "Remove every future challenge"}], "answer": "A", "explanation": "Supportive strategies help learners recognise emotions and respond constructively to difficulties."}, {"id": 335, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Which approach best develops social skills?", "options": [{"value": "A", "text": "Structured cooperative tasks with opportunities to practise communication"}, {"value": "B", "text": "Preventing all interaction"}, {"value": "C", "text": "Rewarding only individual performance in every task"}, {"value": "D", "text": "Ignoring interpersonal conflicts"}], "answer": "A", "explanation": "Cooperative tasks allow learners to practise listening, sharing, negotiation and respectful communication."}, {"id": 336, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "A teacher notices that a learner is isolated by classmates. What is the most appropriate response?", "options": [{"value": "A", "text": "Address the situation sensitively and promote inclusion and safety"}, {"value": "B", "text": "Assume it is always harmless"}, {"value": "C", "text": "Publicly blame the isolated learner"}, {"value": "D", "text": "Encourage further exclusion"}], "answer": "A", "explanation": "Teachers should respond to exclusion or possible bullying using appropriate school procedures and supportive strategies."}, {"id": 337, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Which practice helps create psychological safety in a classroom?", "options": [{"value": "A", "text": "Responding respectfully when learners make mistakes or ask questions"}, {"value": "B", "text": "Mocking incorrect answers"}, {"value": "C", "text": "Threatening learners for expressing uncertainty"}, {"value": "D", "text": "Encouraging classmates to ridicule mistakes"}], "answer": "A", "explanation": "Respectful responses help learners feel more comfortable participating, asking questions and taking learning risks."}, {"id": 338, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Which behaviour demonstrates responsible conflict resolution?", "options": [{"value": "A", "text": "Listening to different viewpoints and negotiating a fair solution"}, {"value": "B", "text": "Interrupting everyone involved"}, {"value": "C", "text": "Using threats to end a disagreement"}, {"value": "D", "text": "Refusing to consider any evidence"}], "answer": "A", "explanation": "Constructive conflict resolution involves listening, understanding the problem and seeking an appropriate solution."}, {"id": 339, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Which classroom practice can promote a sense of belonging?", "options": [{"value": "A", "text": "Recognising contributions and ensuring respectful participation"}, {"value": "B", "text": "Excluding learners who need support"}, {"value": "C", "text": "Using humiliating nicknames"}, {"value": "D", "text": "Giving opportunities only to a selected few"}], "answer": "A", "explanation": "Respectful participation and recognition help learners feel valued as members of the classroom community."}, {"id": 340, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Socio-Emotional Development", "question": "Which statement about emotional development is most appropriate?", "options": [{"value": "A", "text": "Emotional skills can be supported through relationships and learning experiences"}, {"value": "B", "text": "Emotions have no influence on learning"}, {"value": "C", "text": "Every child develops emotional skills at the same rate"}, {"value": "D", "text": "Emotional development ends in early childhood"}], "answer": "A", "explanation": "Supportive relationships and opportunities to practise emotional skills can help learners develop emotional awareness and regulation."}, {"id": 341, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "The primary aim of language teaching is to develop learners’ ability to:", "options": [{"value": "A", "text": "Use language meaningfully for communication"}, {"value": "B", "text": "Memorise grammar rules without application"}, {"value": "C", "text": "Copy paragraphs only"}, {"value": "D", "text": "Avoid speaking and listening"}], "answer": "A", "explanation": "Language learning involves understanding and producing language for meaningful purposes across different contexts."}, {"id": 342, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Which activity primarily develops listening comprehension?", "options": [{"value": "A", "text": "Listening to a story and answering questions about it"}, {"value": "B", "text": "Copying a story without reading it"}, {"value": "C", "text": "Memorising punctuation marks only"}, {"value": "D", "text": "Drawing unrelated pictures"}], "answer": "A", "explanation": "Listening tasks require learners to process spoken information and demonstrate understanding."}, {"id": 343, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Which strategy is most suitable for supporting early reading?", "options": [{"value": "A", "text": "Connect sounds, letters and meaningful words through structured practice"}, {"value": "B", "text": "Require learners to memorise long passages immediately"}, {"value": "C", "text": "Avoid reading aloud or guided practice"}, {"value": "D", "text": "Correct every error through humiliation"}], "answer": "A", "explanation": "Early reading instruction benefits from explicit, systematic support in foundational literacy skills, along with meaningful reading experiences."}, {"id": 344, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Reading comprehension involves:", "options": [{"value": "A", "text": "Constructing meaning from written text"}, {"value": "B", "text": "Recognising letters only"}, {"value": "C", "text": "Copying words without understanding"}, {"value": "D", "text": "Counting the pages in a book"}], "answer": "A", "explanation": "Comprehension requires learners to interpret information, connect ideas and draw appropriate inferences."}, {"id": 345, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Which activity can help learners develop writing skills?", "options": [{"value": "A", "text": "Planning, drafting, revising and editing a piece of writing"}, {"value": "B", "text": "Copying a final paragraph without discussion"}, {"value": "C", "text": "Avoiding feedback"}, {"value": "D", "text": "Memorising punctuation without writing"}], "answer": "A", "explanation": "Writing develops through a process that includes planning ideas, composing, reviewing and improving the text."}, {"id": 346, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Grammar is most meaningfully taught when:", "options": [{"value": "A", "text": "Learners examine how grammatical forms work in meaningful language contexts"}, {"value": "B", "text": "Learners memorise rules without any examples"}, {"value": "C", "text": "Teachers prevent learners from using language"}, {"value": "D", "text": "Every lesson consists only of rule copying"}], "answer": "A", "explanation": "Contextualised grammar instruction connects language forms with their functions and use."}, {"id": 347, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Which response is most appropriate when a learner makes a language error while communicating an understandable idea?", "options": [{"value": "A", "text": "Respond to the meaning and provide suitable correction when helpful"}, {"value": "B", "text": "Stop the learner from speaking again"}, {"value": "C", "text": "Publicly ridicule the error"}, {"value": "D", "text": "Ignore all language development needs permanently"}], "answer": "A", "explanation": "Supportive correction can help learners improve accuracy without unnecessarily discouraging communication."}, {"id": 348, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Which classroom resource is particularly useful for developing vocabulary?", "options": [{"value": "A", "text": "Word walls with examples and meaningful usage"}, {"value": "B", "text": "A list of unrelated numbers"}, {"value": "C", "text": "An attendance register alone"}, {"value": "D", "text": "A timetable with no language content"}], "answer": "A", "explanation": "Word walls can make vocabulary visible and support repeated exposure, recall and meaningful use."}, {"id": 349, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "In multilingual education, learners’ home languages can:", "options": [{"value": "A", "text": "Serve as resources for connecting prior knowledge with new learning"}, {"value": "B", "text": "Never support learning"}, {"value": "C", "text": "Always prevent additional language acquisition"}, {"value": "D", "text": "Be treated as evidence of low intelligence"}], "answer": "A", "explanation": "Learners’ existing languages can support understanding, identity and the development of additional languages when used appropriately."}, {"id": 350, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Language Pedagogy", "question": "Which assessment best evaluates oral communication?", "options": [{"value": "A", "text": "A suitable speaking task assessed with clear criteria"}, {"value": "B", "text": "A handwriting test only"}, {"value": "C", "text": "A silent copying task"}, {"value": "D", "text": "A physical fitness test"}], "answer": "A", "explanation": "Oral communication is best assessed through relevant speaking and listening tasks with transparent criteria."}, {"id": 351, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Mathematics teaching should ideally help learners develop:", "options": [{"value": "A", "text": "Conceptual understanding and problem-solving skills"}, {"value": "B", "text": "Memorisation without meaning only"}, {"value": "C", "text": "Fear of making mistakes"}, {"value": "D", "text": "Dependence on answer keys alone"}], "answer": "A", "explanation": "Effective mathematics teaching combines understanding of concepts, procedural fluency, reasoning and application."}, {"id": 352, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "A learner repeatedly makes errors while borrowing in subtraction. What should the teacher do?", "options": [{"value": "A", "text": "Examine the learner’s method and provide targeted practice"}, {"value": "B", "text": "Ask the learner to memorise the answer"}, {"value": "C", "text": "Assume the learner cannot learn mathematics"}, {"value": "D", "text": "Avoid explaining the procedure"}], "answer": "A", "explanation": "Understanding the source of the error helps the teacher address the specific misconception or procedural difficulty."}, {"id": 353, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Manipulatives such as counters and blocks can help learners:", "options": [{"value": "A", "text": "Represent mathematical ideas concretely"}, {"value": "B", "text": "Avoid all mathematical thinking"}, {"value": "C", "text": "Replace every explanation permanently"}, {"value": "D", "text": "Memorise unrelated facts"}], "answer": "A", "explanation": "Concrete materials can help learners model quantities and relationships before moving towards more abstract representations."}, {"id": 354, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Which is the best example of mathematical reasoning?", "options": [{"value": "A", "text": "Explaining why a solution works"}, {"value": "B", "text": "Copying an answer without checking it"}, {"value": "C", "text": "Memorising a page number"}, {"value": "D", "text": "Repeating a formula without understanding"}], "answer": "A", "explanation": "Mathematical reasoning involves explaining, justifying and examining relationships between mathematical ideas."}, {"id": 355, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Science education should encourage learners to:", "options": [{"value": "A", "text": "Observe, question, investigate and use evidence"}, {"value": "B", "text": "Accept every claim without examination"}, {"value": "C", "text": "Memorise conclusions without understanding"}, {"value": "D", "text": "Avoid experiments and observations"}], "answer": "A", "explanation": "Scientific learning involves inquiry, evidence-based reasoning and the evaluation of explanations."}, {"id": 356, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "In a fair scientific test, the investigator should generally:", "options": [{"value": "A", "text": "Change the factor being tested while controlling relevant variables"}, {"value": "B", "text": "Change every variable without recording it"}, {"value": "C", "text": "Ignore observations"}, {"value": "D", "text": "Decide the conclusion before collecting evidence"}], "answer": "A", "explanation": "In a controlled investigation, relevant variables are managed so the effect of the factor being studied can be examined more clearly."}, {"id": 357, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "A learner predicts that plants grow better in sunlight. What is the best next step in an inquiry activity?", "options": [{"value": "A", "text": "Plan a suitable investigation and collect observations"}, {"value": "B", "text": "Accept the prediction as proven"}, {"value": "C", "text": "Avoid recording results"}, {"value": "D", "text": "Copy the conclusion from a textbook without investigation"}], "answer": "A", "explanation": "A prediction should be examined through an appropriate investigation and evidence."}, {"id": 358, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Which classroom practice helps address science misconceptions?", "options": [{"value": "A", "text": "Ask learners to explain their thinking and compare it with evidence"}, {"value": "B", "text": "Ignore their explanations"}, {"value": "C", "text": "Demand memorisation only"}, {"value": "D", "text": "Prevent practical investigation"}], "answer": "A", "explanation": "Making learners’ ideas explicit allows teachers to identify misconceptions and use evidence to develop understanding."}, {"id": 359, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Environmental education aims to develop:", "options": [{"value": "A", "text": "Awareness, understanding and responsible action related to the environment"}, {"value": "B", "text": "Knowledge of definitions alone"}, {"value": "C", "text": "Indifference towards environmental issues"}, {"value": "D", "text": "Competition without understanding"}], "answer": "A", "explanation": "Environmental education connects knowledge and values with informed decisions and responsible action."}, {"id": 360, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Mathematics And Science Pedagogy", "question": "Which activity best connects science with everyday life?", "options": [{"value": "A", "text": "Investigating household water use and conservation"}, {"value": "B", "text": "Copying a chapter without discussion"}, {"value": "C", "text": "Memorising page numbers"}, {"value": "D", "text": "Avoiding local examples"}], "answer": "A", "explanation": "Real-world investigations help learners connect scientific ideas to familiar experiences and practical decisions."}, {"id": 361, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Social science education can help learners develop:", "options": [{"value": "A", "text": "Understanding of society, institutions and human relationships"}, {"value": "B", "text": "Memorisation of names only"}, {"value": "C", "text": "Avoidance of current social questions"}, {"value": "D", "text": "Physical growth alone"}], "answer": "A", "explanation": "Social science examines people, communities, institutions, history, geography and social processes."}, {"id": 362, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Which classroom activity best develops historical thinking?", "options": [{"value": "A", "text": "Examine sources and compare different accounts of an event"}, {"value": "B", "text": "Memorise dates without context"}, {"value": "C", "text": "Copy a timeline without discussion"}, {"value": "D", "text": "Assume every historical source is equally reliable"}], "answer": "A", "explanation": "Historical thinking involves interpreting evidence, understanding context and evaluating accounts of the past."}, {"id": 363, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Which activity best develops geographical understanding?", "options": [{"value": "A", "text": "Interpret a map and explain spatial relationships"}, {"value": "B", "text": "Memorise a list of unrelated words"}, {"value": "C", "text": "Avoid using maps"}, {"value": "D", "text": "Copy a paragraph without identifying locations"}], "answer": "A", "explanation": "Map interpretation helps learners understand location, direction, patterns and relationships between places."}, {"id": 364, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Civic education aims to help learners understand:", "options": [{"value": "A", "text": "Rights, responsibilities and participation in society"}, {"value": "B", "text": "Only the names of political leaders"}, {"value": "C", "text": "School rules alone"}, {"value": "D", "text": "Competition without cooperation"}], "answer": "A", "explanation": "Civic education develops knowledge of citizenship, public institutions, rights, responsibilities and participation."}, {"id": 365, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Which practice best promotes democratic values at school?", "options": [{"value": "A", "text": "Encourage respectful dialogue and fair participation"}, {"value": "B", "text": "Prevent learners from expressing opinions"}, {"value": "C", "text": "Allow only one viewpoint"}, {"value": "D", "text": "Reward intimidation"}], "answer": "A", "explanation": "Democratic values include participation, respect, fairness and constructive discussion."}, {"id": 366, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Environmental sustainability involves:", "options": [{"value": "A", "text": "Meeting present needs while considering future generations"}, {"value": "B", "text": "Using resources without limits"}, {"value": "C", "text": "Ignoring environmental consequences"}, {"value": "D", "text": "Preventing all development in every context"}], "answer": "A", "explanation": "Sustainability involves balancing environmental, social and economic considerations over time."}, {"id": 367, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "A teacher asks learners to interview community members about changes in their neighbourhood. This supports:", "options": [{"value": "A", "text": "Learning through local evidence and community knowledge"}, {"value": "B", "text": "Memorisation only"}, {"value": "C", "text": "Avoiding social interaction"}, {"value": "D", "text": "Replacing all classroom instruction permanently"}], "answer": "A", "explanation": "Community interviews can connect classroom learning with lived experiences and local perspectives."}, {"id": 368, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Which activity best develops media literacy?", "options": [{"value": "A", "text": "Evaluate the source and evidence behind a news claim"}, {"value": "B", "text": "Believe every online post immediately"}, {"value": "C", "text": "Share information without checking it"}, {"value": "D", "text": "Ignore the author and date of a source"}], "answer": "A", "explanation": "Media literacy includes assessing credibility, evidence, context and potential bias."}, {"id": 369, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "A teacher discusses how communities with different traditions celebrate important events. This can promote:", "options": [{"value": "A", "text": "Cultural awareness and respect"}, {"value": "B", "text": "The idea that only one culture matters"}, {"value": "C", "text": "Stereotyping"}, {"value": "D", "text": "Exclusion of minority viewpoints"}], "answer": "A", "explanation": "Respectful exploration of cultural diversity can support understanding and challenge stereotypes."}, {"id": 370, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Social Science And Environmental Learning", "question": "Which strategy best helps learners understand a complex social issue?", "options": [{"value": "A", "text": "Examine multiple perspectives and relevant evidence"}, {"value": "B", "text": "Accept one unsupported claim"}, {"value": "C", "text": "Avoid discussion"}, {"value": "D", "text": "Memorise a slogan without analysis"}], "answer": "A", "explanation": "Complex social issues are better understood through evidence, context and consideration of different viewpoints."}, {"id": 371, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "Reflective practice requires teachers to:", "options": [{"value": "A", "text": "Examine their teaching and identify ways to improve"}, {"value": "B", "text": "Repeat every lesson unchanged"}, {"value": "C", "text": "Ignore learner feedback"}, {"value": "D", "text": "Avoid professional learning"}], "answer": "A", "explanation": "Reflection helps teachers evaluate the effectiveness of their methods and plan improvements."}, {"id": 372, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "Which action demonstrates professional ethics?", "options": [{"value": "A", "text": "Treat learners fairly and protect confidential information"}, {"value": "B", "text": "Publicly share private learner records"}, {"value": "C", "text": "Discriminate among learners"}, {"value": "D", "text": "Use school resources for unauthorised personal purposes"}], "answer": "A", "explanation": "Professional ethics includes fairness, confidentiality, responsibility and respect for learners."}, {"id": 373, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "A teacher is unsure how to support a learner with a specific educational need. What should the teacher do?", "options": [{"value": "A", "text": "Seek appropriate guidance and collaborate with relevant professionals"}, {"value": "B", "text": "Ignore the learner’s needs"}, {"value": "C", "text": "Make unsupported assumptions"}, {"value": "D", "text": "Exclude the learner from lessons"}], "answer": "A", "explanation": "Collaboration can help teachers identify suitable support while respecting the learner’s needs and school procedures."}, {"id": 374, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "Effective parent-teacher communication should be:", "options": [{"value": "A", "text": "Respectful, clear and focused on supporting the learner"}, {"value": "B", "text": "Based only on blame"}, {"value": "C", "text": "Shared publicly with unrelated people"}, {"value": "D", "text": "Limited to discussing failures"}], "answer": "A", "explanation": "Constructive communication helps families and teachers understand progress, concerns and possible support strategies."}, {"id": 375, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "School-based professional development is most useful when it:", "options": [{"value": "A", "text": "Addresses teachers’ needs and supports improved classroom practice"}, {"value": "B", "text": "Is unrelated to teaching"}, {"value": "C", "text": "Prevents collaboration"}, {"value": "D", "text": "Requires no reflection or application"}], "answer": "A", "explanation": "Relevant professional development connects learning with classroom challenges, practical strategies and ongoing improvement."}, {"id": 376, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "Which practice supports effective teamwork among teachers?", "options": [{"value": "A", "text": "Sharing useful resources and discussing learner progress appropriately"}, {"value": "B", "text": "Withholding all information from colleagues"}, {"value": "C", "text": "Blaming colleagues for every problem"}, {"value": "D", "text": "Refusing to coordinate related teaching activities"}], "answer": "A", "explanation": "Professional collaboration can improve planning, consistency and learner support while respecting confidentiality."}, {"id": 377, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "Which is an appropriate response to a suspected child-protection concern?", "options": [{"value": "A", "text": "Follow applicable safeguarding procedures and report through the appropriate channels"}, {"value": "B", "text": "Promise absolute secrecy regardless of risk"}, {"value": "C", "text": "Investigate alone without following school procedures"}, {"value": "D", "text": "Discuss the child’s information publicly"}], "answer": "A", "explanation": "Teachers should take safeguarding concerns seriously, follow applicable laws and school procedures, and avoid inappropriate disclosure or unsupported investigation."}, {"id": 378, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "A teacher notices a possible mistake in a student’s assessment score. What should the teacher do?", "options": [{"value": "A", "text": "Check the work and correct the record if needed"}, {"value": "B", "text": "Ignore the issue"}, {"value": "C", "text": "Refuse to review the evidence"}, {"value": "D", "text": "Change other learners’ marks to compensate"}], "answer": "A", "explanation": "Fair assessment requires accurate records and appropriate correction of verified errors."}, {"id": 379, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "Which approach best supports continuous improvement in teaching?", "options": [{"value": "A", "text": "Combine reflection, learner evidence and professional learning"}, {"value": "B", "text": "Avoid feedback and reflection"}, {"value": "C", "text": "Use only personal assumptions"}, {"value": "D", "text": "Reject every new teaching strategy"}], "answer": "A", "explanation": "Ongoing improvement relies on evidence, reflection and a willingness to adapt practice."}, {"id": 380, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Teacher Professionalism And School Practice", "question": "A teacher wants to improve participation in class. Which first step is most useful?", "options": [{"value": "A", "text": "Observe participation patterns and identify possible barriers"}, {"value": "B", "text": "Assume learners are not interested"}, {"value": "C", "text": "Punish quiet learners"}, {"value": "D", "text": "Stop asking questions"}], "answer": "A", "explanation": "Understanding when and why participation varies helps teachers choose suitable strategies."}, {"id": 381, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Action research is commonly conducted by teachers to:", "options": [{"value": "A", "text": "Investigate and improve a practical teaching or learning problem"}, {"value": "B", "text": "Replace all educational policy"}, {"value": "C", "text": "Avoid gathering evidence"}, {"value": "D", "text": "Guarantee a predetermined result"}], "answer": "A", "explanation": "Action research involves systematic inquiry into a local problem, followed by reflection and possible changes in practice."}, {"id": 382, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Which is an appropriate first step when investigating a classroom problem?", "options": [{"value": "A", "text": "Define the problem clearly"}, {"value": "B", "text": "Decide the conclusion before gathering information"}, {"value": "C", "text": "Ignore existing evidence"}, {"value": "D", "text": "Change many unrelated factors without a plan"}], "answer": "A", "explanation": "A clear research question helps determine what information should be collected and how it will be analysed."}, {"id": 383, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Which source provides quantitative data?", "options": [{"value": "A", "text": "Numerical scores from a mathematics test"}, {"value": "B", "text": "A descriptive interview transcript only"}, {"value": "C", "text": "A narrative account without numerical coding"}, {"value": "D", "text": "An open-ended reflection alone"}], "answer": "A", "explanation": "Quantitative data are expressed numerically and can be analysed using appropriate statistical methods."}, {"id": 384, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Which source is most clearly qualitative data?", "options": [{"value": "A", "text": "An interview transcript describing learners’ experiences"}, {"value": "B", "text": "A total test score"}, {"value": "C", "text": "The number of students present"}, {"value": "D", "text": "A percentage calculated from marks"}], "answer": "A", "explanation": "Qualitative data describe experiences, perspectives or events through words, observations and other non-numerical information."}, {"id": 385, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Why is it important to use multiple sources of evidence when appropriate?", "options": [{"value": "A", "text": "Different sources can provide a fuller understanding of a problem"}, {"value": "B", "text": "It guarantees that every conclusion is correct"}, {"value": "C", "text": "It removes the need to analyse evidence"}, {"value": "D", "text": "It allows unsupported assumptions"}], "answer": "A", "explanation": "Combining sources can reveal patterns and help teachers interpret findings more carefully."}, {"id": 386, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Which statement best describes a hypothesis?", "options": [{"value": "A", "text": "A proposed explanation or prediction that can be examined"}, {"value": "B", "text": "A conclusion that must never be tested"}, {"value": "C", "text": "An unrelated opinion"}, {"value": "D", "text": "A record of attendance"}], "answer": "A", "explanation": "A hypothesis is a tentative statement that can be investigated using appropriate evidence."}, {"id": 387, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Which practice supports ethical educational research involving learners?", "options": [{"value": "A", "text": "Obtain appropriate permission and protect participants’ privacy"}, {"value": "B", "text": "Publish names and private details without permission"}, {"value": "C", "text": "Force participation without regard to applicable requirements"}, {"value": "D", "text": "Fabricate results to support a claim"}], "answer": "A", "explanation": "Ethical research requires appropriate consent or permission, privacy protections and honest reporting."}, {"id": 388, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "A teacher compares reading results before and after an intervention. What should the teacher remember when interpreting the results?", "options": [{"value": "A", "text": "Improvement may be associated with the intervention, but other factors may also matter"}, {"value": "B", "text": "Any improvement proves the intervention was the only cause"}, {"value": "C", "text": "Results never provide useful information"}, {"value": "D", "text": "One comparison always proves a universal rule"}], "answer": "A", "explanation": "Before-and-after comparisons can be informative, but without an appropriate design they do not automatically establish causation."}, {"id": 389, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Which graph is often suitable for comparing numerical results across several categories?", "options": [{"value": "A", "text": "Bar chart"}, {"value": "B", "text": "Decorative picture without a scale"}, {"value": "C", "text": "Unlabelled shape"}, {"value": "D", "text": "Random line drawing"}], "answer": "A", "explanation": "Bar charts are commonly used to compare values across discrete categories."}, {"id": 390, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Educational Research And Evaluation", "question": "Why should educational conclusions be based on evidence?", "options": [{"value": "A", "text": "Evidence supports more reasoned decisions and reduces reliance on assumptions"}, {"value": "B", "text": "Evidence guarantees perfect certainty in every case"}, {"value": "C", "text": "Evidence makes professional judgement unnecessary"}, {"value": "D", "text": "Evidence is useful only for examinations"}], "answer": "A", "explanation": "Evidence-informed decisions are generally more defensible than decisions based solely on assumptions, though evidence still needs careful interpretation."}, {"id": 391, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "A teacher finds that learners can repeat a scientific definition but cannot explain the phenomenon. Which strategy is most appropriate?", "options": [{"value": "A", "text": "Use demonstrations, examples and questions that connect the definition to observations"}, {"value": "B", "text": "Ask learners to repeat the definition more loudly"}, {"value": "C", "text": "Stop teaching the topic"}, {"value": "D", "text": "Give marks only for memorisation"}], "answer": "A", "explanation": "Connecting language with observations and explanation supports conceptual understanding rather than recall alone."}, {"id": 392, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "A learner makes progress when tasks are divided into smaller steps. This suggests that the teacher should:", "options": [{"value": "A", "text": "Continue providing suitable structure and gradually encourage independence"}, {"value": "B", "text": "Remove all support immediately"}, {"value": "C", "text": "Assume the learner cannot perform complex tasks"}, {"value": "D", "text": "Stop offering challenging activities"}], "answer": "A", "explanation": "Structured support can help learners master complex tasks and gradually take greater responsibility."}, {"id": 393, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "A teacher asks learners to identify the strongest evidence for a claim. Which skill is being emphasised?", "options": [{"value": "A", "text": "Critical evaluation"}, {"value": "B", "text": "Handwriting speed"}, {"value": "C", "text": "Physical coordination"}, {"value": "D", "text": "Simple repetition"}], "answer": "A", "explanation": "Evaluating evidence involves judging the relevance and strength of information supporting a claim."}, {"id": 394, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "A learner understands a topic during discussion but struggles to express the answer in writing. What should the teacher consider?", "options": [{"value": "A", "text": "Assess the learner’s understanding separately from writing demands where appropriate"}, {"value": "B", "text": "Assume the learner has no understanding"}, {"value": "C", "text": "Avoid offering writing support"}, {"value": "D", "text": "Give the learner no opportunity to demonstrate knowledge"}], "answer": "A", "explanation": "When writing is not the skill being assessed, suitable alternative response methods may help reveal subject understanding. Writing development can still be supported separately."}, {"id": 395, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "During a lesson, a teacher notices that one example is confusing several learners. What should the teacher do?", "options": [{"value": "A", "text": "Use a clearer example and check whether understanding improves"}, {"value": "B", "text": "Repeat the same explanation without checking"}, {"value": "C", "text": "Blame the learners"}, {"value": "D", "text": "Ignore the confusion"}], "answer": "A", "explanation": "Teaching should adapt when evidence suggests that the current explanation is not effective."}, {"id": 396, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "Learners develop different solutions to the same open-ended problem. Which response is best?", "options": [{"value": "A", "text": "Compare their strategies and examine their strengths and limitations"}, {"value": "B", "text": "Reject every solution that differs from the teacher’s first idea"}, {"value": "C", "text": "Permit only one learner to explain"}, {"value": "D", "text": "Avoid discussing the solutions"}], "answer": "A", "explanation": "Comparing approaches helps learners develop reasoning, flexibility and a deeper understanding of the problem."}, {"id": 397, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "A teacher wants to encourage independent reading. Which practice may help?", "options": [{"value": "A", "text": "Provide accessible, interesting reading choices and regular reading opportunities"}, {"value": "B", "text": "Force every learner to read the same difficult text at all times"}, {"value": "C", "text": "Prevent learners from choosing books"}, {"value": "D", "text": "Assess reading only through memorised definitions"}], "answer": "A", "explanation": "Appropriate choice, access and consistent practice can encourage reading engagement and development."}, {"id": 398, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "A learner receives low marks despite working hard. What should the teacher do?", "options": [{"value": "A", "text": "Review the learner’s understanding, strategies and support needs"}, {"value": "B", "text": "Assume effort has no value"}, {"value": "C", "text": "Publicly compare the learner with classmates"}, {"value": "D", "text": "Stop providing feedback"}], "answer": "A", "explanation": "Reviewing work and learning strategies can identify what needs to change and how to provide more effective support."}, {"id": 399, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "Which activity best develops reflective learning?", "options": [{"value": "A", "text": "Ask learners to identify what they understood, what challenged them and what they will try next"}, {"value": "B", "text": "Ask learners to copy the answer key"}, {"value": "C", "text": "Prevent learners from discussing difficulties"}, {"value": "D", "text": "Focus only on finishing the textbook"}], "answer": "A", "explanation": "Reflection helps learners monitor progress, recognise difficulties and plan future learning strategies."}, {"id": 400, "part": 4, "partName": "Part 4", "partSubject": "Educational Psychology, Pedagogy, Inclusive Education, Language Learning & Educational Practice", "section": "Application-Based Ktet Practice", "question": "Which statement best summarises effective, inclusive pedagogy?", "options": [{"value": "A", "text": "Use one method for all learners regardless of need"}, {"value": "B", "text": "Set clear goals, provide suitable support, assess learning and adapt teaching"}, {"value": "C", "text": "Focus exclusively on final marks"}, {"value": "D", "text": "Avoid feedback and reflection"}], "answer": "B", "explanation": "Effective inclusive teaching combines purposeful planning, learner participation, appropriate support, assessment and continuous improvement."}, {"id": 401, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "Which principle of development states that development proceeds from the head towards the feet?", "options": [{"value": "A", "text": "Proximodistal principle"}, {"value": "B", "text": "Cephalocaudal principle"}, {"value": "C", "text": "General-to-specific principle"}, {"value": "D", "text": "Individual-difference principle"}], "answer": "B", "explanation": "Cephalocaudal development proceeds from the head towards the lower parts of the body."}, {"id": 402, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "Which of the following best describes maturation?", "options": [{"value": "A", "text": "Learning through punishment"}, {"value": "B", "text": "Changes resulting primarily from biological growth"}, {"value": "C", "text": "Memorising information"}, {"value": "D", "text": "Learning through imitation alone"}], "answer": "B", "explanation": "Maturation refers to biologically based changes that occur as an individual grows."}, {"id": 403, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "A teacher considers learners’ previous knowledge before introducing a new topic. This reflects:", "options": [{"value": "A", "text": "Meaningful learning"}, {"value": "B", "text": "Rote learning"}, {"value": "C", "text": "Mechanical punishment"}, {"value": "D", "text": "Passive learning"}], "answer": "A", "explanation": "Connecting new information with prior knowledge helps learners develop meaningful understanding."}, {"id": 404, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "According to Piaget, the ability to think logically about concrete objects develops during which stage?", "options": [{"value": "A", "text": "Sensorimotor"}, {"value": "B", "text": "Preoperational"}, {"value": "C", "text": "Concrete operational"}, {"value": "D", "text": "Formal operational"}], "answer": "C", "explanation": "Children in the concrete operational stage can reason logically about concrete situations."}, {"id": 405, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "Which concept did Vygotsky use to describe tasks learners can perform with appropriate assistance?", "options": [{"value": "A", "text": "Classical conditioning"}, {"value": "B", "text": "Zone of Proximal Development"}, {"value": "C", "text": "Trial-and-error learning"}, {"value": "D", "text": "Cognitive dissonance"}], "answer": "B", "explanation": "The ZPD represents the gap between independent performance and performance with suitable guidance."}, {"id": 406, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "A teacher provides hints and gradually reduces support as learners become independent. This is called:", "options": [{"value": "A", "text": "Scaffolding"}, {"value": "B", "text": "Conditioning"}, {"value": "C", "text": "Punishment"}, {"value": "D", "text": "Summative assessment"}], "answer": "A", "explanation": "Scaffolding is temporary support that helps learners master a task independently."}, {"id": 407, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "Which of the following is an example of intrinsic motivation?", "options": [{"value": "A", "text": "Studying only to receive a prize"}, {"value": "B", "text": "Completing work to avoid punishment"}, {"value": "C", "text": "Reading because the subject is interesting"}, {"value": "D", "text": "Studying only to impress parents"}], "answer": "C", "explanation": "Intrinsic motivation arises from interest, curiosity or satisfaction within the learner."}, {"id": 408, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "Which theorist is most closely associated with the hierarchy of needs?", "options": [{"value": "A", "text": "Abraham Maslow"}, {"value": "B", "text": "Ivan Pavlov"}, {"value": "C", "text": "Edward Thorndike"}, {"value": "D", "text": "Jean Piaget"}], "answer": "A", "explanation": "Maslow proposed a hierarchy of human needs, including physiological, safety, belonging, esteem and self-actualisation needs."}, {"id": 409, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "A child learns to solve a puzzle by trying different methods until one works. This illustrates:", "options": [{"value": "A", "text": "Trial-and-error learning"}, {"value": "B", "text": "Classical conditioning"}, {"value": "C", "text": "Observational extinction"}, {"value": "D", "text": "Rote memorisation"}], "answer": "A", "explanation": "In trial-and-error learning, different responses are attempted until an effective solution is found."}, {"id": 410, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Child Development And Educational Psychology", "question": "Which classroom practice best supports individual differences?", "options": [{"value": "A", "text": "Giving every learner exactly the same support"}, {"value": "B", "text": "Using varied teaching methods and suitable support"}, {"value": "C", "text": "Comparing learners publicly"}, {"value": "D", "text": "Teaching only the fastest learners"}], "answer": "B", "explanation": "Learners differ in readiness, interests, abilities and learning needs."}, {"id": 411, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "Who is associated with classical conditioning?", "options": [{"value": "A", "text": "B. F. Skinner"}, {"value": "B", "text": "Ivan Pavlov"}, {"value": "C", "text": "Albert Bandura"}, {"value": "D", "text": "Jerome Bruner"}], "answer": "B", "explanation": "Pavlov demonstrated classical conditioning through experiments involving dogs and conditioned responses."}, {"id": 412, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "Operant conditioning is primarily associated with:", "options": [{"value": "A", "text": "B. F. Skinner"}, {"value": "B", "text": "Lev Vygotsky"}, {"value": "C", "text": "Jean Piaget"}, {"value": "D", "text": "Noam Chomsky"}], "answer": "A", "explanation": "Skinner studied how consequences influence the likelihood of behaviour."}, {"id": 413, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "A teacher praises a learner for helping classmates, increasing the likelihood of similar behaviour. This is:", "options": [{"value": "A", "text": "Positive reinforcement"}, {"value": "B", "text": "Negative reinforcement"}, {"value": "C", "text": "Extinction"}, {"value": "D", "text": "Classical conditioning only"}], "answer": "A", "explanation": "Positive reinforcement involves adding a desirable consequence to strengthen behaviour."}, {"id": 414, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "Which statement best describes observational learning?", "options": [{"value": "A", "text": "Learning only through direct rewards"}, {"value": "B", "text": "Learning by observing and imitating others"}, {"value": "C", "text": "Learning only through repetition"}, {"value": "D", "text": "Learning without attention"}], "answer": "B", "explanation": "Bandura highlighted the role of observation, modelling and imitation in learning."}, {"id": 415, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "In constructivist teaching, learners are encouraged to:", "options": [{"value": "A", "text": "Memorise every statement without questioning"}, {"value": "B", "text": "Construct understanding through active engagement"}, {"value": "C", "text": "Remain silent throughout lessons"}, {"value": "D", "text": "Depend entirely on textbook answers"}], "answer": "B", "explanation": "Constructivism views learners as active participants in building knowledge."}, {"id": 416, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "Which approach is most suitable for developing problem-solving skills?", "options": [{"value": "A", "text": "Repeated copying"}, {"value": "B", "text": "Inquiry-based learning"}, {"value": "C", "text": "Dictation alone"}, {"value": "D", "text": "Memorisation without application"}], "answer": "B", "explanation": "Inquiry-based learning encourages learners to ask questions, investigate evidence and develop solutions."}, {"id": 417, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "A learner can explain a concept in a new situation. This indicates:", "options": [{"value": "A", "text": "Transfer of learning"}, {"value": "B", "text": "Mechanical repetition"}, {"value": "C", "text": "Forgetting"}, {"value": "D", "text": "Physical maturation only"}], "answer": "A", "explanation": "Transfer occurs when knowledge or skills learned in one context are applied in another."}, {"id": 418, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "Which of the following best represents experiential learning?", "options": [{"value": "A", "text": "Learning through meaningful direct experience and reflection"}, {"value": "B", "text": "Copying notes without understanding"}, {"value": "C", "text": "Listening without participation in every lesson"}, {"value": "D", "text": "Memorising definitions only"}], "answer": "A", "explanation": "Experiential learning involves learning from experience, often followed by reflection and application."}, {"id": 419, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "A teacher asks learners to predict an experiment’s outcome before conducting it. This promotes:", "options": [{"value": "A", "text": "Scientific thinking"}, {"value": "B", "text": "Passive memorisation"}, {"value": "C", "text": "Blind acceptance"}, {"value": "D", "text": "Mechanical copying"}], "answer": "A", "explanation": "Making predictions encourages learners to use prior knowledge and test ideas against evidence."}, {"id": 420, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Learning Theories And Classroom Application", "question": "Which practice is most likely to promote long-term retention?", "options": [{"value": "A", "text": "Meaningful connections and spaced revision"}, {"value": "B", "text": "Studying everything once immediately before an exam"}, {"value": "C", "text": "Copying without understanding"}, {"value": "D", "text": "Avoiding practice"}], "answer": "A", "explanation": "Connecting ideas and revisiting information over time can strengthen retention."}, {"id": 421, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "The main aim of inclusive education is to:", "options": [{"value": "A", "text": "Separate all learners by ability"}, {"value": "B", "text": "Provide meaningful learning opportunities for diverse learners together"}, {"value": "C", "text": "Teach only learners without disabilities"}, {"value": "D", "text": "Remove individual support"}], "answer": "B", "explanation": "Inclusive education aims to reduce barriers and support participation and learning for all learners."}, {"id": 422, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "A learner with a visual impairment needs access to printed learning material. Which adaptation may help?", "options": [{"value": "A", "text": "Providing suitable accessible formats"}, {"value": "B", "text": "Removing the learner from all activities"}, {"value": "C", "text": "Giving only oral examinations in every situation without considering needs"}, {"value": "D", "text": "Reducing all learning expectations automatically"}], "answer": "A", "explanation": "Accessible materials may include Braille, large print, audio or digital formats, depending on the learner’s needs."}, {"id": 423, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Universal Design for Learning encourages teachers to provide:", "options": [{"value": "A", "text": "One method of presentation for everyone"}, {"value": "B", "text": "Multiple means of engagement, representation and action or expression"}, {"value": "C", "text": "Identical assessments regardless of access needs"}, {"value": "D", "text": "Only printed textbooks"}], "answer": "B", "explanation": "UDL promotes flexible learning experiences that accommodate learner variability."}, {"id": 424, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Which is an appropriate strategy for a learner with hearing impairment?", "options": [{"value": "A", "text": "Speaking while facing away from the class"}, {"value": "B", "text": "Using visual supports and ensuring clear communication"}, {"value": "C", "text": "Giving instructions only from another room"}, {"value": "D", "text": "Avoiding all group activities"}], "answer": "B", "explanation": "Visual cues, clear communication and suitable accommodations can improve access to learning."}, {"id": 425, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Dyslexia is primarily associated with difficulties in:", "options": [{"value": "A", "text": "Reading and word recognition"}, {"value": "B", "text": "Physical growth"}, {"value": "C", "text": "Hearing every sound"}, {"value": "D", "text": "Social interest alone"}], "answer": "A", "explanation": "Dyslexia is a learning difficulty that commonly affects accurate or fluent word reading and spelling."}, {"id": 426, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Which approach is suitable for supporting learners with dyscalculia?", "options": [{"value": "A", "text": "Providing structured, explicit mathematics instruction"}, {"value": "B", "text": "Increasing speed pressure"}, {"value": "C", "text": "Avoiding mathematical representations"}, {"value": "D", "text": "Using punishment for mistakes"}], "answer": "A", "explanation": "Clear explanations, concrete materials, guided practice and gradual progression can support mathematical learning."}, {"id": 427, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "A teacher notices that a learner consistently struggles with classroom tasks. What should the teacher do first?", "options": [{"value": "A", "text": "Label the learner as incapable"}, {"value": "B", "text": "Observe the difficulties and identify possible barriers and support needs"}, {"value": "C", "text": "Immediately exclude the learner"}, {"value": "D", "text": "Ignore the problem"}], "answer": "B", "explanation": "Careful observation and appropriate assessment help teachers plan suitable support without labelling learners."}, {"id": 428, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Which statement about gifted learners is most appropriate?", "options": [{"value": "A", "text": "They never need teacher support"}, {"value": "B", "text": "They may benefit from enrichment and appropriately challenging tasks"}, {"value": "C", "text": "They should always teach the entire class"}, {"value": "D", "text": "They should complete the same repetitive work indefinitely"}], "answer": "B", "explanation": "Gifted learners may need opportunities for depth, complexity, creativity and independent exploration."}, {"id": 429, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Reasonable accommodation in education means:", "options": [{"value": "A", "text": "Removing every learning objective"}, {"value": "B", "text": "Making appropriate adjustments to enable participation and access"}, {"value": "C", "text": "Giving all learners identical materials regardless of need"}, {"value": "D", "text": "Excluding learners who require support"}], "answer": "B", "explanation": "Reasonable accommodations help learners access education and demonstrate their learning."}, {"id": 430, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Inclusive Education And Special Needs", "question": "Which classroom environment best supports inclusion?", "options": [{"value": "A", "text": "One that discourages questions"}, {"value": "B", "text": "One that values diversity, participation and respect"}, {"value": "C", "text": "One that publicly ranks learners every day"}, {"value": "D", "text": "One that ignores accessibility"}], "answer": "B", "explanation": "Respectful, accessible classrooms promote belonging and equitable participation."}, {"id": 431, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "Assessment conducted during instruction to improve learning is called:", "options": [{"value": "A", "text": "Formative assessment"}, {"value": "B", "text": "Summative assessment"}, {"value": "C", "text": "Entrance examination only"}, {"value": "D", "text": "Final certification"}], "answer": "A", "explanation": "Formative assessment provides information that teachers and learners can use to improve learning while it is taking place."}, {"id": 432, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "An examination conducted at the end of a course to judge achievement is generally:", "options": [{"value": "A", "text": "Diagnostic assessment"}, {"value": "B", "text": "Summative assessment"}, {"value": "C", "text": "Informal observation only"}, {"value": "D", "text": "Peer discussion"}], "answer": "B", "explanation": "Summative assessment evaluates achievement at the end of a unit, course or learning period."}, {"id": 433, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "A teacher uses a pre-test to identify learners’ misconceptions before teaching. This is:", "options": [{"value": "A", "text": "Diagnostic assessment"}, {"value": "B", "text": "Summative assessment"}, {"value": "C", "text": "Punitive assessment"}, {"value": "D", "text": "Normative grading only"}], "answer": "A", "explanation": "Diagnostic assessment identifies prior knowledge, misconceptions and learning difficulties."}, {"id": 434, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "Which assessment tool is most suitable for observing a learner’s practical performance over time?", "options": [{"value": "A", "text": "Observation checklist"}, {"value": "B", "text": "Attendance register alone"}, {"value": "C", "text": "A single spelling test"}, {"value": "D", "text": "A seating chart"}], "answer": "A", "explanation": "A checklist helps a teacher systematically record whether specific behaviours or skills are demonstrated."}, {"id": 435, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "A rubric is primarily used to:", "options": [{"value": "A", "text": "Describe criteria and performance levels"}, {"value": "B", "text": "Record only attendance"}, {"value": "C", "text": "Replace every learning activity"}, {"value": "D", "text": "Prevent learners from receiving feedback"}], "answer": "A", "explanation": "Rubrics make expectations and performance standards clearer to learners and assessors."}, {"id": 436, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "Which feature is essential for a valid assessment?", "options": [{"value": "A", "text": "It measures the intended learning outcome"}, {"value": "B", "text": "It is always difficult"}, {"value": "C", "text": "It contains as many questions as possible"}, {"value": "D", "text": "It uses unfamiliar language unnecessarily"}], "answer": "A", "explanation": "Validity concerns whether an assessment measures what it is intended to measure."}, {"id": 437, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "Reliability in assessment refers to:", "options": [{"value": "A", "text": "Consistency of results under comparable conditions"}, {"value": "B", "text": "The colour of the question paper"}, {"value": "C", "text": "The length of the textbook"}, {"value": "D", "text": "The teacher’s popularity"}], "answer": "A", "explanation": "A reliable assessment produces reasonably consistent results when conditions are comparable."}, {"id": 438, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "Feedback is most effective when it is:", "options": [{"value": "A", "text": "Specific, constructive and linked to improvement"}, {"value": "B", "text": "Delayed indefinitely"}, {"value": "C", "text": "Focused on personal insults"}, {"value": "D", "text": "Limited to announcing marks"}], "answer": "A", "explanation": "Useful feedback tells learners what they did well, what needs improvement and how to proceed."}, {"id": 439, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "A portfolio is:", "options": [{"value": "A", "text": "A collection of a learner’s work showing progress over time"}, {"value": "B", "text": "A list of classroom rules only"}, {"value": "C", "text": "A final examination paper"}, {"value": "D", "text": "A teacher’s timetable"}], "answer": "A", "explanation": "Portfolios can document learning processes, achievement and development across time."}, {"id": 440, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Assessment And Evaluation", "question": "Which question assesses higher-order thinking most directly?", "options": [{"value": "A", "text": "Define evaporation."}, {"value": "B", "text": "List three states of matter."}, {"value": "C", "text": "Compare two methods and justify which is more effective."}, {"value": "D", "text": "Copy the textbook definition."}], "answer": "C", "explanation": "Comparing, evaluating and justifying require more complex thinking than simple recall."}, {"id": 441, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "The most important purpose of language teaching is to develop:", "options": [{"value": "A", "text": "Communication and language competence"}, {"value": "B", "text": "Copying speed alone"}, {"value": "C", "text": "Memorisation of grammar rules only"}, {"value": "D", "text": "Handwriting alone"}], "answer": "A", "explanation": "Language education develops listening, speaking, reading, writing and effective communication."}, {"id": 442, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Which activity best develops listening comprehension?", "options": [{"value": "A", "text": "Listening to a short story and answering questions"}, {"value": "B", "text": "Copying a paragraph silently"}, {"value": "C", "text": "Memorising a word list without context"}, {"value": "D", "text": "Writing numbers repeatedly"}], "answer": "A", "explanation": "Listening followed by comprehension tasks helps learners process and interpret spoken language."}, {"id": 443, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Which approach is most appropriate for developing speaking skills?", "options": [{"value": "A", "text": "Meaningful pair discussions and role-play"}, {"value": "B", "text": "Silent copying only"}, {"value": "C", "text": "Grammar translation in every activity"}, {"value": "D", "text": "Avoiding oral participation"}], "answer": "A", "explanation": "Interactive activities provide opportunities to practise spoken language in meaningful contexts."}, {"id": 444, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Reading for the main idea of a passage is known as:", "options": [{"value": "A", "text": "Skimming"}, {"value": "B", "text": "Scanning"}, {"value": "C", "text": "Dictation"}, {"value": "D", "text": "Proofreading"}], "answer": "A", "explanation": "Skimming involves reading quickly to understand the general idea or overall message."}, {"id": 445, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Reading to locate a specific date, name or number is called:", "options": [{"value": "A", "text": "Skimming"}, {"value": "B", "text": "Scanning"}, {"value": "C", "text": "Extensive reading"}, {"value": "D", "text": "Silent composition"}], "answer": "B", "explanation": "Scanning involves searching a text for particular information."}, {"id": 446, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Which practice best supports vocabulary development?", "options": [{"value": "A", "text": "Learning words in meaningful contexts"}, {"value": "B", "text": "Memorising isolated words without use"}, {"value": "C", "text": "Avoiding reading"}, {"value": "D", "text": "Correcting every spoken error immediately"}], "answer": "A", "explanation": "Context helps learners understand meanings, usage and relationships between words."}, {"id": 447, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "A learner makes grammatical errors while speaking but communicates the intended meaning. The teacher should generally:", "options": [{"value": "A", "text": "Encourage communication and provide appropriate feedback"}, {"value": "B", "text": "Stop the learner after every word"}, {"value": "C", "text": "Discourage all speaking"}, {"value": "D", "text": "Ignore language development completely"}], "answer": "A", "explanation": "A supportive classroom encourages fluency while helping learners improve accuracy."}, {"id": 448, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Which activity is most useful for developing writing through revision?", "options": [{"value": "A", "text": "Drafting, receiving feedback and editing"}, {"value": "B", "text": "Copying a final paragraph without thinking"}, {"value": "C", "text": "Avoiding written feedback"}, {"value": "D", "text": "Memorising punctuation marks only"}], "answer": "A", "explanation": "The writing process involves planning, drafting, revising, editing and presenting."}, {"id": 449, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Multilingualism in the classroom should generally be treated as:", "options": [{"value": "A", "text": "A potential learning resource"}, {"value": "B", "text": "A problem that must always be eliminated"}, {"value": "C", "text": "Evidence of poor intelligence"}, {"value": "D", "text": "A reason to exclude learners"}], "answer": "A", "explanation": "Learners’ home languages can support comprehension, identity and connections between languages."}, {"id": 450, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Language Pedagogy", "question": "Which is the best way to introduce a new language concept to young learners?", "options": [{"value": "A", "text": "Use meaningful examples, interaction and suitable visual support"}, {"value": "B", "text": "Begin with complex grammatical terminology alone"}, {"value": "C", "text": "Require extensive copying before explanation"}, {"value": "D", "text": "Avoid contextual examples"}], "answer": "A", "explanation": "Contextualised and age-appropriate teaching makes language concepts easier to understand."}, {"id": 451, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "A learner solves a mathematics problem using blocks before writing a numerical expression. This illustrates:", "options": [{"value": "A", "text": "Concrete-to-abstract learning"}, {"value": "B", "text": "Rote learning only"}, {"value": "C", "text": "Punishment-based learning"}, {"value": "D", "text": "Assessment without teaching"}], "answer": "A", "explanation": "Concrete materials can help learners understand mathematical ideas before moving to symbols."}, {"id": 452, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "Which is the best response when a learner gives an incorrect mathematical answer?", "options": [{"value": "A", "text": "Investigate the learner’s reasoning"}, {"value": "B", "text": "Immediately label the learner weak"}, {"value": "C", "text": "Ignore the answer"}, {"value": "D", "text": "Punish the learner for the mistake"}], "answer": "A", "explanation": "Errors can reveal misconceptions and guide the teacher’s next instructional steps."}, {"id": 453, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "Which activity best develops mathematical reasoning?", "options": [{"value": "A", "text": "Explaining why a solution works"}, {"value": "B", "text": "Copying answers without understanding"}, {"value": "C", "text": "Memorising every worked example without practice"}, {"value": "D", "text": "Avoiding problem-solving"}], "answer": "A", "explanation": "Justification helps learners develop logical thinking and conceptual understanding."}, {"id": 454, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "A child learns multiplication by arranging objects in equal rows and columns. This uses:", "options": [{"value": "A", "text": "An array model"}, {"value": "B", "text": "A punishment model"}, {"value": "C", "text": "A language drill"}, {"value": "D", "text": "A historical timeline"}], "answer": "A", "explanation": "Arrays represent multiplication as equal groups arranged in rows and columns."}, {"id": 455, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "Which practice best helps learners understand fractions?", "options": [{"value": "A", "text": "Using fraction strips and visual representations"}, {"value": "B", "text": "Memorising fraction rules without examples"}, {"value": "C", "text": "Avoiding comparisons"}, {"value": "D", "text": "Teaching only through lengthy definitions"}], "answer": "A", "explanation": "Visual models help learners compare fractions and understand parts of a whole."}, {"id": 456, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "A mathematics teacher asks learners to find different solutions to the same problem. This encourages:", "options": [{"value": "A", "text": "Flexible thinking"}, {"value": "B", "text": "Passive listening"}, {"value": "C", "text": "Single-method dependence"}, {"value": "D", "text": "Mechanical repetition only"}], "answer": "A", "explanation": "Exploring multiple strategies helps learners understand mathematical relationships and develop problem-solving flexibility."}, {"id": 457, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "Which tool is particularly useful for exploring geometrical shapes and transformations?", "options": [{"value": "A", "text": "Geoboard"}, {"value": "B", "text": "Attendance register"}, {"value": "C", "text": "Dictionary alone"}, {"value": "D", "text": "Historical map only"}], "answer": "A", "explanation": "A geoboard allows learners to construct and investigate shapes, angles and geometric relationships."}, {"id": 458, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "Formative assessment in mathematics can include:", "options": [{"value": "A", "text": "Exit tickets showing how learners solved a problem"}, {"value": "B", "text": "Final examination marks only"}, {"value": "C", "text": "Attendance alone"}, {"value": "D", "text": "Classroom decoration"}], "answer": "A", "explanation": "Exit tickets provide quick evidence of understanding and misconceptions."}, {"id": 459, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "Which question best encourages estimation?", "options": [{"value": "A", "text": "Is the answer exactly 247?"}, {"value": "B", "text": "About how many books might fit on this shelf? Explain your estimate."}, {"value": "C", "text": "Copy the number 247 ten times."}, {"value": "D", "text": "Memorise the multiplication table only."}], "answer": "B", "explanation": "Estimation involves making a reasonable approximation and explaining the basis for it."}, {"id": 460, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Mathematics Pedagogy", "question": "The primary purpose of teaching mathematics through real-life contexts is to:", "options": [{"value": "A", "text": "Help learners connect mathematical concepts with everyday situations"}, {"value": "B", "text": "Eliminate abstract thinking permanently"}, {"value": "C", "text": "Avoid mathematical reasoning"}, {"value": "D", "text": "Replace all calculations with stories"}], "answer": "A", "explanation": "Real-life contexts can make mathematics meaningful and support transfer of learning."}, {"id": 461, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "Which activity best reflects the scientific method?", "options": [{"value": "A", "text": "Making observations, forming hypotheses and testing them"}, {"value": "B", "text": "Accepting every statement without evidence"}, {"value": "C", "text": "Memorising results without investigation"}, {"value": "D", "text": "Avoiding questions"}], "answer": "A", "explanation": "Scientific investigation uses evidence and systematic methods to examine questions."}, {"id": 462, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "In an experiment, the variable deliberately changed by the investigator is the:", "options": [{"value": "A", "text": "Independent variable"}, {"value": "B", "text": "Dependent variable"}, {"value": "C", "text": "Constant"}, {"value": "D", "text": "Measurement error"}], "answer": "A", "explanation": "The independent variable is the factor deliberately changed to examine its effect."}, {"id": 463, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "The variable measured as an outcome in an experiment is the:", "options": [{"value": "A", "text": "Independent variable"}, {"value": "B", "text": "Dependent variable"}, {"value": "C", "text": "Constant"}, {"value": "D", "text": "Control condition only"}], "answer": "B", "explanation": "The dependent variable is the measured outcome that may respond to changes in the independent variable."}, {"id": 464, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "Why should learners repeat an experiment when appropriate?", "options": [{"value": "A", "text": "To improve confidence in the consistency of results"}, {"value": "B", "text": "To guarantee that the hypothesis is correct"}, {"value": "C", "text": "To avoid recording data"}, {"value": "D", "text": "To make the experiment longer without purpose"}], "answer": "A", "explanation": "Repetition helps identify unusual results and assess whether findings are consistent."}, {"id": 465, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "Which practice best develops scientific curiosity?", "options": [{"value": "A", "text": "Encouraging learners to ask questions and investigate evidence"}, {"value": "B", "text": "Discouraging all questions"}, {"value": "C", "text": "Providing conclusions without discussion in every lesson"}, {"value": "D", "text": "Punishing learners for uncertainty"}], "answer": "A", "explanation": "Curiosity and inquiry are important parts of scientific learning."}, {"id": 466, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "A teacher demonstrates how water evaporates and asks learners to record observations. This is an example of:", "options": [{"value": "A", "text": "Demonstration with observation"}, {"value": "B", "text": "Rote memorisation alone"}, {"value": "C", "text": "Summative grading"}, {"value": "D", "text": "Silent reading only"}], "answer": "A", "explanation": "Demonstrations allow learners to observe processes and connect evidence with scientific concepts."}, {"id": 467, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "Which of the following is a renewable energy source?", "options": [{"value": "A", "text": "Coal"}, {"value": "B", "text": "Petroleum"}, {"value": "C", "text": "Solar energy"}, {"value": "D", "text": "Natural gas"}], "answer": "C", "explanation": "Solar energy is continually replenished by sunlight, unlike fossil fuels."}, {"id": 468, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "Which classroom activity best develops environmental awareness?", "options": [{"value": "A", "text": "Conducting a school waste audit and planning improvements"}, {"value": "B", "text": "Memorising environmental terms without application"}, {"value": "C", "text": "Ignoring litter around the school"}, {"value": "D", "text": "Using more disposable materials without discussion"}], "answer": "A", "explanation": "Local investigations connect environmental concepts with practical action."}, {"id": 469, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "Which safety practice is appropriate during a school science experiment?", "options": [{"value": "A", "text": "Following instructions and using suitable protective equipment"}, {"value": "B", "text": "Tasting unknown substances"}, {"value": "C", "text": "Mixing chemicals without guidance"}, {"value": "D", "text": "Running around the laboratory"}], "answer": "A", "explanation": "Laboratory safety requires following procedures, using appropriate equipment and avoiding unsafe handling."}, {"id": 470, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Science Pedagogy", "question": "A learner revises a hypothesis after observing contradictory evidence. This demonstrates:", "options": [{"value": "A", "text": "Scientific reasoning"}, {"value": "B", "text": "Blind acceptance"}, {"value": "C", "text": "Fixed thinking"}, {"value": "D", "text": "Memorisation without understanding"}], "answer": "A", "explanation": "Scientific thinking involves using evidence to evaluate and revise explanations."}, {"id": 471, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which teaching resource is most suitable for helping learners understand geographical location?", "options": [{"value": "A", "text": "Map"}, {"value": "B", "text": "Dictionary alone"}, {"value": "C", "text": "Poetry notebook"}, {"value": "D", "text": "Attendance sheet"}], "answer": "A", "explanation": "Maps represent spatial information and help learners understand locations and geographical relationships."}, {"id": 472, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "A timeline is particularly useful for teaching:", "options": [{"value": "A", "text": "Chronological sequence of historical events"}, {"value": "B", "text": "Chemical reactions only"}, {"value": "C", "text": "Geometrical transformations only"}, {"value": "D", "text": "Pronunciation patterns only"}], "answer": "A", "explanation": "Timelines show the order and relative timing of events."}, {"id": 473, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which activity best develops historical thinking?", "options": [{"value": "A", "text": "Comparing primary and secondary sources"}, {"value": "B", "text": "Memorising dates without context"}, {"value": "C", "text": "Avoiding evidence"}, {"value": "D", "text": "Treating every source as equally reliable"}], "answer": "A", "explanation": "Analysing sources helps learners evaluate evidence, context and differing interpretations."}, {"id": 474, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which is an example of a primary historical source?", "options": [{"value": "A", "text": "A diary written by a person who experienced an event"}, {"value": "B", "text": "A modern textbook summary of the event"}, {"value": "C", "text": "A recent study guide"}, {"value": "D", "text": "A teacher’s revision notes"}], "answer": "A", "explanation": "Primary sources originate from the period or people being studied, although they still need critical evaluation."}, {"id": 475, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "The main purpose of teaching civics is to help learners understand:", "options": [{"value": "A", "text": "Citizenship, rights, responsibilities and democratic processes"}, {"value": "B", "text": "Mathematical formulas only"}, {"value": "C", "text": "Grammar rules only"}, {"value": "D", "text": "Laboratory procedures only"}], "answer": "A", "explanation": "Civics develops understanding of public institutions, citizenship and participation in society."}, {"id": 476, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which activity best promotes democratic values in the classroom?", "options": [{"value": "A", "text": "Giving learners opportunities to discuss and make decisions respectfully"}, {"value": "B", "text": "Allowing only one learner to speak"}, {"value": "C", "text": "Punishing disagreement automatically"}, {"value": "D", "text": "Preventing participation"}], "answer": "A", "explanation": "Participation, dialogue and respect for differing views help learners practise democratic behaviour."}, {"id": 477, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which is the best example of a field-based learning activity in geography?", "options": [{"value": "A", "text": "Observing land use in the local area"}, {"value": "B", "text": "Copying definitions for the entire lesson"}, {"value": "C", "text": "Memorising place names without maps"}, {"value": "D", "text": "Avoiding outdoor observation"}], "answer": "A", "explanation": "Fieldwork helps learners connect geographical concepts with real places and evidence."}, {"id": 478, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Sustainable development seeks to:", "options": [{"value": "A", "text": "Meet present needs while safeguarding future generations’ ability to meet theirs"}, {"value": "B", "text": "Use all natural resources immediately"}, {"value": "C", "text": "Ignore environmental consequences"}, {"value": "D", "text": "Prevent all economic activity"}], "answer": "A", "explanation": "Sustainability balances environmental protection, social well-being and economic considerations."}, {"id": 479, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which approach best helps learners understand local community issues?", "options": [{"value": "A", "text": "Investigating the issue through interviews, observation and evidence"}, {"value": "B", "text": "Memorising an unrelated definition"}, {"value": "C", "text": "Avoiding community perspectives"}, {"value": "D", "text": "Accepting rumours as facts"}], "answer": "A", "explanation": "Local inquiry encourages evidence-based understanding and active citizenship."}, {"id": 480, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Social Science And Environmental Studies", "question": "Which resource is particularly useful for comparing population patterns across regions?", "options": [{"value": "A", "text": "Population distribution map"}, {"value": "B", "text": "Alphabet chart"}, {"value": "C", "text": "Musical instrument"}, {"value": "D", "text": "Handwriting worksheet"}], "answer": "A", "explanation": "Population maps help learners identify spatial patterns and compare regions."}, {"id": 481, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Which teacher behaviour best demonstrates professional ethics?", "options": [{"value": "A", "text": "Treating learners fairly and respecting confidentiality"}, {"value": "B", "text": "Sharing learners’ private information publicly"}, {"value": "C", "text": "Showing favouritism"}, {"value": "D", "text": "Humiliating learners for mistakes"}], "answer": "A", "explanation": "Professional ethics include fairness, dignity, responsibility and appropriate confidentiality."}, {"id": 482, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "A teacher reflects on a lesson to identify what worked and what needs improvement. This is:", "options": [{"value": "A", "text": "Reflective practice"}, {"value": "B", "text": "Punitive discipline"}, {"value": "C", "text": "Rote teaching"}, {"value": "D", "text": "Summative grading"}], "answer": "A", "explanation": "Reflective practice helps teachers evaluate their decisions and improve future teaching."}, {"id": 483, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Which strategy is most effective for preventing many classroom management problems?", "options": [{"value": "A", "text": "Establishing clear expectations and engaging learning activities"}, {"value": "B", "text": "Giving unclear instructions"}, {"value": "C", "text": "Using threats as the main teaching method"}, {"value": "D", "text": "Ignoring learners’ needs"}], "answer": "A", "explanation": "Predictable routines and meaningful engagement can reduce confusion and disruptive behaviour."}, {"id": 484, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "When two learners have a disagreement, the teacher should generally:", "options": [{"value": "A", "text": "Listen to both sides and guide a fair resolution"}, {"value": "B", "text": "Punish one learner without investigation"}, {"value": "C", "text": "Ignore every conflict"}, {"value": "D", "text": "Encourage classmates to take sides"}], "answer": "A", "explanation": "Fair conflict resolution involves listening, understanding the issue and supporting respectful solutions."}, {"id": 485, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Which practice best supports communication with parents or caregivers?", "options": [{"value": "A", "text": "Sharing specific observations and discussing ways to support learning"}, {"value": "B", "text": "Contacting them only to blame the learner"}, {"value": "C", "text": "Comparing their child publicly with others"}, {"value": "D", "text": "Avoiding all communication"}], "answer": "A", "explanation": "Constructive communication builds collaboration between school and home."}, {"id": 486, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Continuing professional development helps teachers to:", "options": [{"value": "A", "text": "Update knowledge and improve teaching practice"}, {"value": "B", "text": "Avoid learning new methods"}, {"value": "C", "text": "Replace all classroom experience"}, {"value": "D", "text": "Stop reflecting on their work"}], "answer": "A", "explanation": "Professional development supports continuing growth in subject knowledge, pedagogy and assessment."}, {"id": 487, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Which is the most appropriate response to bullying?", "options": [{"value": "A", "text": "Take the concern seriously and follow safeguarding procedures"}, {"value": "B", "text": "Tell the learner to accept it"}, {"value": "C", "text": "Publicly blame the affected learner"}, {"value": "D", "text": "Ignore repeated incidents"}], "answer": "A", "explanation": "Schools should respond promptly, protect learners and follow appropriate reporting and support procedures."}, {"id": 488, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "A teacher notices that some learners rarely participate. What is a suitable response?", "options": [{"value": "A", "text": "Offer varied participation methods and create a supportive environment"}, {"value": "B", "text": "Assume they have no ideas"}, {"value": "C", "text": "Force public speaking in every situation"}, {"value": "D", "text": "Stop asking them questions permanently"}], "answer": "A", "explanation": "Pair work, written responses, small groups and wait time can provide different ways to participate."}, {"id": 489, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Which practice demonstrates responsible use of digital learning resources?", "options": [{"value": "A", "text": "Checking reliability, privacy and accessibility"}, {"value": "B", "text": "Sharing learners’ personal data without permission"}, {"value": "C", "text": "Accepting every online claim as accurate"}, {"value": "D", "text": "Ignoring copyright"}], "answer": "A", "explanation": "Teachers should consider credibility, learner safety, privacy, accessibility and responsible use."}, {"id": 490, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Teacher Professionalism And Classroom Management", "question": "Which classroom practice best promotes learner autonomy?", "options": [{"value": "A", "text": "Helping learners set goals and monitor their progress"}, {"value": "B", "text": "Making every decision without learner involvement"}, {"value": "C", "text": "Preventing self-assessment"}, {"value": "D", "text": "Requiring learners to depend on the teacher for every step"}], "answer": "A", "explanation": "Learner autonomy grows when students take increasing responsibility for their learning."}, {"id": 491, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "Action research conducted by a teacher is primarily intended to:", "options": [{"value": "A", "text": "Investigate and improve a local teaching or learning problem"}, {"value": "B", "text": "Replace all curriculum requirements"}, {"value": "C", "text": "Prove that the teacher is always correct"}, {"value": "D", "text": "Avoid collecting evidence"}], "answer": "A", "explanation": "Action research uses systematic inquiry to improve practice in a specific educational context."}, {"id": 492, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "A teacher introduces a new reading strategy and compares learners’ performance before and after its use. This is an example of:", "options": [{"value": "A", "text": "Classroom-based inquiry"}, {"value": "B", "text": "Random guessing"}, {"value": "C", "text": "Purely administrative record-keeping"}, {"value": "D", "text": "Unstructured punishment"}], "answer": "A", "explanation": "Collecting evidence before and after an intervention can help a teacher examine its possible effects, while considering other factors."}, {"id": 493, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "Which is the strongest reason to use more than one source of evidence when evaluating a teaching strategy?", "options": [{"value": "A", "text": "Different sources may provide complementary information"}, {"value": "B", "text": "More sources guarantee a positive result"}, {"value": "C", "text": "Evidence is unnecessary when opinions are strong"}, {"value": "D", "text": "Different sources should always produce identical findings"}], "answer": "A", "explanation": "Combining observations, assessments and learner feedback can give a fuller picture of classroom learning."}, {"id": 494, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "A teacher wants to know whether learners understand a new concept during the lesson. Which method is most suitable?", "options": [{"value": "A", "text": "Asking targeted questions and examining learners’ responses"}, {"value": "B", "text": "Waiting until the next academic year"}, {"value": "C", "text": "Checking attendance only"}, {"value": "D", "text": "Assuming silence means understanding"}], "answer": "A", "explanation": "Questioning and response analysis provide immediate evidence of understanding and misconceptions."}, {"id": 495, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "Which is the clearest example of evidence-based teaching?", "options": [{"value": "A", "text": "Adapting instruction using relevant assessment evidence and research"}, {"value": "B", "text": "Using a method only because it is fashionable"}, {"value": "C", "text": "Ignoring learners’ responses"}, {"value": "D", "text": "Refusing to review teaching outcomes"}], "answer": "A", "explanation": "Evidence-based teaching draws on research, assessment information, professional judgement and learners’ needs."}, {"id": 496, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "A learner can recall a definition but cannot apply it to a real situation. What should the teacher emphasise?", "options": [{"value": "A", "text": "Application tasks and contextual examples"}, {"value": "B", "text": "More copying of the same definition only"}, {"value": "C", "text": "Avoiding practical examples"}, {"value": "D", "text": "Removing all questions"}], "answer": "A", "explanation": "Applying knowledge in different contexts helps learners move beyond recall towards understanding and transfer."}, {"id": 497, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "Which question is most suitable for evaluating a proposed solution?", "options": [{"value": "A", "text": "What evidence supports this solution, and what are its limitations?"}, {"value": "B", "text": "Can you repeat the title?"}, {"value": "C", "text": "How many words are in the question?"}, {"value": "D", "text": "Can you copy the first sentence?"}], "answer": "A", "explanation": "Evaluation requires judging the quality, evidence and limitations of an idea or solution."}, {"id": 498, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "A teacher changes a lesson after discovering that learners misunderstood a key idea. This demonstrates:", "options": [{"value": "A", "text": "Responsive teaching"}, {"value": "B", "text": "Fixed lesson delivery"}, {"value": "C", "text": "Punishment-based learning"}, {"value": "D", "text": "Assessment avoidance"}], "answer": "A", "explanation": "Responsive teaching adapts instruction to learners’ demonstrated needs and understanding."}, {"id": 499, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "Which approach best encourages metacognition?", "options": [{"value": "A", "text": "Asking learners to explain how they solved a problem and what they would change"}, {"value": "B", "text": "Giving answers without discussion"}, {"value": "C", "text": "Preventing reflection"}, {"value": "D", "text": "Requiring copying without explanation"}], "answer": "A", "explanation": "Metacognition involves thinking about and regulating one’s own thinking and learning processes."}, {"id": 500, "part": 5, "partName": "Part 5", "partSubject": "Educational Psychology, Learning Theories, Inclusive Education, Teaching Methods, Assessment, Language Pedagogy, Mathematics, Science, Social Science and Classroom Practice", "section": "Research, Reasoning And Application", "question": "Which statement best describes the role of a teacher in a learner-centred classroom?", "options": [{"value": "A", "text": "Sole provider of all knowledge"}, {"value": "B", "text": "Facilitator who guides, supports and challenges learners"}, {"value": "C", "text": "Passive observer who never intervenes"}, {"value": "D", "text": "Examiner whose only responsibility is grading"}], "answer": "B", "explanation": "In learner-centred education, teachers design meaningful experiences, guide inquiry, provide feedback and support learner development."}];
